const DOM_TRANSACTION_MAX_LEN: usize = 1024 * 1024;
const FUNDING_ARTIFACT_MAX_LEN: usize =
    ARTIFACT_PREFIX_LEN + DOM_TRANSACTION_MAX_LEN * 2 + DIGEST_LEN;

