enum ConsumedFundingCommitV1 {
    Legacy(OperationalFundingCommitRecordV1),
    M8(OperationalM8FundingCommitRecordV1),
    M8V2(OperationalM8FundingCommitRecordV2),
}

struct ConsumedFundingPublicationV1 {
    commit: ConsumedFundingCommitV1,
    publish_artifact: bool,
    publish_consumption: bool,
}

