    /// Persists a Store-issued outbound request for one exact prepared M.8
    /// `ReadyToFund` vote (`0x11`). A remote canonical voter returns `None`
    /// without creating a request.
    pub fn prepare_m8_ready_to_fund_dsc1_signing_request(
        &self,
        gate: &PreparedOperationalM8FundingGateV1,
        vote: PreparedOperationalM8ReadyToFundVoteV1,
    ) -> Result<Option<PreparedDsc1SigningRequestV1>, SessionStoreError> {
        self.require_legacy_v1_non_productive_profile()?;
        let _guard = self.operation_lock()?;
        let expected = self
            .prepare_next_operational_m8_ready_to_fund_vote_locked(gate)?
            .ok_or(SessionStoreError::FundingAuthorityUnavailable)?;
        if vote.session_id != expected.session_id
            || vote.participant_id != expected.participant_id
            || vote.sequence != expected.sequence
            || vote.previous_transcript_hash != expected.previous_transcript_hash
            || vote.payload != expected.payload
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let signer = self.authenticate_local_transport_signer_binding(vote.session_id)?;
        if signer.participant_id != vote.participant_id {
            return Ok(None);
        }
        let retained_gate = self.load_m8_funding_gate(vote.session_id)?;
        let current = self.load_session_locked(vote.session_id)?;
        self.require_m8_final_refund_provenance(&retained_gate, &current)?;
        self.issue_outbound_dsc1_request_locked(OutboundDsc1RequestIssueV1 {
            authority_class: OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFund,
            chain_id: retained_gate.chain_id,
            session_id: vote.session_id,
            sender_id: vote.participant_id,
            sequence: vote.sequence,
            previous_transcript_hash: vote.previous_transcript_hash,
            predecessor: &current,
            authority_digest: retained_gate.digest,
            payload: &vote.payload,
        })
        .map(Some)
    }

