    /// Reauthenticates a live Store-issued signing request immediately before
    /// the independent identity keystore uses its opaque key reference.
    pub fn revalidate_prepared_outbound_dsc1(
        &self,
        request: &PreparedDsc1SigningRequestV1,
    ) -> Result<(), SessionStoreError> {
        let _guard = self.operation_lock()?;
        let retained = self.authenticate_prepared_outbound_dsc1_handle_locked(request)?;
        self.require_non_productive_legacy_v1_outbound_class(retained.authority_class)?;
        match self.load_committed_outbound_dsc1(
            retained.session_id,
            retained.sender_id,
            retained.sequence,
        ) {
            Ok(_) => return Err(SessionStoreError::InvalidTransition),
            Err(SessionStoreError::SessionNotFound) => {}
            Err(error) => return Err(error),
        }
        self.revalidate_outbound_dsc1_request_locked(&retained, false)
    }

    /// Authenticates and commits the exact identity-signed bytes for one
    /// Store-issued request before returning a relayable handle.
    pub fn commit_prepared_outbound_dsc1(
        &self,
        request: PreparedDsc1SigningRequestV1,
        signed_bytes: &[u8],
    ) -> Result<CommittedOutboundDsc1V1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let retained = self.authenticate_prepared_outbound_dsc1_handle_locked(&request)?;
        match self.load_committed_outbound_dsc1(
            retained.session_id,
            retained.sender_id,
            retained.sequence,
        ) {
            Ok(committed) => {
                self.authenticate_committed_outbound_dsc1_record_locked(&committed, &retained)?;
                return if committed.signed_bytes == signed_bytes {
                    Ok(committed.issued_handle(self.open_instance_id))
                } else {
                    Err(SessionStoreError::Conflict)
                };
            }
            Err(SessionStoreError::SessionNotFound) => {}
            Err(error) => return Err(error),
        }
        self.require_non_productive_legacy_v1_outbound_class(retained.authority_class)?;
        self.revalidate_outbound_dsc1_request_locked(&retained, true)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        let signer = self.authenticate_local_transport_signer_binding(retained.session_id)?;
        if envelope.chain_id != retained.chain_id
            || envelope.session_id != retained.session_id
            || envelope.sender_id != retained.sender_id
            || envelope.sequence != retained.sequence
            || envelope.previous_transcript_hash != retained.previous_transcript_hash
            || envelope.message_type != retained.message_type
            || envelope.message_digest != retained.unsigned_message_digest
            || envelope.payload(signed_bytes)? != retained.payload
            || signer.participant_id != retained.sender_id
            || signer.key_reference != retained.signer_key_reference
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        envelope.verify(&signer.schnorr_public_key)?;

        let accepted_name = transport_message_name(
            retained.session_id,
            retained.sender_id,
            retained.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&accepted_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
                self.authenticate_transport_record(&accepted_name, &accepted)?;
                if accepted.signed_bytes != signed_bytes {
                    return Err(SessionStoreError::Conflict);
                }
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }

        let predecessor =
            self.load_session_revision(retained.session_id, retained.predecessor_revision)?;
        if predecessor.digest() != &retained.predecessor_record_digest {
            return Err(SessionStoreError::Quarantined);
        }
        let roster = self.load_transport_roster(retained.session_id)?;
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == retained.sender_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let phase = match retained.authority_class {
            authority_class
                if authority_class.is_early()
                    || authority_class.is_operational_bp()
                    || authority_class
                        == OutboundDsc1AuthorityClassV1::OperationalTemplateCommit
                    || authority_class.is_operational_signing() =>
            {
                self.require_outbound_dsc1_request_transition_locked(
                    &retained,
                    &predecessor,
                    &envelope,
                    signed_bytes,
                )?
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignature
            | OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignatureV2 => {
                SessionPhaseV1::FundingConfirmed
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalRefund => SessionPhaseV1::RefundSigned,
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFund
            | OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFundV2 => {
                SessionPhaseV1::RefundSigned
            }
            // The arm class 20 was missing when it first landed, which made
            // every commit of that class an invalid transition. Class 21 is
            // spelled here at the same time as the enum variant.
            OutboundDsc1AuthorityClassV1::OperationalFinalClaimV2 => SessionPhaseV1::ClaimBroadcast,
            OutboundDsc1AuthorityClassV1::OperationalAbort => SessionPhaseV1::Aborted,
            _ => return Err(SessionStoreError::InvalidTransition),
        };
        let transcript_hash = accepted_transport_transcript_hash(
            &predecessor.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            phase,
        )?;
        let successor = predecessor.advance(
            predecessor.revision(),
            phase,
            transcript_hash,
            predecessor.irreversible(),
            predecessor.chain(),
            predecessor.encrypted_payload(),
        )?;
        let current = self.load_session_locked(retained.session_id)?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        match self.accept_transport_message_with_successor_locked(
            signed_bytes,
            &successor,
            Some(&failed),
        )? {
            DurableTransportOutcomeV1::Accepted(receipt)
                if receipt.message_digest == retained.unsigned_message_digest
                    && receipt.sequence == retained.sequence
                    && receipt.message_type == retained.message_type => {}
            DurableTransportOutcomeV1::Accepted(_)
            | DurableTransportOutcomeV1::EquivocationPersisted => {
                return Err(SessionStoreError::Conflict)
            }
        }
        test_crash_hook("outbound-dsc1-after-message-persist");
        let committed = CommittedOutboundDsc1RecordV1::new(&retained, signed_bytes)?;
        self.persist_committed_outbound_dsc1(&committed)?;
        test_crash_hook("outbound-dsc1-after-commit-persist");
        let durable = self.load_committed_outbound_dsc1(
            retained.session_id,
            retained.sender_id,
            retained.sequence,
        )?;
        self.authenticate_committed_outbound_dsc1_record_locked(&durable, &retained)?;
        if durable.bytes != committed.bytes {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(durable.issued_handle(self.open_instance_id))
    }

    /// Reauthenticates one committed outbound handle and its exact retained
    /// request, signed bytes, transport message, and durable successor.
    pub fn revalidate_committed_outbound_dsc1(
        &self,
        outbound: &CommittedOutboundDsc1V1,
    ) -> Result<(), SessionStoreError> {
        let _guard = self.operation_lock()?;
        if outbound.open_instance_id != self.open_instance_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let committed = self.load_committed_outbound_dsc1(
            outbound.session_id,
            outbound.sender_id,
            outbound.sequence,
        )?;
        if committed.application_id != outbound.application_id
            || committed.message_digest != outbound.message_digest
            || committed.signed_bytes != outbound.signed_bytes
            || committed.request_id != outbound.request_id
            || committed.digest != outbound.committed_record_digest
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let request = self.load_outbound_dsc1_request(
            committed.session_id,
            committed.sender_id,
            committed.sequence,
        )?;
        self.authenticate_committed_outbound_dsc1_record_locked(&committed, &request)
    }

    /// Durably records that the Relay sender reconciled one exact Store-owned
    /// application before allowing recovery to advance past it.
    ///
    /// The opaque committed handle is consumed and must belong to this exact
    /// Store opening. Repeating the same durable handoff is idempotent; any
    /// application, request, commit, message, or logical-key divergence fails
    /// closed. The owner-only marker is fsynced and read back before success.
    pub fn complete_outbound_dsc1_relay_handoff(
        &self,
        outbound: CommittedOutboundDsc1V1,
    ) -> Result<(), SessionStoreError> {
        let _guard = self.operation_lock()?;
        if outbound.open_instance_id != self.open_instance_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let committed = self.load_committed_outbound_dsc1(
            outbound.session_id,
            outbound.sender_id,
            outbound.sequence,
        )?;
        if committed.application_id != outbound.application_id
            || committed.message_digest != outbound.message_digest
            || committed.signed_bytes != outbound.signed_bytes
            || committed.request_id != outbound.request_id
            || committed.digest != outbound.committed_record_digest
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let request = self.load_outbound_dsc1_request(
            committed.session_id,
            committed.sender_id,
            committed.sequence,
        )?;
        self.authenticate_committed_outbound_dsc1_record_locked(&committed, &request)?;
        let expected = ReconciledOutboundDsc1RecordV1::new(&request, &committed)?;
        match self.load_reconciled_outbound_dsc1(
            committed.session_id,
            committed.sender_id,
            committed.sequence,
        ) {
            Ok(retained) => {
                self.authenticate_reconciled_outbound_dsc1_record_locked(
                    &retained, &committed, &request,
                )?;
                return if retained.bytes == expected.bytes {
                    Ok(())
                } else {
                    Err(SessionStoreError::Conflict)
                };
            }
            Err(SessionStoreError::SessionNotFound) => {}
            Err(error) => return Err(error),
        }
        self.persist_reconciled_outbound_dsc1(&expected)?;
        test_crash_hook("outbound-dsc1-after-relay-handoff-persist");
        let durable = self.load_reconciled_outbound_dsc1(
            committed.session_id,
            committed.sender_id,
            committed.sequence,
        )?;
        self.authenticate_reconciled_outbound_dsc1_record_locked(&durable, &committed, &request)?;
        if durable.bytes != expected.bytes {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(())
    }

    /// Recovers the earliest uncommitted request, healing an accepted
    /// crash-cut into a committed record first, or returns a committed message
    /// for byte-identical relay retry. No new outbound message is created.
    pub fn resume_outbound_dsc1(
        &self,
        session_id: [u8; 32],
    ) -> Result<OutboundDsc1RecoveryV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        self.load_session_locked(session_id)?;
        let prefix = format!("{}-", hex_lower(&session_id));
        let mut requests = Vec::new();
        self.rosters.scan_lexicographic(|name, node| {
            if node.node_type != ExpectedNodeType::RegularFile || name.starts_with('.') {
                return Err(LinuxCapabilityError::InvalidObject);
            }
            let Some((parsed_session, sender, sequence, committed)) =
                parse_outbound_dsc1_name(name)
            else {
                return Ok(());
            };
            if name.starts_with(&prefix) && parsed_session == session_id && !committed {
                let request = self
                    .load_outbound_dsc1_request(parsed_session, sender, sequence)
                    .map_err(|_| LinuxCapabilityError::ExactBytesMismatch)?;
                requests.push(request);
            }
            Ok(())
        })?;
        requests.sort_by_key(|request| {
            (
                request.predecessor_revision,
                request.sender_id,
                request.sequence,
            )
        });
        let mut first_committed = None;
        for request in requests {
            let reconciled = match self.load_reconciled_outbound_dsc1(
                request.session_id,
                request.sender_id,
                request.sequence,
            ) {
                Ok(reconciled) => Some(reconciled),
                Err(SessionStoreError::SessionNotFound) => None,
                Err(error) => return Err(error),
            };
            match self.load_committed_outbound_dsc1(
                request.session_id,
                request.sender_id,
                request.sequence,
            ) {
                Ok(committed) => {
                    self.authenticate_committed_outbound_dsc1_record_locked(&committed, &request)?;
                    if let Some(reconciled) = reconciled.as_ref() {
                        self.authenticate_reconciled_outbound_dsc1_record_locked(
                            reconciled, &committed, &request,
                        )?;
                        continue;
                    }
                    first_committed.get_or_insert(committed);
                }
                Err(SessionStoreError::SessionNotFound) => {
                    if reconciled.is_some() {
                        return Err(SessionStoreError::Quarantined);
                    }
                    let accepted_name = transport_message_name(
                        request.session_id,
                        request.sender_id,
                        request.sequence,
                        false,
                    );
                    match self.messages.read_bounded_file(
                        &ValidatedComponent::registered(&accepted_name)?,
                        TRANSPORT_MESSAGE_MAX_LEN,
                    ) {
                        Ok(bytes) => {
                            let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
                            self.authenticate_transport_record(&accepted_name, &accepted)?;
                            self.require_signed_envelope_matches_outbound_request(
                                &request,
                                &accepted.signed_bytes,
                            )?;
                            let committed = CommittedOutboundDsc1RecordV1::new(
                                &request,
                                &accepted.signed_bytes,
                            )?;
                            self.persist_committed_outbound_dsc1(&committed)?;
                            let durable = self.load_committed_outbound_dsc1(
                                request.session_id,
                                request.sender_id,
                                request.sequence,
                            )?;
                            self.authenticate_committed_outbound_dsc1_record_locked(
                                &durable, &request,
                            )?;
                            return Ok(OutboundDsc1RecoveryV1::Committed(Box::new(
                                durable.issued_handle(self.open_instance_id),
                            )));
                        }
                        Err(LinuxCapabilityError::NotFound) => {
                            self.require_non_productive_legacy_v1_outbound_class(
                                request.authority_class,
                            )?;
                            self.revalidate_outbound_dsc1_request_locked(&request, false)?;
                            return Ok(OutboundDsc1RecoveryV1::SigningRequest(Box::new(
                                request.issued_handle(self.open_instance_id),
                            )));
                        }
                        Err(error) => return Err(error.into()),
                    }
                }
                Err(error) => return Err(error),
            }
        }
        Ok(match first_committed {
            Some(committed) => OutboundDsc1RecoveryV1::Committed(Box::new(
                committed.issued_handle(self.open_instance_id),
            )),
            None => OutboundDsc1RecoveryV1::None,
        })
    }

    /// Persist and issue the exact authority for DSC1 `Offer`, `Accept`,
    /// `ShareCommit`, and `ShareReveal`.
    ///
    /// Both supplied bindings must describe the same trusted chain, session,
    /// canonical participant-ID roster, terms and recovery capsule; each must
    /// also match its participant's role and public point in the retained
    /// transport roster. The resulting immutable context is installed before
    /// the first message. Reissuing after restart requires byte-identical
    /// authenticated inputs and never creates a replacement context.
    pub fn prepare_early_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        shared_blinding_bindings: [&SharedBlindingBindingV1; 2],
    ) -> Result<PreparedEarlyTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let session_id = *shared_blinding_bindings[0].session_id();
        let current = self.load_session_locked(session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed {
            return Err(SessionStoreError::InvalidTransition);
        }
        let initial = self.load_session_revision(session_id, 0)?;
        let roster = self.load_transport_roster(session_id)?;
        let identities = self.load_transport_identity_binding(session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        let expected = EarlyTransportAuthorityRecordV1::new(
            &initial,
            &roster,
            &trusted_chain_id,
            shared_blinding_bindings,
        )?;
        let durable = match self.load_early_transport_authority(session_id) {
            Ok(existing) => {
                if existing.bytes != expected.bytes {
                    return Err(SessionStoreError::Conflict);
                }
                existing
            }
            Err(SessionStoreError::SessionNotFound) => {
                if current.revision() != 0
                    || current.phase() != SessionPhaseV1::Created
                    || self.transport_message_count(session_id)? != 0
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                self.persist_early_transport_authority(&expected)?;
                test_crash_hook("early-transport-after-authority-persist");
                let persisted = self.load_early_transport_authority(session_id)?;
                if persisted.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                persisted
            }
            Err(error) => return Err(error),
        };
        self.require_live_early_transport_authority(&durable, &initial, &roster)?;
        Ok(PreparedEarlyTransportAuthorityV1 {
            session_id,
            authority_digest: durable.digest,
            context_commitment: durable.context_commitment,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accept one new or repeated prepared DSC1 `0x01`–`0x04` message.
    ///
    /// The Store authenticates the envelope, reloads the immutable prepared
    /// context, derives the next sender/type/phase internally, verifies the
    /// exact terms acknowledgement or share PoK, and only then journals the
    /// successor. A same-key byte conflict persists `FailedClosed`. The
    /// generic derived ingress remains unavailable for unseen messages.
    pub fn accept_prepared_early_transport_message(
        &self,
        authority: &PreparedEarlyTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let prepared = self.authenticate_prepared_early_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != prepared.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let current = self.load_session_locked(envelope.session_id)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let retained = TransportMessageRecordV1::from_bytes(&bytes)?;
                if retained.signed_bytes == signed_bytes {
                    return self.accept_transport_message_with_successor_locked(
                        signed_bytes,
                        &current,
                        None,
                    );
                }
                let failed = current.advance(
                    current.revision(),
                    SessionPhaseV1::FailedClosed,
                    current.transcript_hash(),
                    current.irreversible(),
                    current.chain(),
                    current.encrypted_payload(),
                )?;
                return self.accept_transport_message_with_successor_locked(
                    signed_bytes,
                    &current,
                    Some(&failed),
                );
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if !(0x01..=0x04).contains(&envelope.message_type) {
            return Err(SessionStoreError::InvalidTransition);
        }
        let phase = self.require_next_prepared_early_transport_message(
            &prepared,
            &current,
            &roster,
            &envelope,
            signed_bytes,
        )?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            phase,
        )?;
        let successor = current.advance(
            current.revision(),
            phase,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Freezes the exact authority for operational DSC1 `0x05`–`0x0a`.
    ///
    /// The completed early transport transcript, statement, encrypted recovery
    /// capsule and round-start record are persisted immutably before any BP
    /// message can be accepted. Reissuing after restart requires byte-identical
    /// authenticated inputs and never replaces the original authority.
    pub fn prepare_operational_bp_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        session_id: [u8; 32],
        expected_terms_hash: [u8; 32],
        statement: &BpStatementV1,
        recovery_capsule: &RecoveryCapsule,
    ) -> Result<PreparedOperationalBpTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let current = self.load_session_locked(session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed
            || trusted_chain_id.as_bytes() == &[0; 32]
            || expected_terms_hash == [0; 32]
            || current.terms_hash() != expected_terms_hash
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let initial = self.load_session_revision(session_id, 0)?;
        let roster = self.load_transport_roster(session_id)?;
        let identities = self.load_transport_identity_binding(session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != *trusted_chain_id.as_bytes() {
            return Err(SessionStoreError::InvalidTransition);
        }
        let early = self.load_early_transport_authority(session_id)?;
        self.require_live_early_transport_authority(&early, &initial, &roster)?;
        let canonical = BpStatementV1::from_bytes(statement.to_bytes(), &trusted_chain_id)
            .map_err(|_| SessionStoreError::Canonical)?;
        if canonical.to_bytes() != statement.to_bytes()
            || canonical.statement_hash() != statement.statement_hash()
        {
            return Err(SessionStoreError::Canonical);
        }

        let durable = match self.load_bp_transport_authority(session_id) {
            Ok(existing) => {
                let round_start =
                    self.load_session_revision(session_id, existing.round_start_revision)?;
                let expected = BpTransportAuthorityRecordV1::new(
                    &early,
                    &round_start,
                    &canonical,
                    recovery_capsule,
                )?;
                if existing.bytes != expected.bytes {
                    return Err(SessionStoreError::Conflict);
                }
                existing
            }
            Err(SessionStoreError::SessionNotFound) => {
                let early_prefix =
                    self.authenticated_early_transport_prefix(session_id, current.revision())?;
                if current.phase() != SessionPhaseV1::SharesRevealed
                    || early_prefix.len() != 6
                    || current.revision()
                        != u64::try_from(early_prefix.len())
                            .map_err(|_| SessionStoreError::CapacityExceeded)?
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                let expected = BpTransportAuthorityRecordV1::new(
                    &early,
                    &current,
                    &canonical,
                    recovery_capsule,
                )?;
                self.persist_bp_transport_authority(&expected)?;
                test_crash_hook("bp-transport-after-authority-persist");
                let persisted = self.load_bp_transport_authority(session_id)?;
                if persisted.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                persisted
            }
            Err(error) => return Err(error),
        };
        let round_start = self.load_session_revision(session_id, durable.round_start_revision)?;
        self.require_live_bp_transport_authority(&durable, &early, &round_start, &roster)?;
        let verifier = DomCollaborativeRangeProofV1::new(
            &durable.statement,
            durable.recovery_capsule.as_bytes().to_vec(),
        )
        .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let _ = self.audit_operational_bp_continuation(
            session_id,
            &current,
            &roster,
            &durable.statement,
            &verifier,
        )?;
        Ok(PreparedOperationalBpTransportAuthorityV1 {
            session_id,
            authority_digest: durable.digest,
            statement_hash: durable.statement.statement_hash(),
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts one new or repeated prepared operational BP message.
    ///
    /// The Store derives the only legal sender, type, sequence, phase and
    /// transcript successor, verifies typed payload semantics, and persists the
    /// signed envelope before the successor. The generic ingress remains
    /// unavailable for an unseen `0x05`–`0x0a` message.
    pub fn accept_prepared_operational_bp_transport_message(
        &self,
        authority: &PreparedOperationalBpTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let prepared = self.authenticate_prepared_bp_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != prepared.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let current = self.load_session_locked(envelope.session_id)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let retained = TransportMessageRecordV1::from_bytes(&bytes)?;
                if retained.signed_bytes == signed_bytes {
                    return self.accept_transport_message_with_successor_locked(
                        signed_bytes,
                        &current,
                        None,
                    );
                }
                let failed = current.advance(
                    current.revision(),
                    SessionPhaseV1::FailedClosed,
                    current.transcript_hash(),
                    current.irreversible(),
                    current.chain(),
                    current.encrypted_payload(),
                )?;
                return self.accept_transport_message_with_successor_locked(
                    signed_bytes,
                    &current,
                    Some(&failed),
                );
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if !(0x05..=0x0a).contains(&envelope.message_type) {
            return Err(SessionStoreError::InvalidTransition);
        }
        let phase = self.require_next_prepared_operational_bp_message(
            &prepared,
            &current,
            &roster,
            &envelope,
            signed_bytes,
        )?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            phase,
        )?;
        let successor = current.advance(
            current.revision(),
            phase,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Freezes the exact authority for both operational `TxTemplateCommit`
    /// (`0x0b`) messages.
    ///
    /// The complete prepared Bulletproof transcript and the three exact
    /// canonical DOM transaction templates are authenticated before the
    /// five-digest 160-byte payload is persisted immutably. Reissue after a
    /// restart accepts only the same templates, statement and recovery
    /// capsule; it never replaces the frozen authority.
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_operational_template_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        session_id: [u8; 32],
        expected_terms_hash: [u8; 32],
        funding_template: &Transaction,
        claim_template: &Transaction,
        refund_template: &Transaction,
        statement: &BpStatementV1,
        recovery_capsule: &RecoveryCapsule,
    ) -> Result<PreparedOperationalTemplateTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let current = self.load_session_locked(session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed
            || trusted_chain_id.as_bytes() == &[0; 32]
            || expected_terms_hash == [0; 32]
            || current.terms_hash() != expected_terms_hash
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(session_id)?;
        let identities = self.load_transport_identity_binding(session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        let early = self.load_early_transport_authority(session_id)?;
        let initial = self.load_session_revision(session_id, 0)?;
        self.require_live_early_transport_authority(&early, &initial, &roster)?;
        let bp = self.load_bp_transport_authority(session_id)?;
        let bp_round_start = self.load_session_revision(session_id, bp.round_start_revision)?;
        self.require_live_bp_transport_authority(&bp, &early, &bp_round_start, &roster)?;
        let expected_bp = BpTransportAuthorityRecordV1::new(
            &early,
            &bp_round_start,
            statement,
            recovery_capsule,
        )?;
        if bp.bytes != expected_bp.bytes || bp.chain_id != *trusted_chain_id.as_bytes() {
            return Err(SessionStoreError::Conflict);
        }
        let bp_terminal_revision = bp
            .round_start_revision
            .checked_add(11)
            .ok_or(SessionStoreError::CapacityExceeded)?;
        let bp_terminal = self.load_session_revision(session_id, bp_terminal_revision)?;
        let verifier = DomCollaborativeRangeProofV1::new(
            &bp.statement,
            bp.recovery_capsule.as_bytes().to_vec(),
        )
        .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let continuation = self.audit_operational_bp_continuation(
            session_id,
            &bp_terminal,
            &roster,
            &bp.statement,
            &verifier,
        )?;
        if continuation.stage() != OperationalBpContinuationStageV1::Complete
            || continuation.session_revision() != bp_terminal.revision()
            || continuation.transcript_hash() != bp_terminal.transcript_hash()
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let payload = operational_template_commit_payload_v1(
            funding_template,
            claim_template,
            refund_template,
            &bp.statement,
        )?;
        let durable = match self.load_template_transport_authority(session_id) {
            Ok(existing) => {
                let round_start =
                    self.load_session_revision(session_id, existing.round_start_revision)?;
                let expected = TemplateTransportAuthorityRecordV1::new(&bp, &round_start, payload)?;
                if existing.bytes != expected.bytes {
                    return Err(SessionStoreError::Conflict);
                }
                existing
            }
            Err(SessionStoreError::SessionNotFound) => {
                if current.phase() != SessionPhaseV1::OutputFinalized
                    || current.as_bytes() != bp_terminal.as_bytes()
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                let expected = TemplateTransportAuthorityRecordV1::new(&bp, &current, payload)?;
                self.persist_template_transport_authority(&expected)?;
                test_crash_hook("template-transport-after-authority-persist");
                let persisted = self.load_template_transport_authority(session_id)?;
                if persisted.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                persisted
            }
            Err(error) => return Err(error),
        };
        let round_start = self.load_session_revision(session_id, durable.round_start_revision)?;
        self.require_live_template_transport_authority(&durable, &bp, &round_start, &roster)?;
        let _ = self
            .audit_operational_template_transport_prefix(session_id, &current, &roster, &durable)?;
        Ok(PreparedOperationalTemplateTransportAuthorityV1 {
            session_id,
            authority_digest: durable.digest,
            template_commit_payload: durable.template_commit_payload,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts one new or repeated prepared `TxTemplateCommit` message.
    ///
    /// Sender, local sequence, predecessor transcript and the exact five
    /// digests are derived by the Store. The first message moves to
    /// `TemplatesCommitted`; the second remains in that phase. The generic
    /// ingress remains unavailable for an unseen `0x0b`.
    pub fn accept_prepared_operational_template_transport_message(
        &self,
        authority: &PreparedOperationalTemplateTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let prepared = self.authenticate_prepared_template_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != prepared.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let current = self.load_session_locked(envelope.session_id)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let retained = TransportMessageRecordV1::from_bytes(&bytes)?;
                if retained.signed_bytes == signed_bytes {
                    return self.accept_transport_message_with_successor_locked(
                        signed_bytes,
                        &current,
                        None,
                    );
                }
                let failed = current.advance(
                    current.revision(),
                    SessionPhaseV1::FailedClosed,
                    current.transcript_hash(),
                    current.irreversible(),
                    current.chain(),
                    current.encrypted_payload(),
                )?;
                return self.accept_transport_message_with_successor_locked(
                    signed_bytes,
                    &current,
                    Some(&failed),
                );
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if envelope.message_type != 0x0b {
            return Err(SessionStoreError::InvalidTransition);
        }
        self.require_next_prepared_operational_template_message(
            &prepared,
            &current,
            &roster,
            &envelope,
            signed_bytes,
        )?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            SessionPhaseV1::TemplatesCommitted,
        )?;
        let successor = current.advance(
            current.revision(),
            SessionPhaseV1::TemplatesCommitted,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Reissues the process-local authority for one frozen operational
    /// signing round.
    ///
    /// The immutable signing binding must already have been created by the
    /// corresponding Store-owned signing-session entry point. This method
    /// accepts no roster, transaction, kernel, adaptor point, transcript or
    /// sender sequence from the caller: all of them are decoded from retained
    /// state and reauthenticated against the current Contracts journal.
    pub fn prepare_operational_signing_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        session_id: [u8; 32],
        purpose: PurposeV1,
    ) -> Result<PreparedOperationalSigningTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        self.audit_transport()?;
        let context = self.authenticate_operational_signing_transport_context(
            &trusted_chain_id,
            session_id,
            purpose,
        )?;
        Ok(PreparedOperationalSigningTransportAuthorityV1 {
            trusted_chain_id,
            session_id,
            purpose,
            signing_binding_digest: context.signing_binding_digest,
            round_start_revision: context.round.round_start_revision,
            round_start_record_digest: context.round.round_start_record_digest,
            post_anchor: context.post_anchor,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts one new or repeated prepared signing message (`0x0c`–`0x0e`).
    ///
    /// Before persistence, the Store derives the only legal sender, purpose,
    /// signing index, sender-local sequence and transcript successor. Nonce
    /// reveals must open the retained commitments and every partial signature
    /// must satisfy the exact bound DOM equation. Completion also verifies the
    /// aggregate plain signature or adaptor pre-signature. The generic ingress
    /// remains closed for every unseen signing message.
    pub fn accept_prepared_operational_signing_transport_message(
        &self,
        authority: &PreparedOperationalSigningTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let context = self.authenticate_prepared_signing_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != authority.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let current = self.load_session_locked(envelope.session_id)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let retained = TransportMessageRecordV1::from_bytes(&bytes)?;
                if retained.signed_bytes == signed_bytes {
                    return self.accept_transport_message_with_successor_locked(
                        signed_bytes,
                        &current,
                        None,
                    );
                }
                let failed = current.advance(
                    current.revision(),
                    SessionPhaseV1::FailedClosed,
                    current.transcript_hash(),
                    current.irreversible(),
                    current.chain(),
                    current.encrypted_payload(),
                )?;
                return self.accept_transport_message_with_successor_locked(
                    signed_bytes,
                    &current,
                    Some(&failed),
                );
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if !(0x0c..=0x0e).contains(&envelope.message_type) {
            return Err(SessionStoreError::InvalidTransition);
        }
        let phase = self.require_next_prepared_operational_signing_message(
            &context,
            &current,
            &roster,
            &envelope,
            signed_bytes,
        )?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            phase,
        )?;
        let successor = current.advance(
            current.revision(),
            phase,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Persists and reissues the exact completed Refund transaction authority.
    ///
    /// The caller supplies only the already trusted chain identity and the
    /// session identifier. The Store replays the retained Refund signing
    /// round, derives the aggregate signature, finalizes the frozen
    /// HEIGHT_LOCKED transaction and fsyncs its canonical bytes before this
    /// process-local handle exposes the public `0x10` payload.
    pub fn prepare_operational_final_refund_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        session_id: [u8; 32],
    ) -> Result<PreparedOperationalFinalRefundTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        self.audit_transport()?;
        let current = self.load_session_locked(session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed {
            return Err(SessionStoreError::InvalidTransition);
        }
        let retained_v2 = match self.load_operational_final_refund_v2(session_id) {
            Ok(record) => self.authenticate_operational_final_refund_v2_at_terminal(
                session_id,
                record.terminal_revision,
            )?,
            Err(SessionStoreError::SessionNotFound) => {
                let terminal_revision = match self.load_operational_final_refund(session_id) {
                    Ok(legacy) => legacy.terminal_revision,
                    Err(SessionStoreError::SessionNotFound)
                        if current.phase() == SessionPhaseV1::RefundSigning =>
                    {
                        current.revision()
                    }
                    Err(SessionStoreError::SessionNotFound) => {
                        return Err(SessionStoreError::InvalidTransition)
                    }
                    Err(error) => return Err(error),
                };
                let derived = self.derive_completed_operational_final_refund_v2_at_terminal(
                    trusted_chain_id.as_bytes(),
                    session_id,
                    terminal_revision,
                )?;
                let expected = OperationalFinalRefundRecordV2::new(derived)?;
                self.persist_operational_final_refund_v2(&expected)?;
                test_crash_hook("final-refund-v2-after-artifact-persist");
                let durable = self.load_operational_final_refund_v2(session_id)?;
                if durable.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                durable
            }
            Err(error) => return Err(error),
        };
        if trusted_chain_id.as_bytes() != &retained_v2.chain_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let retained = match self.load_operational_final_refund(session_id) {
            Ok(record) => record,
            Err(SessionStoreError::SessionNotFound) => {
                let derived = self.derive_completed_operational_final_refund_at_terminal(
                    trusted_chain_id.as_bytes(),
                    session_id,
                    retained_v2.terminal_revision,
                )?;
                let expected = OperationalFinalRefundRecordV1::new(derived)?;
                self.persist_operational_final_refund(&expected)?;
                test_crash_hook("final-refund-after-artifact-persist");
                let durable = self.load_operational_final_refund(session_id)?;
                if durable.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                durable
            }
            Err(error) => return Err(error),
        };
        if trusted_chain_id.as_bytes() != &retained.chain_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let authenticated = self.authenticate_completed_operational_final_refund_at_terminal(
            session_id,
            retained.terminal_revision,
        )?;
        if retained_v2.session_id != authenticated.session_id
            || retained_v2.chain_id != authenticated.chain_id
            || retained_v2.terms_hash != authenticated.terms_hash
            || retained_v2.signing_binding_record_digest
                != authenticated.signing_binding_record_digest
            || retained_v2.terminal_revision != authenticated.terminal_revision
            || retained_v2.terminal_record_digest != authenticated.terminal_record_digest
            || retained_v2.terminal_transcript_hash != authenticated.terminal_transcript_hash
            || retained_v2.canonical_sender_id != authenticated.canonical_sender_id
            || retained_v2.canonical_sender_sequence != authenticated.canonical_sender_sequence
            || retained_v2.refund_tx_hash != authenticated.refund_tx_hash
            || retained_v2.exact_transaction_bytes != authenticated.final_refund_payload
        {
            return Err(SessionStoreError::Quarantined);
        }
        self.require_operational_final_refund_transport_head(&authenticated, &current)?;
        Ok(PreparedOperationalFinalRefundTransportAuthorityV1 {
            trusted_chain_id,
            session_id,
            signing_binding_record_digest: authenticated.signing_binding_record_digest,
            final_refund_record_digest: authenticated.final_refund_record_digest,
            final_refund_v2_record_digest: retained_v2.digest,
            terminal_revision: authenticated.terminal_revision,
            terminal_record_digest: authenticated.terminal_record_digest,
            terminal_transcript_hash: authenticated.terminal_transcript_hash,
            canonical_sender_id: authenticated.canonical_sender_id,
            canonical_sender_sequence: authenticated.canonical_sender_sequence,
            refund_tx_hash: authenticated.refund_tx_hash,
            final_refund_payload: authenticated.final_refund_payload,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts the exact Store-derived `FinalRefund` (`0x10`) envelope.
    ///
    /// The sender, sequence, predecessor transcript and payload all come from
    /// the retained completed signing round. A byte-identical redelivery is
    /// idempotent; a validly signed conflict under the same logical key is
    /// persisted as `FailedClosed`.
    pub fn accept_prepared_operational_final_refund_transport_message(
        &self,
        authority: &PreparedOperationalFinalRefundTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let authenticated =
            self.authenticate_prepared_operational_final_refund_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != authenticated.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        if envelope.chain_id != authenticated.chain_id
            || envelope.sender_id != authenticated.canonical_sender_id
            || envelope.sequence != authenticated.canonical_sender_sequence
            || participant.direction != authenticated.canonical_sender_direction
        {
            return Err(SessionStoreError::InvalidTransition);
        }

        let retained_name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        let retained = match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&retained_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => Some(TransportMessageRecordV1::from_bytes(&bytes)?),
            Err(LinuxCapabilityError::NotFound) => None,
            Err(error) => return Err(error.into()),
        };
        if let Some(retained) = retained {
            let (retained_envelope, retained_direction) =
                self.authenticate_transport_record(&retained_name, &retained)?;
            if retained.equivocation
                || retained_envelope.chain_id != authenticated.chain_id
                || retained_envelope.session_id != authenticated.session_id
                || retained_envelope.sender_id != authenticated.canonical_sender_id
                || retained_envelope.sequence != authenticated.canonical_sender_sequence
                || retained_envelope.previous_transcript_hash
                    != authenticated.terminal_transcript_hash
                || retained_envelope.message_type != 0x10
                || retained_direction != authenticated.canonical_sender_direction
                || retained_envelope.payload(&retained.signed_bytes)?
                    != authenticated.final_refund_payload
            {
                return Err(SessionStoreError::Quarantined);
            }
            let current = self.load_session_locked(envelope.session_id)?;
            match self.accept_transport_message_with_successor_locked(signed_bytes, &current, None)
            {
                Ok(outcome) => return Ok(outcome),
                Err(SessionStoreError::InvalidTransition) => {}
                Err(error) => return Err(error),
            }
            let current = self.load_session_locked(envelope.session_id)?;
            let failed = current.advance(
                current.revision(),
                SessionPhaseV1::FailedClosed,
                current.transcript_hash(),
                current.irreversible(),
                current.chain(),
                current.encrypted_payload(),
            )?;
            return self.accept_transport_message_with_successor_locked(
                signed_bytes,
                &current,
                Some(&failed),
            );
        }

        if envelope.previous_transcript_hash != authenticated.terminal_transcript_hash
            || envelope.message_type != 0x10
            || envelope.payload(signed_bytes)? != authenticated.final_refund_payload
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let current = self.load_session_locked(envelope.session_id)?;
        self.require_operational_final_refund_transport_head(&authenticated, &current)?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            SessionPhaseV1::RefundSigned,
        )?;
        let successor = current.advance(
            current.revision(),
            SessionPhaseV1::RefundSigned,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.require_bounded_operational_final_refund_transport_edge(
            &authenticated,
            &current,
            &envelope,
            signed_bytes,
            participant.direction,
            &successor,
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Persists and reissues one exact cooperative Abort (`0x13`) authority.
    ///
    /// The owner-only authority record binds the non-zero decision digest to
    /// the exact local pre-funding revision, record digest and chain projection
    /// before any transport bytes may be signed. Its exposed bilateral wire
    /// digest uses only facts both peers can reproduce: chain, session, terms,
    /// decision, predecessor phase/transcript, roster, canonical smallest
    /// participant and sender-local sequence. Funding gates, issuances,
    /// commits, consumptions, broadcasts, secret exposure, or any retained
    /// chain observation make this operation fail closed.
    pub fn prepare_operational_abort_transport_authority(
        &self,
        trusted_chain_id: TrustedChainIdV1,
        session_id: [u8; 32],
        durable_decision_digest: [u8; 32],
    ) -> Result<PreparedOperationalAbortTransportAuthorityV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        self.audit_transport()?;
        if trusted_chain_id.as_bytes() == &[0; 32] || durable_decision_digest == [0; 32] {
            return Err(SessionStoreError::InvalidTransition);
        }
        let current = self.require_operational_abort_economic_state(session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(session_id)?;
        let identities = self.load_transport_identity_binding(session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != *trusted_chain_id.as_bytes() {
            return Err(SessionStoreError::InvalidTransition);
        }
        let retained = match self.load_operational_abort_transport_authority(session_id) {
            Ok(existing) => {
                if existing.durable_decision_digest != durable_decision_digest {
                    return Err(SessionStoreError::Conflict);
                }
                existing
            }
            Err(SessionStoreError::SessionNotFound) => {
                if !abort_phase_is_strictly_pre_funding(current.phase()) {
                    return Err(SessionStoreError::InvalidTransition);
                }
                let canonical_sender_id = roster
                    .participants
                    .iter()
                    .map(|participant| participant.participant_id)
                    .min()
                    .ok_or(SessionStoreError::Canonical)?;
                let canonical_sender_sequence =
                    self.next_transport_sequence(session_id, canonical_sender_id)?;
                let expected = OperationalAbortTransportAuthorityRecordV1::new(
                    &roster,
                    &current,
                    durable_decision_digest,
                    canonical_sender_sequence,
                )?;
                self.persist_operational_abort_transport_authority(&expected)?;
                test_crash_hook("operational-abort-after-authority-persist");
                let durable = self.load_operational_abort_transport_authority(session_id)?;
                if durable.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                durable
            }
            Err(error) => return Err(error),
        };
        let authenticated = self.authenticate_operational_abort_transport_authority(session_id)?;
        if retained.bytes
            != self
                .load_operational_abort_transport_authority(session_id)?
                .bytes
            || authenticated.chain_id != *trusted_chain_id.as_bytes()
        {
            return Err(SessionStoreError::Quarantined);
        }
        let current = self.load_session_locked(session_id)?;
        self.require_operational_abort_transport_head(&authenticated, &current)?;
        Ok(PreparedOperationalAbortTransportAuthorityV1 {
            trusted_chain_id,
            session_id,
            authority_record_digest: authenticated.authority_record_digest,
            predecessor_revision: authenticated.predecessor_revision,
            predecessor_record_digest: authenticated.predecessor_record_digest,
            predecessor_transcript_hash: authenticated.predecessor_transcript_hash,
            canonical_sender_id: authenticated.canonical_sender_id,
            canonical_sender_sequence: authenticated.canonical_sender_sequence,
            abort_binding_digest: authenticated.abort_binding_digest,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts the exact Store-derived cooperative Abort (`0x13`) envelope.
    ///
    /// The Store reexecutes the complete economic fence under the same
    /// operation lock immediately before persisting the envelope and derives
    /// the sole `Aborted` successor internally. Exact redelivery is
    /// idempotent; different validly signed bytes under the same logical key
    /// persist `FailedClosed` through the common transport journal.
    pub fn accept_prepared_operational_abort_transport_message(
        &self,
        authority: &PreparedOperationalAbortTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let authenticated =
            self.authenticate_prepared_operational_abort_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != authenticated.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        if envelope.chain_id != authenticated.chain_id
            || roster.chain_id != authenticated.chain_id
            || envelope.sender_id != authenticated.canonical_sender_id
            || envelope.sequence != authenticated.canonical_sender_sequence
            || participant.direction != authenticated.canonical_sender_direction
        {
            return Err(SessionStoreError::InvalidTransition);
        }

        let retained_name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        let retained = match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&retained_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => Some(TransportMessageRecordV1::from_bytes(&bytes)?),
            Err(LinuxCapabilityError::NotFound) => None,
            Err(error) => return Err(error.into()),
        };
        if let Some(retained) = retained {
            let (retained_envelope, retained_direction) =
                self.authenticate_transport_record(&retained_name, &retained)?;
            let predecessor = self.load_session_revision(
                authenticated.session_id,
                authenticated.predecessor_revision,
            )?;
            if retained.equivocation {
                return Err(SessionStoreError::Quarantined);
            }
            self.require_bounded_operational_abort_transport_edge(
                &authenticated,
                &predecessor,
                &retained_envelope,
                &retained.signed_bytes,
                retained_direction,
                &retained.successor,
            )?;
            let current = self.load_session_locked(envelope.session_id)?;
            match self.accept_transport_message_with_successor_locked(signed_bytes, &current, None)
            {
                Ok(outcome) => return Ok(outcome),
                Err(SessionStoreError::InvalidTransition) => {}
                Err(error) => return Err(error),
            }
            let current = self.load_session_locked(envelope.session_id)?;
            let failed = current.advance(
                current.revision(),
                SessionPhaseV1::FailedClosed,
                current.transcript_hash(),
                current.irreversible(),
                current.chain(),
                current.encrypted_payload(),
            )?;
            return self.accept_transport_message_with_successor_locked(
                signed_bytes,
                &current,
                Some(&failed),
            );
        }

        let payload = envelope.payload(signed_bytes)?;
        if envelope.previous_transcript_hash != authenticated.predecessor_transcript_hash
            || envelope.message_type != 0x13
            || payload.len() != OPERATIONAL_ABORT_PAYLOAD_LEN
            || payload == [0; 32]
            || payload != authenticated.abort_binding_digest
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let current = self.require_operational_abort_economic_state(envelope.session_id)?;
        self.require_operational_abort_transport_head(&authenticated, &current)?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            SessionPhaseV1::Aborted,
        )?;
        let successor = current.advance(
            current.revision(),
            SessionPhaseV1::Aborted,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.require_bounded_operational_abort_transport_edge(
            &authenticated,
            &current,
            &envelope,
            signed_bytes,
            participant.direction,
            &successor,
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Reissues the process-local authority for the post-anchor Claim adaptor
    /// pre-signature transport edge (`0x0f`).
    ///
    /// The exact `DOMSPPS1` artifact must already be durable. This method does
    /// not reconstruct it implicitly: it reauthenticates the live consumed
    /// signing capability, trusted chain, all six completed signing messages,
    /// their public equations and the retained artifact before issuing the
    /// linear transport handle. Reissue after restart accepts only the same
    /// authenticated terminal round and at most its one exact `0x0f` edge.
    pub fn prepare_post_anchor_dom_claim_pre_signature_transport_authority(
        &self,
        authorization: &ConsumedClaimSigningAuthorizationV1,
        trusted_chain_id: TrustedChainIdV1,
    ) -> Result<PreparedPostAnchorClaimPreSignatureTransportAuthorityV1, SessionStoreError> {
        self.require_legacy_v1_non_productive_profile()?;
        let _guard = self.operation_lock()?;
        let (issued, consumed, current) =
            self.authenticate_live_consumed_claim_authority(authorization)?;
        if trusted_chain_id.as_bytes() != &issued.chain_id {
            return Err(SessionStoreError::ClaimSigningAuthorityUnavailable);
        }
        let retained = self.load_post_anchor_claim_pre_signature(issued.session_id)?;
        let authenticated = self.authenticate_completed_post_anchor_claim_round_at_terminal(
            issued.session_id,
            retained.terminal_revision,
        )?;
        if authenticated.issuance_record_digest != issued.digest
            || authenticated.consumption_record_digest != consumed.digest
            || authenticated.chain_id != *trusted_chain_id.as_bytes()
        {
            return Err(SessionStoreError::ClaimSigningAuthorityUnavailable);
        }
        self.require_post_anchor_claim_pre_signature_transport_head(&authenticated, &current)?;
        Ok(PreparedPostAnchorClaimPreSignatureTransportAuthorityV1 {
            trusted_chain_id,
            session_id: authenticated.session_id,
            issuance_record_digest: authenticated.issuance_record_digest,
            consumption_record_digest: authenticated.consumption_record_digest,
            signing_binding_record_digest: authenticated.signing_binding_record_digest,
            round_binding_record_digest: authenticated.round_binding_record_digest,
            pre_signature_record_digest: authenticated.pre_signature_record_digest,
            terminal_revision: authenticated.terminal_revision,
            terminal_record_digest: authenticated.terminal_record_digest,
            terminal_transcript_hash: authenticated.terminal_transcript_hash,
            canonical_sender_id: authenticated.canonical_sender_id,
            canonical_sender_sequence: authenticated.canonical_sender_sequence,
            pre_signature_payload: authenticated.pre_signature_payload,
            open_instance_id: self.open_instance_id,
        })
    }

    /// Accepts the exact prepared post-anchor Claim pre-signature (`0x0f`).
    ///
    /// The Store rederives the pre-signature from the six retained signing
    /// messages and fixes the sender to the smallest participant identifier,
    /// independent of initiator/responder transport role. A byte-identical
    /// redelivery returns the retained receipt; a validly signed conflict at
    /// the same logical key persists `FailedClosed`. No second `0x0f` edge is
    /// accepted.
    pub fn accept_prepared_post_anchor_dom_claim_pre_signature_transport_message(
        &self,
        authority: &PreparedPostAnchorClaimPreSignatureTransportAuthorityV1,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        self.require_legacy_v1_non_productive_profile()?;
        let _guard = self.operation_lock()?;
        let authenticated = self
            .authenticate_prepared_post_anchor_claim_pre_signature_transport_authority(authority)?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.session_id != authenticated.session_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identities = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;

        if envelope.chain_id != authenticated.chain_id
            || envelope.sender_id != authenticated.canonical_sender_id
            || envelope.sequence != authenticated.canonical_sender_sequence
            || participant.direction != authenticated.canonical_sender_direction
        {
            return Err(SessionStoreError::InvalidTransition);
        }

        // A retained logical key must be handled before applying the unseen
        // edge rules below.  Otherwise an exact duplicate is interpreted as a
        // second 0x0f successor after the transcript already advanced, and a
        // validly signed conflict is returned as an ordinary invalid payload
        // instead of being durably failed closed.
        let retained_name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        let retained = match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&retained_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => Some(TransportMessageRecordV1::from_bytes(&bytes)?),
            Err(LinuxCapabilityError::NotFound) => None,
            Err(error) => return Err(error.into()),
        };
        if let Some(retained) = retained {
            let (retained_envelope, retained_direction) =
                self.authenticate_transport_record(&retained_name, &retained)?;
            if retained.equivocation
                || retained_envelope.chain_id != authenticated.chain_id
                || retained_envelope.session_id != authenticated.session_id
                || retained_envelope.sender_id != authenticated.canonical_sender_id
                || retained_envelope.sequence != authenticated.canonical_sender_sequence
                || retained_envelope.previous_transcript_hash
                    != authenticated.terminal_transcript_hash
                || retained_envelope.message_type != 0x0f
                || retained_direction != authenticated.canonical_sender_direction
                || retained_envelope.payload(&retained.signed_bytes)?
                    != authenticated.pre_signature_payload
            {
                return Err(SessionStoreError::Quarantined);
            }

            let current = self.load_session_locked(envelope.session_id)?;
            match self.accept_transport_message_with_successor_locked(signed_bytes, &current, None)
            {
                Ok(outcome) => return Ok(outcome),
                Err(SessionStoreError::InvalidTransition) => {}
                Err(error) => return Err(error),
            }

            // The first call above authenticates the retained accepted edge
            // and heals its persist-before-successor crash cut.  Re-read the
            // actual head before deriving FailedClosed so a conflict after
            // either that healing or later projection-only revisions cannot
            // overwrite or skip durable history.
            let current = self.load_session_locked(envelope.session_id)?;
            let failed = current.advance(
                current.revision(),
                SessionPhaseV1::FailedClosed,
                current.transcript_hash(),
                current.irreversible(),
                current.chain(),
                current.encrypted_payload(),
            )?;
            return self.accept_transport_message_with_successor_locked(
                signed_bytes,
                &current,
                Some(&failed),
            );
        }

        if envelope.previous_transcript_hash != authenticated.terminal_transcript_hash
            || envelope.message_type != 0x0f
            || envelope.payload(signed_bytes)? != authenticated.pre_signature_payload
        {
            return Err(SessionStoreError::InvalidTransition);
        }

        let current = self.load_session_locked(envelope.session_id)?;
        self.require_post_anchor_claim_pre_signature_transport_head(&authenticated, &current)?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            SessionPhaseV1::FundingConfirmed,
        )?;
        let successor = current.advance(
            current.revision(),
            SessionPhaseV1::FundingConfirmed,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.require_bounded_post_anchor_claim_pre_signature_transport_edge(
            &authenticated,
            &current,
            &envelope,
            signed_bytes,
            participant.direction,
            &successor,
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    /// Authenticates one canonical DSC1 redelivery inside the retained
    /// Contracts authority.
    ///
    /// No caller supplies a phase, transcript, irreversible flags, chain
    /// projection, encrypted payload or failed-closed record. For an already
    /// retained logical key, the Store reloads the exact durable successor.
    /// Exact duplicates return that receipt and validly signed conflicting
    /// bytes construct `FailedClosed` internally.
    /// A previously unseen envelope is refused here: each V1 payload requires
    /// a phase-specific opaque authority (intent, collaborative-output,
    /// Bulletproof, signing, final transaction, ready-to-fund, ACK, or abort)
    /// and cannot be made trustworthy from its message type and phase alone.
    pub fn accept_transport_message_derived(
        &self,
        signed_bytes: &[u8],
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identity_binding = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identity_binding)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let current = self.load_session_locked(envelope.session_id)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        let retained = match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => Some(TransportMessageRecordV1::from_bytes(&bytes)?),
            Err(LinuxCapabilityError::NotFound) => None,
            Err(error) => return Err(error.into()),
        };
        if let Some(record) = retained {
            if record.signed_bytes == signed_bytes {
                return self.accept_transport_message_with_successor_locked(
                    signed_bytes,
                    &current,
                    None,
                );
            }
            let failed = current.advance(
                current.revision(),
                SessionPhaseV1::FailedClosed,
                current.transcript_hash(),
                current.irreversible(),
                current.chain(),
                current.encrypted_payload(),
            )?;
            return self.accept_transport_message_with_successor_locked(
                signed_bytes,
                &current,
                Some(&failed),
            );
        }
        self.require_prepared_derived_transport_authority(
            &current,
            &roster,
            &envelope,
            signed_bytes,
        )?;
        let phase = derived_transport_phase(&current, &envelope, signed_bytes)?;
        self.require_derived_transport_prefix(&current, &roster, &envelope, signed_bytes, phase)?;
        let transcript_hash = accepted_transport_transcript_hash(
            &current.transcript_hash(),
            &envelope.message_digest,
            participant.direction,
            envelope.message_type,
            phase,
        )?;
        let successor = current.advance(
            current.revision(),
            phase,
            transcript_hash,
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let failed = current.advance(
            current.revision(),
            SessionPhaseV1::FailedClosed,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        self.accept_transport_message_with_successor_locked(signed_bytes, &successor, Some(&failed))
    }

    fn require_prepared_derived_transport_authority(
        &self,
        _current: &SessionRecordV1,
        _roster: &TransportRosterRecordV1,
        _envelope: &ParsedTransportEnvelopeV1,
        _signed_bytes: &[u8],
    ) -> Result<(), SessionStoreError> {
        // There is deliberately no generic authority for a new DSC1 message.
        // Envelope authentication proves who sent bytes, not that those bytes
        // satisfy the phase's cryptographic/economic statement. New messages
        // enter through narrowly prepared methods; this boundary exists for
        // idempotent redelivery and durable equivocation detection only.
        Err(SessionStoreError::InvalidTransition)
    }

    /// Evidence-only compatibility boundary for early/BP tests and migration.
    ///
    /// The retained store itself must use the `EvidenceOnly` policy profile;
    /// merely compiling this method cannot turn a production-ratified store
    /// into a caller-shaped ingress. Message types `0x0b` and later always
    /// require their narrow prepared authorities, including in evidence
    /// builds. Production callers cannot provide a `SessionRecordV1`
    /// successor.
    #[cfg(any(test, feature = "evidence-only"))]
    pub fn accept_transport_message(
        &self,
        signed_bytes: &[u8],
        successor: &SessionRecordV1,
        failed_closed_successor: Option<&SessionRecordV1>,
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        if self.policy.profile() != BudgetPolicyProfileV1::EvidenceOnly {
            return Err(SessionStoreError::PolicyProfile);
        }
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        if envelope.message_type >= 0x0b {
            return Err(SessionStoreError::InvalidTransition);
        }
        let _guard = self.operation_lock()?;
        self.accept_transport_message_with_successor_locked(
            signed_bytes,
            successor,
            failed_closed_successor,
        )
    }

    fn accept_transport_message_with_successor(
        &self,
        signed_bytes: &[u8],
        successor: &SessionRecordV1,
        failed_closed_successor: Option<&SessionRecordV1>,
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        self.accept_transport_message_with_successor_locked(
            signed_bytes,
            successor,
            failed_closed_successor,
        )
    }

    fn accept_transport_message_with_successor_locked(
        &self,
        signed_bytes: &[u8],
        successor: &SessionRecordV1,
        failed_closed_successor: Option<&SessionRecordV1>,
    ) -> Result<DurableTransportOutcomeV1, SessionStoreError> {
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        let roster = self.load_transport_roster(envelope.session_id)?;
        let identity_binding = self.load_transport_identity_binding(envelope.session_id)?;
        require_transport_identity_binding(&roster, &identity_binding)?;
        if roster.chain_id != envelope.chain_id {
            return Err(SessionStoreError::Canonical);
        }
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        envelope.verify(&participant.identity_key)?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
                let (accepted_envelope, accepted_direction) =
                    self.authenticate_transport_record(&name, &accepted)?;
                if accepted.equivocation
                    || accepted_envelope.session_id != envelope.session_id
                    || accepted_envelope.sender_id != envelope.sender_id
                    || accepted_envelope.sequence != envelope.sequence
                    || accepted_direction != participant.direction
                {
                    return Err(SessionStoreError::Quarantined);
                }

                let accepted_predecessor_revision = accepted
                    .successor
                    .revision()
                    .checked_sub(1)
                    .ok_or(SessionStoreError::Quarantined)?;
                let accepted_predecessor = self
                    .load_session_revision(accepted.session_id, accepted_predecessor_revision)
                    .map_err(|_| SessionStoreError::Quarantined)?;
                self.require_authenticated_transport_successor(
                    &accepted_predecessor,
                    &accepted_envelope,
                    &accepted.signed_bytes,
                    accepted_direction,
                    &accepted.successor,
                )
                .map_err(|_| SessionStoreError::Quarantined)?;

                let accepted_successor_is_pending = match self
                    .load_session_revision(accepted.session_id, accepted.successor.revision())
                {
                    Ok(durable) if durable.as_bytes() == accepted.successor.as_bytes() => false,
                    Ok(_) => return Err(SessionStoreError::Quarantined),
                    Err(SessionStoreError::SessionNotFound) => true,
                    Err(error) => return Err(error),
                };

                let equivocation_name = transport_message_name(
                    accepted.session_id,
                    accepted.sender_id,
                    accepted.sequence,
                    true,
                );
                let retained_equivocation = match self.messages.read_bounded_file(
                    &ValidatedComponent::registered(&equivocation_name)?,
                    TRANSPORT_MESSAGE_MAX_LEN,
                ) {
                    Ok(bytes) => {
                        let record = TransportMessageRecordV1::from_bytes(&bytes)?;
                        self.authenticate_transport_record(&equivocation_name, &record)?;
                        let predecessor_revision = record
                            .successor
                            .revision()
                            .checked_sub(1)
                            .ok_or(SessionStoreError::Quarantined)?;
                        if predecessor_revision < accepted.successor.revision() {
                            return Err(SessionStoreError::Quarantined);
                        }
                        let predecessor = if predecessor_revision == accepted.successor.revision()
                            && accepted_successor_is_pending
                        {
                            accepted.successor.clone()
                        } else {
                            self.load_session_revision(record.session_id, predecessor_revision)
                                .map_err(|_| SessionStoreError::Quarantined)?
                        };
                        require_failed_closed_successor(&predecessor, &record.successor)
                            .map_err(|_| SessionStoreError::Quarantined)?;
                        Some((record, predecessor))
                    }
                    Err(LinuxCapabilityError::NotFound) => None,
                    Err(error) => return Err(error.into()),
                };

                if accepted_successor_is_pending {
                    let current = self.load_session_locked(accepted.session_id)?;
                    if current.as_bytes() != accepted_predecessor.as_bytes() {
                        return Err(SessionStoreError::Quarantined);
                    }
                    self.persist_session_record(&accepted.successor)?;
                }

                if let Some((equivocation, predecessor)) = retained_equivocation {
                    match self.load_session_revision(
                        equivocation.session_id,
                        equivocation.successor.revision(),
                    ) {
                        Ok(durable) if durable.as_bytes() == equivocation.successor.as_bytes() => {}
                        Ok(_) => return Err(SessionStoreError::Quarantined),
                        Err(SessionStoreError::SessionNotFound) => {
                            let current = self.load_session_locked(equivocation.session_id)?;
                            if current.as_bytes() != predecessor.as_bytes() {
                                return Err(SessionStoreError::Quarantined);
                            }
                            self.persist_session_record(&equivocation.successor)?;
                        }
                        Err(error) => return Err(error),
                    }
                    return Ok(DurableTransportOutcomeV1::EquivocationPersisted);
                }

                if accepted.signed_bytes == signed_bytes {
                    return Ok(DurableTransportOutcomeV1::Accepted(accepted.receipt(true)));
                }
                let failed = failed_closed_successor.ok_or(SessionStoreError::InvalidTransition)?;
                let current = self.load_session_locked(envelope.session_id)?;
                require_failed_closed_successor(&current, failed)?;
                let equivocation = TransportMessageRecordV1::new(
                    &envelope,
                    signed_bytes,
                    failed,
                    participant.direction,
                    true,
                )?;
                let final_name = transport_message_name(
                    envelope.session_id,
                    envelope.sender_id,
                    envelope.sequence,
                    true,
                );
                let staging_name = format!(".{final_name}.staging");
                publish_immutable(
                    &self.messages,
                    &staging_name,
                    &final_name,
                    &equivocation.bytes,
                    TRANSPORT_MESSAGE_MAX_LEN,
                )?;
                test_crash_hook("transport-after-equivocation-persist");
                self.persist_session_record(failed)?;
                return Ok(DurableTransportOutcomeV1::EquivocationPersisted);
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if envelope.message_type != 0x13
            && self.operational_abort_transport_authority_exists(envelope.session_id)?
        {
            // Persisting the Abort authority is the local CAS winner. No
            // previously unseen transport edge may consume its predecessor;
            // retained exact duplicates/equivocations were handled above.
            // Reauthenticate the record before enforcing the freeze so a
            // corrupted owner-only file never degrades into a mere refusal.
            self.authenticate_operational_abort_transport_authority(envelope.session_id)?;
            return Err(SessionStoreError::InvalidTransition);
        }
        let current = self.load_session_locked(envelope.session_id)?;
        if current.phase() == SessionPhaseV1::FailedClosed {
            return Err(SessionStoreError::InvalidTransition);
        }
        self.require_authenticated_transport_successor(
            &current,
            &envelope,
            signed_bytes,
            participant.direction,
            successor,
        )?;
        let expected_sequence =
            self.next_transport_sequence(envelope.session_id, envelope.sender_id)?;
        if envelope.sequence != expected_sequence {
            return Err(SessionStoreError::InvalidTransition);
        }
        if self.transport_message_count(envelope.session_id)? >= MAX_ACCEPTED_TRANSPORT_MESSAGES {
            return Err(SessionStoreError::CapacityExceeded);
        }
        let record = TransportMessageRecordV1::new(
            &envelope,
            signed_bytes,
            successor,
            participant.direction,
            false,
        )?;
        let staging_name = format!(".{name}.staging");
        publish_immutable(
            &self.messages,
            &staging_name,
            &name,
            &record.bytes,
            TRANSPORT_MESSAGE_MAX_LEN,
        )?;
        test_crash_hook("transport-after-message-persist");
        self.persist_session_record(successor)?;
        test_crash_hook("transport-after-session-persist");
        Ok(DurableTransportOutcomeV1::Accepted(record.receipt(false)))
    }

    fn operation_lock(&self) -> Result<MutexGuard<'_, ()>, SessionStoreError> {
        self.operation
            .lock()
            .map_err(|_| SessionStoreError::Quarantined)
    }

    fn issue_outbound_dsc1_request_locked(
        &self,
        input: OutboundDsc1RequestIssueV1<'_>,
    ) -> Result<PreparedDsc1SigningRequestV1, SessionStoreError> {
        if input.predecessor.session_id() != input.session_id
            || input.predecessor.digest() == &[0; 32]
            || input.predecessor.transcript_hash() != input.previous_transcript_hash
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let signer = self.authenticate_local_transport_signer_binding(input.session_id)?;
        if signer.store_id != self._store_id
            || signer.chain_id != input.chain_id
            || signer.participant_id != input.sender_id
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let identities = self.load_transport_identity_binding(input.session_id)?;
        let identity_binding_digest = copy_array(&identities.bytes[338..370])?;
        if identity_binding_digest != signer.identity_binding_digest {
            return Err(SessionStoreError::Quarantined);
        }
        let expected =
            OutboundDsc1SigningRequestRecordV1::new(OutboundDsc1RequestRecordInputsV1 {
                store_id: self._store_id,
                authority_class: input.authority_class,
                chain_id: input.chain_id,
                session_id: input.session_id,
                sender_id: input.sender_id,
                sequence: input.sequence,
                previous_transcript_hash: input.previous_transcript_hash,
                predecessor_revision: input.predecessor.revision(),
                predecessor_record_digest: *input.predecessor.digest(),
                identity_binding_digest,
                signer_binding_digest: signer.digest,
                authority_digest: input.authority_digest,
                signer_key_reference: signer.key_reference,
                request_open_instance_id: self.open_instance_id,
                payload: input.payload,
            })?;
        match self.load_committed_outbound_dsc1(input.session_id, input.sender_id, input.sequence) {
            Ok(_) => return Err(SessionStoreError::InvalidTransition),
            Err(SessionStoreError::SessionNotFound) => {}
            Err(error) => return Err(error),
        }
        let durable = match self.load_outbound_dsc1_request(
            input.session_id,
            input.sender_id,
            input.sequence,
        ) {
            Ok(retained) => {
                if !retained.same_semantic_request(&expected) {
                    return Err(SessionStoreError::Conflict);
                }
                retained
            }
            Err(SessionStoreError::SessionNotFound) => {
                self.persist_outbound_dsc1_request(&expected)?;
                test_crash_hook("outbound-dsc1-after-request-persist");
                let retained = self.load_outbound_dsc1_request(
                    input.session_id,
                    input.sender_id,
                    input.sequence,
                )?;
                if retained.bytes != expected.bytes {
                    return Err(SessionStoreError::Quarantined);
                }
                retained
            }
            Err(error) => return Err(error),
        };
        self.revalidate_outbound_dsc1_request_locked(&durable, false)?;
        Ok(durable.issued_handle(self.open_instance_id))
    }

    fn authenticate_prepared_outbound_dsc1_handle_locked(
        &self,
        request: &PreparedDsc1SigningRequestV1,
    ) -> Result<OutboundDsc1SigningRequestRecordV1, SessionStoreError> {
        if request.open_instance_id != self.open_instance_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let retained = self.load_outbound_dsc1_request(
            request.session_id,
            request.sender_id,
            request.sequence,
        )?;
        if retained.request_id != request.request_id
            || retained.unsigned_message_digest != request.unsigned_message_digest
            || retained.chain_id != request.chain_id
            || retained.previous_transcript_hash != request.previous_transcript_hash
            || retained.message_type != request.message_type
            || retained.payload != request.payload
            || retained.signer_key_reference != request.signer_key_reference
            || retained.authority_class != request.authority_class
            || retained.authority_digest != request.authority_digest
            || retained.predecessor_revision != request.predecessor_revision
            || retained.predecessor_record_digest != request.predecessor_record_digest
            || retained.identity_binding_digest != request.identity_binding_digest
            || retained.signer_binding_digest != request.signer_binding_digest
            || retained.digest != request.request_record_digest
            || retained.request_open_instance_id != request.request_open_instance_id
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        Ok(retained)
    }

    fn require_signed_envelope_matches_outbound_request(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
        signed_bytes: &[u8],
    ) -> Result<(), SessionStoreError> {
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        let signer = self.authenticate_local_transport_signer_binding(request.session_id)?;
        if envelope.chain_id != request.chain_id
            || envelope.session_id != request.session_id
            || envelope.sender_id != request.sender_id
            || envelope.sequence != request.sequence
            || envelope.previous_transcript_hash != request.previous_transcript_hash
            || envelope.message_type != request.message_type
            || envelope.message_digest != request.unsigned_message_digest
            || envelope.payload(signed_bytes)? != request.payload
            || signer.participant_id != request.sender_id
            || signer.key_reference != request.signer_key_reference
            || signer.digest != request.signer_binding_digest
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        envelope.verify(&signer.schnorr_public_key)
    }

    fn revalidate_outbound_dsc1_request_locked(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
        allow_accepted: bool,
    ) -> Result<(), SessionStoreError> {
        if request.store_id != self._store_id {
            return Err(SessionStoreError::InvalidTransition);
        }
        let signer = self.authenticate_local_transport_signer_binding(request.session_id)?;
        if signer.store_id != self._store_id
            || signer.chain_id != request.chain_id
            || signer.session_id != request.session_id
            || signer.participant_id != request.sender_id
            || signer.key_reference != request.signer_key_reference
            || signer.identity_binding_digest != request.identity_binding_digest
            || signer.digest != request.signer_binding_digest
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let predecessor =
            self.load_session_revision(request.session_id, request.predecessor_revision)?;
        if predecessor.digest() != &request.predecessor_record_digest
            || predecessor.transcript_hash() != request.previous_transcript_hash
        {
            return Err(SessionStoreError::Quarantined);
        }
        // Both branches below audit the same durable authority, so the live
        // head is loaded exactly once here. The accepted branch may legally
        // observe a head ahead of `predecessor`; only the branch with no
        // accepted message requires the two to be identical.
        let current = self.load_session_locked(request.session_id)?;
        let accepted_name = transport_message_name(
            request.session_id,
            request.sender_id,
            request.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&accepted_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
                self.authenticate_transport_record(&accepted_name, &accepted)?;
                self.require_signed_envelope_matches_outbound_request(
                    request,
                    &accepted.signed_bytes,
                )?;
                if !allow_accepted {
                    return Err(SessionStoreError::InvalidTransition);
                }
                return self.require_static_outbound_dsc1_authority_locked(request, &current);
            }
            Err(LinuxCapabilityError::NotFound) => {}
            Err(error) => return Err(error.into()),
        }
        if current.as_bytes() != predecessor.as_bytes() {
            return Err(SessionStoreError::InvalidTransition);
        }
        self.require_live_outbound_dsc1_authority_locked(request, &current)
    }

    fn outbound_dsc1_request_candidate_bytes(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
    ) -> Result<Vec<u8>, SessionStoreError> {
        outbound_dsc1_candidate_bytes(&OutboundDsc1UnsignedFieldsV1 {
            message_type: request.message_type,
            chain_id: request.chain_id,
            session_id: request.session_id,
            sender_id: request.sender_id,
            sequence: request.sequence,
            previous_transcript_hash: request.previous_transcript_hash,
            payload: &request.payload,
        })
    }

    fn outbound_signing_round_phase(
        &self,
        session_id: [u8; 32],
        purpose: PurposeV1,
    ) -> Result<SessionPhaseV1, SessionStoreError> {
        if self.post_anchor_profile_selection(session_id)? == PostAnchorProfileV1V2::ProductiveV2 {
            // Profile first, round presence second: a productive V2 session
            // without a durable `DOMSPCB2` is still a pre-funding signing round.
            return if !self.post_anchor_claim_signing_binding_v2_exists(session_id)? {
                Ok(signing_phase_for_purpose(purpose))
            } else if purpose == PurposeV1::ClaimAdaptor {
                Ok(SessionPhaseV1::FundingConfirmed)
            } else {
                Err(SessionStoreError::Quarantined)
            };
        }
        match self.load_post_anchor_claim_signing_binding(session_id) {
            Ok(_) if purpose == PurposeV1::ClaimAdaptor => Ok(SessionPhaseV1::FundingConfirmed),
            Ok(_) => Err(SessionStoreError::Quarantined),
            Err(SessionStoreError::SessionNotFound) => Ok(signing_phase_for_purpose(purpose)),
            Err(error) => Err(error),
        }
    }

    fn require_outbound_dsc1_request_transition_locked(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
        predecessor: &SessionRecordV1,
        envelope: &ParsedTransportEnvelopeV1,
        complete_bytes: &[u8],
    ) -> Result<SessionPhaseV1, SessionStoreError> {
        if predecessor.session_id() != request.session_id
            || predecessor.revision() != request.predecessor_revision
            || predecessor.digest() != &request.predecessor_record_digest
            || predecessor.transcript_hash() != request.previous_transcript_hash
            || envelope.chain_id != request.chain_id
            || envelope.session_id != request.session_id
            || envelope.sender_id != request.sender_id
            || envelope.sequence != request.sequence
            || envelope.previous_transcript_hash != request.previous_transcript_hash
            || envelope.message_type != request.message_type
            || envelope.message_digest != request.unsigned_message_digest
            || envelope.payload(complete_bytes)? != request.payload
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        let roster = self.load_transport_roster(request.session_id)?;
        let participant = roster
            .participants
            .iter()
            .find(|participant| participant.participant_id == request.sender_id)
            .ok_or(SessionStoreError::Quarantined)?;
        match request.authority_class {
            authority_class if authority_class.is_early() => {
                let authority = self.load_early_transport_authority(request.session_id)?;
                if authority.digest != request.authority_digest
                    || authority.chain_id != request.chain_id
                    || request.sequence
                        != self.transport_sequence_at_revision(
                            request.session_id,
                            request.sender_id,
                            predecessor.revision(),
                        )?
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                self.require_next_prepared_early_transport_message(
                    &authority,
                    predecessor,
                    &roster,
                    envelope,
                    complete_bytes,
                )
            }
            authority_class if authority_class.is_operational_bp() => {
                let authority = self.load_bp_transport_authority(request.session_id)?;
                if authority.digest != request.authority_digest
                    || authority.chain_id != request.chain_id
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                self.require_next_prepared_operational_bp_message(
                    &authority,
                    predecessor,
                    &roster,
                    envelope,
                    complete_bytes,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalTemplateCommit => {
                let authority = self.load_template_transport_authority(request.session_id)?;
                if authority.digest != request.authority_digest
                    || authority.chain_id != request.chain_id
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                self.require_next_prepared_operational_template_message(
                    &authority,
                    predecessor,
                    &roster,
                    envelope,
                    complete_bytes,
                )?;
                Ok(SessionPhaseV1::TemplatesCommitted)
            }
            authority_class if authority_class.is_operational_signing() => {
                let purpose = signing_payload_purpose(request.message_type, &request.payload)?;
                let binding = self.load_signing_binding(request.session_id, purpose)?;
                let binding_digest = copy_array(
                    binding
                        .bytes
                        .get(binding.bytes.len().saturating_sub(DIGEST_LEN)..)
                        .ok_or(SessionStoreError::Quarantined)?,
                )?;
                if binding_digest != request.authority_digest
                    || binding.bytes[48..80] != request.chain_id
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
                let phase = self.outbound_signing_round_phase(request.session_id, purpose)?;
                let transcript_hash = accepted_transport_transcript_hash(
                    &predecessor.transcript_hash(),
                    &envelope.message_digest,
                    participant.direction,
                    envelope.message_type,
                    phase,
                )?;
                let successor = predecessor.advance(
                    predecessor.revision(),
                    phase,
                    transcript_hash,
                    predecessor.irreversible(),
                    predecessor.chain(),
                    predecessor.encrypted_payload(),
                )?;
                self.require_signing_transport_semantic_replay_with_recovery_scope(
                    predecessor,
                    envelope,
                    complete_bytes,
                    &successor,
                    (purpose, phase),
                    None,
                )?;
                Ok(phase)
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignature
            | OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignatureV2 => {
                Ok(SessionPhaseV1::FundingConfirmed)
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalRefund => {
                Ok(SessionPhaseV1::RefundSigned)
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFund => {
                Ok(SessionPhaseV1::RefundSigned)
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFundV2 => {
                Ok(SessionPhaseV1::RefundSigned)
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalClaimV2 => {
                Ok(SessionPhaseV1::ClaimBroadcast)
            }
            OutboundDsc1AuthorityClassV1::OperationalAbort => Ok(SessionPhaseV1::Aborted),
            _ => Err(SessionStoreError::InvalidTransition),
        }
    }

    /// Audits the durable authority that owns one outbound DSC1 request.
    ///
    /// The live session head is supplied by the caller so a single audit
    /// loads it exactly once. Every arm that needs the head consumes this
    /// value; no arm reloads it, so an authority audit can never observe two
    /// different heads for the same request.
    fn require_static_outbound_dsc1_authority_locked(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
        current: &SessionRecordV1,
    ) -> Result<(), SessionStoreError> {
        match request.authority_class {
            authority_class
                if authority_class.is_early()
                    || authority_class.is_operational_bp()
                    || authority_class.is_operational_signing() =>
            {
                let predecessor =
                    self.load_session_revision(request.session_id, request.predecessor_revision)?;
                let candidate = self.outbound_dsc1_request_candidate_bytes(request)?;
                let envelope = ParsedTransportEnvelopeV1::parse(&candidate)?;
                self.require_outbound_dsc1_request_transition_locked(
                    request,
                    &predecessor,
                    &envelope,
                    &candidate,
                )?;
            }
            OutboundDsc1AuthorityClassV1::OperationalTemplateCommit => {
                let authority = self.load_template_transport_authority(request.session_id)?;
                if authority.digest != request.authority_digest
                    || authority.chain_id != request.chain_id
                    || authority.template_commit_payload.as_slice() != request.payload
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignature => {
                let retained = self.load_post_anchor_claim_pre_signature(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_post_anchor_claim_round_at_terminal(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                if authenticated.pre_signature_record_digest != request.authority_digest
                    || authenticated.chain_id != request.chain_id
                    || authenticated.pre_signature_payload.as_slice() != request.payload
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignatureV2 => {
                let retained = self.load_post_anchor_claim_pre_signature_v2(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_post_anchor_claim_round_at_terminal_v2(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                if authenticated.pre_signature_record_digest != request.authority_digest
                    || authenticated.chain_id != request.chain_id
                    || authenticated.pre_signature_payload.as_slice() != request.payload
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalRefund => {
                let retained = self.load_operational_final_refund(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_operational_final_refund_at_terminal(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                if authenticated.final_refund_record_digest != request.authority_digest
                    || authenticated.chain_id != request.chain_id
                    || authenticated.final_refund_payload != request.payload
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFund => {
                let gate = self.load_m8_funding_gate(request.session_id)?;
                self.require_m8_final_refund_provenance(&gate, current)?;
                if gate.digest != request.authority_digest
                    || gate.chain_id != request.chain_id
                    || request.payload != gate.digest
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFundV2 => {
                let gate = self.load_m8_funding_gate_v2(request.session_id)?;
                if gate.digest != request.authority_digest
                    || gate.role_binding.dom_chain_id().0 != request.chain_id
                    || request.payload != gate.ready_binding.digest()
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalClaimV2 => {
                let exposure = self.load_operational_final_claim_exposure_v2(request.session_id)?;
                // The claim may only be carried to the peer after a node
                // admitted it: the admission record is the economic proof, and
                // its absence is not an authority.
                self.load_operational_final_claim_admission_v2(request.session_id)?;
                if exposure.digest != request.authority_digest
                    || exposure.chain_id != request.chain_id
                    || exposure.dom_claim_sender_id != request.sender_id
                    || request.payload != exposure.exact_transaction_bytes
                    || current.phase() != SessionPhaseV1::FundingConfirmed
                    || !current.irreversible().adaptor_secret_exposed
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            OutboundDsc1AuthorityClassV1::OperationalAbort => {
                let authenticated =
                    self.authenticate_operational_abort_transport_authority(request.session_id)?;
                if authenticated.authority_record_digest != request.authority_digest
                    || authenticated.chain_id != request.chain_id
                    || request.payload != authenticated.abort_binding_digest
                {
                    return Err(SessionStoreError::InvalidTransition);
                }
            }
            _ => return Err(SessionStoreError::InvalidTransition),
        }
        Ok(())
    }

    fn require_live_outbound_dsc1_authority_locked(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
        current: &SessionRecordV1,
    ) -> Result<(), SessionStoreError> {
        self.require_static_outbound_dsc1_authority_locked(request, current)?;
        let roster = self.load_transport_roster(request.session_id)?;
        let expected = match request.authority_class {
            authority_class
                if authority_class.is_early()
                    || authority_class.is_operational_bp()
                    || authority_class.is_operational_signing() =>
            {
                (
                    request.sender_id,
                    request.sequence,
                    request.previous_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalTemplateCommit => {
                let authority = self.load_template_transport_authority(request.session_id)?;
                let bp = self.load_bp_transport_authority(request.session_id)?;
                let early = self.load_early_transport_authority(request.session_id)?;
                let initial = self.load_session_revision(request.session_id, 0)?;
                self.require_live_early_transport_authority(&early, &initial, &roster)?;
                let bp_start =
                    self.load_session_revision(request.session_id, bp.round_start_revision)?;
                self.require_live_bp_transport_authority(&bp, &early, &bp_start, &roster)?;
                let round_start =
                    self.load_session_revision(request.session_id, authority.round_start_revision)?;
                self.require_live_template_transport_authority(
                    &authority,
                    &bp,
                    &round_start,
                    &roster,
                )?;
                let position = self.audit_operational_template_transport_prefix(
                    request.session_id,
                    current,
                    &roster,
                    &authority,
                )?;
                let participant = roster
                    .participants
                    .get(position)
                    .ok_or(SessionStoreError::InvalidTransition)?;
                let sequence = self.transport_sequence_at_revision(
                    request.session_id,
                    participant.participant_id,
                    authority.round_start_revision,
                )?;
                (
                    participant.participant_id,
                    sequence,
                    current.transcript_hash(),
                )
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignature => {
                let retained = self.load_post_anchor_claim_pre_signature(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_post_anchor_claim_round_at_terminal(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                self.require_post_anchor_claim_pre_signature_transport_head(
                    &authenticated,
                    current,
                )?;
                (
                    authenticated.canonical_sender_id,
                    authenticated.canonical_sender_sequence,
                    authenticated.terminal_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::PostAnchorClaimPreSignatureV2 => {
                let retained = self.load_post_anchor_claim_pre_signature_v2(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_post_anchor_claim_round_at_terminal_v2(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                self.require_post_anchor_claim_pre_signature_transport_head_v2(
                    &authenticated,
                    current,
                )?;
                (
                    authenticated.canonical_sender_id,
                    authenticated.canonical_sender_sequence,
                    authenticated.terminal_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalRefund => {
                let retained = self.load_operational_final_refund(request.session_id)?;
                let authenticated = self
                    .authenticate_completed_operational_final_refund_at_terminal(
                        request.session_id,
                        retained.terminal_revision,
                    )?;
                self.require_operational_final_refund_transport_head(&authenticated, current)?;
                (
                    authenticated.canonical_sender_id,
                    authenticated.canonical_sender_sequence,
                    authenticated.terminal_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalFinalClaimV2 => {
                let exposure = self.load_operational_final_claim_exposure_v2(request.session_id)?;
                let sequence = self.transport_sequence_at_revision(
                    request.session_id,
                    exposure.dom_claim_sender_id,
                    current.revision(),
                )?;
                (
                    exposure.dom_claim_sender_id,
                    sequence,
                    current.transcript_hash(),
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFund => {
                let gate = self.load_m8_funding_gate(request.session_id)?;
                self.require_m8_final_refund_provenance(&gate, current)?;
                let prepared = PreparedOperationalM8FundingGateV1 {
                    session_id: gate.session_id,
                    gate_digest: gate.digest,
                    refund_tx_hash: gate.refund_tx_hash,
                };
                let vote = self
                    .prepare_next_operational_m8_ready_to_fund_vote_locked(&prepared)?
                    .ok_or(SessionStoreError::FundingAuthorityUnavailable)?;
                (
                    vote.participant_id,
                    vote.sequence,
                    vote.previous_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalM8ReadyToFundV2 => {
                let gate = self.load_m8_funding_gate_v2(request.session_id)?;
                let prepared = self.prepared_operational_m8_funding_gate_v2(&gate);
                let vote = self
                    .prepare_next_operational_m8_ready_to_fund_vote_locked_v2(&prepared)?
                    .ok_or(SessionStoreError::FundingAuthorityUnavailable)?;
                (
                    vote.participant_id,
                    vote.sequence,
                    vote.previous_transcript_hash,
                )
            }
            OutboundDsc1AuthorityClassV1::OperationalAbort => {
                let authenticated =
                    self.authenticate_operational_abort_transport_authority(request.session_id)?;
                self.require_operational_abort_transport_head(&authenticated, current)?;
                (
                    authenticated.canonical_sender_id,
                    authenticated.canonical_sender_sequence,
                    authenticated.predecessor_transcript_hash,
                )
            }
            _ => return Err(SessionStoreError::InvalidTransition),
        };
        if request.sender_id != expected.0
            || request.sequence != expected.1
            || request.previous_transcript_hash != expected.2
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        Ok(())
    }

    fn authenticate_committed_outbound_dsc1_record_locked(
        &self,
        committed: &CommittedOutboundDsc1RecordV1,
        request: &OutboundDsc1SigningRequestRecordV1,
    ) -> Result<(), SessionStoreError> {
        if committed.store_id != self._store_id
            || committed.store_id != request.store_id
            || committed.authority_class != request.authority_class
            || committed.message_type != request.message_type
            || committed.session_id != request.session_id
            || committed.sender_id != request.sender_id
            || committed.sequence != request.sequence
            || committed.request_id != request.request_id
            || committed.request_record_digest != request.digest
            || committed.message_digest != request.unsigned_message_digest
        {
            return Err(SessionStoreError::Quarantined);
        }
        let expected = CommittedOutboundDsc1RecordV1::new(request, &committed.signed_bytes)?;
        if expected.bytes != committed.bytes {
            return Err(SessionStoreError::Quarantined);
        }
        self.require_signed_envelope_matches_outbound_request(request, &committed.signed_bytes)?;
        let accepted_name = transport_message_name(
            committed.session_id,
            committed.sender_id,
            committed.sequence,
            false,
        );
        let bytes = self.messages.read_bounded_file(
            &ValidatedComponent::registered(&accepted_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        )?;
        let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
        self.authenticate_transport_record(&accepted_name, &accepted)?;
        if accepted.equivocation || accepted.signed_bytes != committed.signed_bytes {
            return Err(SessionStoreError::Quarantined);
        }
        let durable =
            self.load_session_revision(accepted.session_id, accepted.successor.revision())?;
        if durable.as_bytes() != accepted.successor.as_bytes() {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(())
    }

    fn authenticate_reconciled_outbound_dsc1_record_locked(
        &self,
        reconciled: &ReconciledOutboundDsc1RecordV1,
        committed: &CommittedOutboundDsc1RecordV1,
        request: &OutboundDsc1SigningRequestRecordV1,
    ) -> Result<(), SessionStoreError> {
        self.authenticate_committed_outbound_dsc1_record_locked(committed, request)?;
        let expected = ReconciledOutboundDsc1RecordV1::new(request, committed)?;
        if reconciled.bytes != expected.bytes
            || reconciled.store_id != self._store_id
            || reconciled.authority_class != committed.authority_class
            || reconciled.message_type != committed.message_type
            || reconciled.session_id != committed.session_id
            || reconciled.sender_id != committed.sender_id
            || reconciled.sequence != committed.sequence
            || reconciled.request_id != committed.request_id
            || reconciled.request_record_digest != committed.request_record_digest
            || reconciled.committed_record_digest != committed.digest
            || reconciled.application_id != committed.application_id
            || reconciled.message_digest != committed.message_digest
            || reconciled.digest != expected.digest
        {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(())
    }

    fn audit_outbound_dsc1_request_locked(
        &self,
        request: &OutboundDsc1SigningRequestRecordV1,
    ) -> Result<(), SessionStoreError> {
        match self.load_committed_outbound_dsc1(
            request.session_id,
            request.sender_id,
            request.sequence,
        ) {
            Ok(committed) => {
                return self.authenticate_committed_outbound_dsc1_record_locked(&committed, request)
            }
            Err(SessionStoreError::SessionNotFound) => {}
            Err(error) => return Err(error),
        }
        let accepted_name = transport_message_name(
            request.session_id,
            request.sender_id,
            request.sequence,
            false,
        );
        match self.messages.read_bounded_file(
            &ValidatedComponent::registered(&accepted_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let accepted = TransportMessageRecordV1::from_bytes(&bytes)?;
                self.authenticate_transport_record(&accepted_name, &accepted)?;
                self.require_signed_envelope_matches_outbound_request(
                    request,
                    &accepted.signed_bytes,
                )?;
                // Loaded once, only on the branch that audits the authority
                // here; the recheck branch below loads its own head.
                let current = self.load_session_locked(request.session_id)?;
                self.require_static_outbound_dsc1_authority_locked(request, &current)
            }
            Err(LinuxCapabilityError::NotFound) => {
                self.revalidate_outbound_dsc1_request_locked(request, false)
            }
            Err(error) => Err(error.into()),
        }
    }

    fn persist_session_record(&self, record: &SessionRecordV1) -> Result<(), SessionStoreError> {
        let final_name = session_record_name(record.session_id(), record.revision());
        let staging_name = format!(".{final_name}.staging");
        publish_immutable(
            &self.records,
            &staging_name,
            &final_name,
            record.as_bytes(),
            SESSION_RECORD_MAX_LEN,
        )
    }

    fn load_session_locked(
        &self,
        session_id: [u8; 32],
    ) -> Result<SessionRecordV1, SessionStoreError> {
        let session_hex = hex_lower(&session_id);
        let mut records = Vec::new();
        self.records.scan_lexicographic(|name, node| {
            if node.node_type != ExpectedNodeType::RegularFile || name.starts_with('.') {
                return Err(LinuxCapabilityError::InvalidObject);
            }
            let Some((name_session, revision)) = parse_session_record_name(name) else {
                return Err(LinuxCapabilityError::InvalidDirectoryEntry);
            };
            if name_session != session_hex {
                return Ok(());
            }
            let bytes = self.records.read_bounded_file(
                &ValidatedComponent::registered(name)?,
                SESSION_RECORD_MAX_LEN,
            )?;
            let record = SessionRecordV1::from_bytes(&bytes)
                .map_err(|_| LinuxCapabilityError::ExactBytesMismatch)?;
            if hex_lower(&record.session_id()) != name_session || record.revision() != revision {
                return Err(LinuxCapabilityError::ExactBytesMismatch);
            }
            records.push(record);
            Ok(())
        })?;
        if let Some(projected) = self
            .recovery_projection
            .lock()
            .map_err(|_| SessionStoreError::Quarantined)?
            .as_ref()
        {
            records.extend(
                projected
                    .records
                    .range((session_id, 0)..=(session_id, u64::MAX))
                    .map(|(_, record)| record.clone()),
            );
        }
        records.sort_by_key(SessionRecordV1::revision);
        let Some(first) = records.first() else {
            return Err(SessionStoreError::SessionNotFound);
        };
        if first.revision() != 0 {
            return Err(SessionStoreError::Quarantined);
        }
        for pair in records.windows(2) {
            let previous = &pair[0];
            let next = &pair[1];
            if next.revision()
                != previous
                    .revision()
                    .checked_add(1)
                    .ok_or(SessionStoreError::Quarantined)?
            {
                return Err(SessionStoreError::Quarantined);
            }
            if require_exact_successor(previous, previous.revision(), next).is_err() {
                return Err(SessionStoreError::Quarantined);
            }
        }
        records.pop().ok_or(SessionStoreError::SessionNotFound)
    }

