    /// Loads and authenticates the retained M.8 funding gate record itself.
    ///
    /// This is a loader: it proves the record decodes and belongs to this exact
    /// session, and nothing else. The final-refund provenance
    /// ([`Self::require_m8_final_refund_provenance`]) is asserted explicitly at
    /// every boundary that mints, emits or commits authority from the gate, not
    /// here. Keeping it here made the loader depend on the liveness of the
    /// transport head, so a session holding a legitimate persist-before-
    /// successor edge answered `SessionNotFound` for a gate that exists, and
    /// [`Self::m8_funding_gate_exists`] then reported an existing authority as
    /// absent to every must-be-absent guard.
    fn load_m8_funding_gate(
        &self,
        session_id: [u8; 32],
    ) -> Result<OperationalM8FundingGateRecordV1, SessionStoreError> {
        let name = m8_funding_gate_name(session_id);
        match self.artifacts.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            M8_FUNDING_GATE_MAX_LEN,
        ) {
            Ok(bytes) => {
                let gate = OperationalM8FundingGateRecordV1::from_bytes(&bytes)?;
                if gate.session_id != session_id {
                    return Err(SessionStoreError::Quarantined);
                }
                Ok(gate)
            }
            Err(LinuxCapabilityError::NotFound) => Err(SessionStoreError::SessionNotFound),
            Err(error) => Err(error.into()),
        }
    }

    fn load_m8_funding_gate_v2(
        &self,
        session_id: [u8; 32],
    ) -> Result<OperationalM8FundingGateRecordV2, SessionStoreError> {
        let name = m8_funding_gate_v2_name(session_id);
        let bytes = match self.artifacts.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            M8_FUNDING_GATE_V2_MAX_LEN,
        ) {
            Ok(bytes) => bytes,
            Err(LinuxCapabilityError::NotFound) => return Err(SessionStoreError::SessionNotFound),
            Err(error) => return Err(error.into()),
        };
        let roster = self.load_transport_roster(session_id)?;
        let gate = OperationalM8FundingGateRecordV2::from_bytes(&roster.chain_id, &bytes)?;
        if gate.role_binding.session_id().0 != session_id {
            return Err(SessionStoreError::Quarantined);
        }
        let directories = self.m8_f7_v2_directories();
        preflight_m8_f7_v2_gate_ancestry(&directories, session_id, &gate)?;
        Ok(gate)
    }

    fn m8_funding_gate_v2_exists(&self, session_id: [u8; 32]) -> Result<bool, SessionStoreError> {
        match self.load_m8_funding_gate_v2(session_id) {
            Ok(_) => Ok(true),
            Err(SessionStoreError::SessionNotFound) => Ok(false),
            Err(error) => Err(error),
        }
    }

    fn require_m8_final_refund_provenance(
        &self,
        gate: &OperationalM8FundingGateRecordV1,
        current: &SessionRecordV1,
    ) -> Result<(), SessionStoreError> {
        let retained = self.load_operational_final_refund(gate.session_id)?;
        let authenticated = self.authenticate_completed_operational_final_refund_at_terminal(
            gate.session_id,
            retained.terminal_revision,
        )?;
        self.require_operational_final_refund_transport_head(&authenticated, current)?;
        let refund = <Transaction as DomDeserialize>::from_bytes(&retained.exact_transaction_bytes)
            .map_err(|_| SessionStoreError::Quarantined)?;
        if gate.session_id != retained.session_id
            || gate.terms_hash != retained.terms_hash
            || gate.chain_id != retained.chain_id
            || gate.refund_template_hash != retained.template_hash
            || gate.refund_unlock_height != retained.refund_unlock_height
            || gate.refund_tx_hash != retained.refund_tx_hash
            || gate.refund_bytes != retained.exact_transaction_bytes
            || gate.shared_output_commitment
                != *refund
                    .inputs
                    .first()
                    .ok_or(SessionStoreError::Quarantined)?
                    .commitment
                    .as_bytes()
            || authenticated.final_refund_record_digest != retained.digest
            || authenticated.refund_tx_hash != gate.refund_tx_hash
            || authenticated.final_refund_payload != gate.refund_bytes
        {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(())
    }

    /// Reports only whether an authenticated M.8 gate record is retained for
    /// this session. It never depends on transport or session liveness.
    fn m8_funding_gate_exists(&self, session_id: [u8; 32]) -> Result<bool, SessionStoreError> {
        match self.load_m8_funding_gate(session_id) {
            Ok(_) => Ok(true),
            Err(SessionStoreError::SessionNotFound) => Ok(false),
            Err(error) => Err(error),
        }
    }

