    fn authenticate_local_transport_signer_binding(
        &self,
        session_id: [u8; 32],
    ) -> Result<LocalTransportSignerBindingRecordV1, SessionStoreError> {
        let retained = self.load_local_transport_signer_binding(session_id)?;
        let roster = self.load_transport_roster(session_id)?;
        let identities = self.load_transport_identity_binding(session_id)?;
        require_transport_identity_binding(&roster, &identities)?;
        let reference = identities
            .references
            .iter()
            .find(|reference| reference.key_reference == retained.key_reference)
            .ok_or(SessionStoreError::Quarantined)?;
        let expected = LocalTransportSignerBindingRecordV1::new(
            self._store_id,
            &roster,
            &identities,
            reference,
        )?;
        let participant = roster
            .participants
            .iter()
            .find(|participant| participant.participant_id == retained.participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        if retained.bytes != expected.bytes
            || retained.noise_public_key != reference.noise_public_key
            || retained.schnorr_public_key != reference.schnorr_public_key
            || retained.direction != participant.direction
            || retained.identity_binding_digest != copy_array(&identities.bytes[338..370])?
            || retained.roster_digest != copy_array(&roster.bytes[212..244])?
        {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(retained)
    }

