    fn load_outbound_dsc1_request(
        &self,
        session_id: [u8; 32],
        sender_id: [u8; 32],
        sequence: u64,
    ) -> Result<OutboundDsc1SigningRequestRecordV1, SessionStoreError> {
        let name = outbound_dsc1_request_name(session_id, sender_id, sequence);
        match self.rosters.read_bounded_file(
            &ValidatedComponent::registered(&name)?,
            OUTBOUND_DSC1_REQUEST_MAX_LEN,
        ) {
            Ok(bytes) => {
                let request = OutboundDsc1SigningRequestRecordV1::from_bytes(&bytes)?;
                if request.session_id != session_id
                    || request.sender_id != sender_id
                    || request.sequence != sequence
                {
                    return Err(SessionStoreError::Quarantined);
                }
                Ok(request)
            }
            Err(LinuxCapabilityError::NotFound) => Err(SessionStoreError::SessionNotFound),
            Err(error) => Err(error.into()),
        }
    }

