    fn require_operational_abort_economic_state(
        &self,
        session_id: [u8; 32],
    ) -> Result<SessionRecordV1, SessionStoreError> {
        let current = self.load_session_locked(session_id)?;
        let mut revision = 0_u64;
        loop {
            let record = self.load_session_revision(session_id, revision)?;
            let irreversible = record.irreversible();
            let chain = record.chain();
            if (!abort_phase_is_strictly_pre_funding(record.phase())
                && !matches!(
                    record.phase(),
                    SessionPhaseV1::Aborted | SessionPhaseV1::FailedClosed
                ))
                || irreversible.funding_authorized
                || irreversible.adaptor_secret_exposed
                || chain.funding != SessionTxObservationV1::Unknown
                || chain.claim != SessionTxObservationV1::Unknown
                || chain.refund != SessionTxObservationV1::Unknown
            {
                return Err(SessionStoreError::InvalidTransition);
            }
            if revision == current.revision() {
                break;
            }
            revision = revision
                .checked_add(1)
                .ok_or(SessionStoreError::Quarantined)?;
        }
        if self.funding_gate_exists(session_id)?
            || self.m8_funding_gate_exists(session_id)?
            || self.any_operational_issuance_exists(session_id)?
            || self.any_operational_commit_exists(session_id)?
            || self.artifact_exists(session_id)?
            || self.consumption_exists(session_id)?
            || self.post_anchor_claim_issuance_exists(session_id)?
            || self.post_anchor_claim_consumption_exists(session_id)?
            || self
                .process_funding_authorities
                .lock()
                .map_err(|_| SessionStoreError::StoreBusy)?
                .contains(&session_id)
        {
            return Err(SessionStoreError::InvalidTransition);
        }
        Ok(current)
    }

