impl ContractsSessionStoreV1 {
    fn persist_verified_m8_funding_store_owned_v2(
        &self,
        capability: OperationalM8FundingPersistenceCapabilityV2,
    ) -> Result<FundingBroadcastV1, SessionStoreError> {
        let _guard = self.operation_lock()?;
        let authorization = capability.authorization();
        let binding = authorization.binding();
        let session_id = *binding.session_id();
        if self.issuance_exists(session_id)?
            || self.m8_issuance_exists(session_id)?
            || self.funding_gate_exists(session_id)?
            || self.m8_funding_gate_exists(session_id)?
            || self.funding_commit_exists(session_id)?
            || self.m8_funding_commit_exists(session_id)?
            || self.operational_abort_transport_authority_exists(session_id)?
        {
            return Err(SessionStoreError::FundingAuthorityUnavailable);
        }
        let gate = self.load_m8_funding_gate_v2(session_id)?;
        let issuance = self.load_m8_funding_issuance_v2(session_id)?;
        let roster = self.load_transport_roster(session_id)?;
        let directories = self.m8_f7_v2_directories();
        let gate_bound = preflight_m8_f7_v2_gate_ancestry(&directories, session_id, &gate)?;
        authenticate_m8_f7_v2_issuance_with_vote_ancestry(
            &directories,
            &roster.chain_id,
            &roster,
            &gate,
            &gate_bound,
            &issuance,
        )?;
        let current = self.load_session_locked(session_id)?;
        let (signed_template_bytes, signed_template_hash) =
            canonical_template_v1(capability.transaction())
                .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let shared_output_matches = capability
            .transaction()
            .outputs
            .iter()
            .filter(|output| {
                output.commitment.as_bytes() == &gate.ready_binding.shared_output_commitment()
            })
            .count();
        self.audit_funding_authorized_signing_prefix(
            session_id,
            &roster.chain_id,
            &gate.ready_binding.terms_hash(),
            &issuance.unsigned_template_bytes,
            binding.funding_template_hash(),
            &issuance.funding_authorized_record,
            &current,
            true,
        )
        .map_err(|_| SessionStoreError::FundingAuthorityUnavailable)?;
        if self.consumption_exists(session_id)?
            || self.m8_funding_commit_v2_exists(session_id)?
            || self.artifact_exists(session_id)?
            || issuance.binding != *binding
            || issuance.digest != *authorization.issuance_record_digest()
            || issuance.authorized_revision != authorization.authorized_revision()
            || issuance.gate_record_digest != gate.digest
            || binding.chain_id() != &roster.chain_id
            || binding.terms_hash() != &gate.ready_binding.terms_hash()
            || binding.shared_output_commitment() != &gate.ready_binding.shared_output_commitment()
            || binding.bp_statement_hash() != &gate.ready_binding.bp_statement_hash()
            || binding.funding_template_hash() != &gate.ready_binding.funding_template_hash()
            || binding.claim_template_hash() != &gate.ready_binding.claim_template_hash()
            || binding.claim_adaptor_point() != &gate.ready_binding.adaptor_point_sec1()
            || binding.m8_policy_digest() != &gate.ready_binding.m8_policy_digest()
            || binding.refund_tx_hash() != &gate.ready_binding.refund_tx_hash()
            || binding.backup_receipt_hash() != &gate.ready_binding.backup_receipt_hash()
            || binding.final_claim_role_binding_digest() != &gate.role_binding.digest()
            || binding.ready_binding_digest() != &gate.ready_binding.digest()
            || current.phase() != SessionPhaseV1::FundingAuthorized
            || !current.irreversible().funding_authorized
            || capability.template_hash() != binding.funding_template_hash()
            || capability.template_hash() != &signed_template_hash
            || signed_template_bytes != issuance.unsigned_template_bytes
            || capability.shared_output_commitment()
                != &gate.ready_binding.shared_output_commitment()
            || shared_output_matches != 1
            || capability.canonical_bytes()
                != capability
                    .transaction()
                    .to_bytes()
                    .map_err(|_| SessionStoreError::InvalidDomTransaction)?
            || *blake2b_256(capability.canonical_bytes()).as_bytes() != *capability.tx_hash()
        {
            return Err(SessionStoreError::FundingAuthorityUnavailable);
        }
        capability
            .verify(binding.chain_id(), gate.validation_tip_height)
            .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let artifact = FundingArtifactRecordV1::new_operational_m8_v2(
            &gate,
            current.revision(),
            capability.canonical_bytes(),
        )?;
        let funding_broadcast = current.advance(
            current.revision(),
            SessionPhaseV1::FundingBroadcast,
            current.transcript_hash(),
            current.irreversible(),
            current.chain(),
            current.encrypted_payload(),
        )?;
        let consumption = FundingConsumptionRecordV1::new(
            session_id,
            current.revision(),
            artifact.digest,
            &funding_broadcast,
        )?;
        let commit = OperationalM8FundingCommitRecordV2::new(
            issuance.digest,
            gate.role_binding.digest(),
            gate.ready_binding.digest(),
            artifact,
            consumption,
        )?;
        self.verify_m8_v2_commit_against_authority(&commit)?;
        self.persist_m8_funding_commit_v2(&commit)?;
        test_crash_hook("operational-m8-v2-sink-after-commit-intent-persist");
        self.persist_artifact(&commit.artifact)?;
        test_crash_hook("operational-m8-v2-sink-after-artifact-persist");
        self.persist_consumption(&commit.consumption)?;
        test_crash_hook("operational-m8-v2-sink-after-consumption-persist");
        self.persist_session_record(&funding_broadcast)?;
        test_crash_hook("operational-m8-v2-sink-after-session-persist");
        let durable_commit = self.load_m8_funding_commit_v2(session_id)?;
        let durable = self.load_session_locked(session_id)?;
        let durable_artifact = self.load_artifact(session_id)?;
        let durable_consumption = self.load_consumption(session_id)?;
        if durable_commit.bytes != commit.bytes
            || durable.as_bytes() != funding_broadcast.as_bytes()
            || durable_artifact.bytes != commit.artifact.bytes
            || durable_consumption.bytes != commit.consumption.bytes
        {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(FundingBroadcastV1 {
            exact_bytes: commit.artifact.funding_bytes,
        })
    }
}

impl OperationalM8FundingTransactionSinkV2 for M8FundingTransactionSinkRefV2<'_> {
    type Error = SessionStoreError;
    type PersistedFunding = FundingBroadcastV1;

    fn persist_verified_m8_funding_v2(
        &mut self,
        capability: OperationalM8FundingPersistenceCapabilityV2,
    ) -> Result<Self::PersistedFunding, Self::Error> {
        self.store
            .persist_verified_m8_funding_store_owned_v2(capability)
    }
}

impl OperationalClaimTransactionSinkV1 for FinalClaimTransactionSinkRefV2<'_> {
    type Error = SessionStoreError;
    type PersistedClaim = PreparedOperationalFinalClaimSubmissionV2;

    fn persist_verified_claim(
        &mut self,
        capability: OperationalClaimPersistenceCapabilityV1,
    ) -> Result<Self::PersistedClaim, Self::Error> {
        self.store.persist_verified_final_claim_store_owned_v2(
            self.authorization,
            self.chain_id,
            self.action_scope_digest,
            self.validation_height,
            capability,
        )
    }
}

