#[derive(Clone, Copy, Eq, PartialEq)]
enum PostAnchorClaimAuthorizationStateV2 {
    Issued,
    Consumed,
}

/// Durable post-anchor claim profile of one session.
///
/// The value is produced only by
/// [`ContractsSessionStoreV1::post_anchor_profile_selection`] and is carried
/// inside the signing transport context and its linear handle, so a handle
/// issued under one profile can never be accepted under the other.
#[derive(Clone, Copy, Eq, PartialEq)]
enum PostAnchorProfileV1V2 {
    /// No post-anchor artifact of either profile is durable.
    None,
    /// Only legacy V1 artifacts are durable; they stay recovery-only.
    LegacyV1,
    /// Only productive M.8/F7 V2 artifacts are durable.
    ProductiveV2,
}

impl PostAnchorClaimAuthorizationStateV2 {
    const fn byte(self) -> u8 {
        match self {
            Self::Issued => 0x01,
            Self::Consumed => 0x02,
        }
    }

    fn from_byte(byte: u8) -> Result<Self, SessionStoreError> {
        match byte {
            0x01 => Ok(Self::Issued),
            0x02 => Ok(Self::Consumed),
            _ => Err(SessionStoreError::Quarantined),
        }
    }
}

