/// record that merely claims admission cannot pass.
struct OperationalFinalClaimAdmissionRecordV2 {
    chain_id: [u8; 32],
    session_id: [u8; 32],
    settlement_id: [u8; 32],
    exposure_record_digest: [u8; 32],
    tx_hash: [u8; 32],
    dom_claim_sender_id: [u8; 32],
    final_claim_receiver_id: [u8; 32],
    action_scope_digest: [u8; 32],
    admitted_height: u64,
    receipt_state_tag: u8,
    receipt_relayed: u8,
    receipt_facts_digest: [u8; 32],
    bound_session_revision: u64,
    bound_session_record_digest: [u8; 32],
    open_instance_id: [u8; 32],
}

/// Exact field set of one `DOMFCAD2` publication.
