#[derive(Clone, Copy)]
struct SigningSemanticParticipantRefV1<'binding> {
    participant_id: &'binding [u8; 32],
    signing_public_key: &'binding PublicKey,
    direction: DirectionV1,
}

trait SigningSemanticBindingAccessV1 {
    fn participant_count(&self) -> usize;
    fn participant(&self, index: usize) -> Option<SigningSemanticParticipantRefV1<'_>>;
    fn transaction_template(&self) -> &Transaction;
    fn template_hash(&self) -> &[u8; 32];
    fn kernel_index(&self) -> usize;
    fn adaptor_point(&self) -> Option<&PublicKey>;

    fn signing_index(&self, participant_id: &[u8; 32]) -> Result<u16, SessionStoreError> {
        let signing_key = (0..self.participant_count())
            .filter_map(|index| self.participant(index))
            .find(|participant| participant.participant_id == participant_id)
            .map(|participant| participant.signing_public_key.to_compressed_bytes())
            .ok_or(SessionStoreError::Quarantined)?;
        let mut signing_keys: Vec<[u8; 33]> = (0..self.participant_count())
            .filter_map(|index| self.participant(index))
            .map(|participant| participant.signing_public_key.to_compressed_bytes())
            .collect();
        signing_keys.sort_unstable();
        signing_keys
            .iter()
            .position(|candidate| candidate == &signing_key)
            .and_then(|index| u16::try_from(index).ok())
            .ok_or(SessionStoreError::Quarantined)
    }
}

impl SigningSemanticBindingAccessV1 for DecodedSigningSessionBindingV1 {
    fn participant_count(&self) -> usize {
        self.roster.entries().len()
    }

    fn participant(&self, index: usize) -> Option<SigningSemanticParticipantRefV1<'_>> {
        self.roster
            .entries()
            .get(index)
            .map(|participant| SigningSemanticParticipantRefV1 {
                participant_id: participant.participant_id(),
                signing_public_key: participant.signing_public_key(),
                direction: participant.direction(),
            })
    }

    fn transaction_template(&self) -> &Transaction {
        &self.transaction_template
    }

    fn template_hash(&self) -> &[u8; 32] {
        &self.template_hash
    }

    fn kernel_index(&self) -> usize {
        self.kernel_index
    }

    fn adaptor_point(&self) -> Option<&PublicKey> {
        self.adaptor_point.as_ref()
    }
}

impl SigningSemanticBindingAccessV1 for AuthenticatedSigningReplayBindingV1 {
    fn participant_count(&self) -> usize {
        self.participants.len()
    }

    fn participant(&self, index: usize) -> Option<SigningSemanticParticipantRefV1<'_>> {
        self.participants
            .get(index)
            .map(|participant| SigningSemanticParticipantRefV1 {
                participant_id: &participant.participant_id,
                signing_public_key: &participant.signing_public_key,
                direction: participant.direction,
            })
    }

    fn transaction_template(&self) -> &Transaction {
        &self.transaction_template
    }

    fn template_hash(&self) -> &[u8; 32] {
        &self.template_hash
    }

    fn kernel_index(&self) -> usize {
        self.kernel_index
    }

    fn adaptor_point(&self) -> Option<&PublicKey> {
        self.adaptor_point.as_ref()
    }
}

