#[derive(Clone, Copy, Eq, PartialEq)]
#[repr(u8)]
enum OutboundDsc1AuthorityClassV1 {
    OperationalTemplateCommit = 1,
    PostAnchorClaimPreSignature = 2,
    OperationalFinalRefund = 3,
    OperationalM8ReadyToFund = 4,
    OperationalAbort = 5,
    EarlyOffer = 6,
    EarlyAccept = 7,
    EarlyShareCommit = 8,
    EarlyShareReveal = 9,
    OperationalBpCommonCommit = 10,
    OperationalBpCommonReveal = 11,
    OperationalBpRoundCommit = 12,
    OperationalBpRound1 = 13,
    OperationalBpRound2 = 14,
    OperationalBpProof = 15,
    OperationalSigningNonceCommitment = 16,
    OperationalSigningNonceReveal = 17,
    OperationalSigningPartialSignature = 18,
    OperationalM8ReadyToFundV2 = 19,
    PostAnchorClaimPreSignatureV2 = 20,
    OperationalFinalClaimV2 = 21,
}

impl OutboundDsc1AuthorityClassV1 {
    const fn message_type(self) -> u8 {
        match self {
            Self::EarlyOffer => 0x01,
            Self::EarlyAccept => 0x02,
            Self::EarlyShareCommit => 0x03,
            Self::EarlyShareReveal => 0x04,
            Self::OperationalBpCommonCommit => 0x05,
            Self::OperationalBpCommonReveal => 0x06,
            Self::OperationalBpRoundCommit => 0x07,
            Self::OperationalBpRound1 => 0x08,
            Self::OperationalBpRound2 => 0x09,
            Self::OperationalBpProof => 0x0a,
            Self::OperationalTemplateCommit => 0x0b,
            Self::OperationalSigningNonceCommitment => 0x0c,
            Self::OperationalSigningNonceReveal => 0x0d,
            Self::OperationalSigningPartialSignature => 0x0e,
            Self::PostAnchorClaimPreSignature | Self::PostAnchorClaimPreSignatureV2 => 0x0f,
            Self::OperationalFinalRefund => 0x10,
            Self::OperationalM8ReadyToFund | Self::OperationalM8ReadyToFundV2 => 0x11,
            Self::OperationalFinalClaimV2 => 0x12,
            Self::OperationalAbort => 0x13,
        }
    }

    fn for_early_message_type(message_type: u8) -> Result<Self, SessionStoreError> {
        match message_type {
            0x01 => Ok(Self::EarlyOffer),
            0x02 => Ok(Self::EarlyAccept),
            0x03 => Ok(Self::EarlyShareCommit),
            0x04 => Ok(Self::EarlyShareReveal),
            _ => Err(SessionStoreError::InvalidTransition),
        }
    }

    fn for_operational_bp_message_type(message_type: u8) -> Result<Self, SessionStoreError> {
        match message_type {
            0x05 => Ok(Self::OperationalBpCommonCommit),
            0x06 => Ok(Self::OperationalBpCommonReveal),
            0x07 => Ok(Self::OperationalBpRoundCommit),
            0x08 => Ok(Self::OperationalBpRound1),
            0x09 => Ok(Self::OperationalBpRound2),
            0x0a => Ok(Self::OperationalBpProof),
            _ => Err(SessionStoreError::InvalidTransition),
        }
    }

    fn for_operational_signing_message_type(message_type: u8) -> Result<Self, SessionStoreError> {
        match message_type {
            0x0c => Ok(Self::OperationalSigningNonceCommitment),
            0x0d => Ok(Self::OperationalSigningNonceReveal),
            0x0e => Ok(Self::OperationalSigningPartialSignature),
            _ => Err(SessionStoreError::InvalidTransition),
        }
    }

    const fn is_early(self) -> bool {
        matches!(
            self,
            Self::EarlyOffer | Self::EarlyAccept | Self::EarlyShareCommit | Self::EarlyShareReveal
        )
    }

    const fn is_operational_bp(self) -> bool {
        matches!(
            self,
            Self::OperationalBpCommonCommit
                | Self::OperationalBpCommonReveal
                | Self::OperationalBpRoundCommit
                | Self::OperationalBpRound1
                | Self::OperationalBpRound2
                | Self::OperationalBpProof
        )
    }

    const fn is_operational_signing(self) -> bool {
        matches!(
            self,
            Self::OperationalSigningNonceCommitment
                | Self::OperationalSigningNonceReveal
                | Self::OperationalSigningPartialSignature
        )
    }
}

impl TryFrom<u8> for OutboundDsc1AuthorityClassV1 {
    type Error = SessionStoreError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            1 => Ok(Self::OperationalTemplateCommit),
            2 => Ok(Self::PostAnchorClaimPreSignature),
            3 => Ok(Self::OperationalFinalRefund),
            4 => Ok(Self::OperationalM8ReadyToFund),
            5 => Ok(Self::OperationalAbort),
            6 => Ok(Self::EarlyOffer),
            7 => Ok(Self::EarlyAccept),
            8 => Ok(Self::EarlyShareCommit),
            9 => Ok(Self::EarlyShareReveal),
            10 => Ok(Self::OperationalBpCommonCommit),
            11 => Ok(Self::OperationalBpCommonReveal),
            12 => Ok(Self::OperationalBpRoundCommit),
            13 => Ok(Self::OperationalBpRound1),
            14 => Ok(Self::OperationalBpRound2),
            15 => Ok(Self::OperationalBpProof),
            16 => Ok(Self::OperationalSigningNonceCommitment),
            17 => Ok(Self::OperationalSigningNonceReveal),
            18 => Ok(Self::OperationalSigningPartialSignature),
            19 => Ok(Self::OperationalM8ReadyToFundV2),
            20 => Ok(Self::PostAnchorClaimPreSignatureV2),
            21 => Ok(Self::OperationalFinalClaimV2),
            _ => Err(SessionStoreError::Quarantined),
        }
    }
}

