impl FundingArtifactRecordV1 {
    fn new_operational_m8_v2(
        gate: &OperationalM8FundingGateRecordV2,
        authorized_revision: u64,
        funding_bytes: &[u8],
    ) -> Result<Self, SessionStoreError> {
        Self::new_operational_fields(
            gate.role_binding.session_id().0,
            gate.ready_binding.terms_hash(),
            authorized_revision,
            gate.ready_binding.refund_unlock_height(),
            &gate.refund_bytes,
            funding_bytes,
        )
    }

    fn new_operational_m8(
        gate: &OperationalM8FundingGateRecordV1,
        authorized_revision: u64,
        funding_bytes: &[u8],
    ) -> Result<Self, SessionStoreError> {
        Self::new_operational_fields(
            gate.session_id,
            gate.terms_hash,
            authorized_revision,
            gate.refund_unlock_height,
            &gate.refund_bytes,
            funding_bytes,
        )
    }

    fn new_operational(
        gate: &OperationalFundingGateRecordV1,
        authorized_revision: u64,
        funding_bytes: &[u8],
    ) -> Result<Self, SessionStoreError> {
        Self::new_operational_fields(
            gate.session_id,
            gate.terms_hash,
            authorized_revision,
            gate.refund_unlock_height,
            &gate.refund_bytes,
            funding_bytes,
        )
    }

    fn new_operational_fields(
        session_id: [u8; 32],
        terms_hash: [u8; 32],
        authorized_revision: u64,
        refund_unlock_height: u64,
        refund_bytes: &[u8],
        funding_bytes: &[u8],
    ) -> Result<Self, SessionStoreError> {
        if funding_bytes.is_empty() || funding_bytes.len() > DOM_TRANSACTION_MAX_LEN {
            return Err(SessionStoreError::InvalidDomTransaction);
        }
        let refund_len = u32::try_from(refund_bytes.len())
            .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let funding_len = u32::try_from(funding_bytes.len())
            .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let total = ARTIFACT_PREFIX_LEN
            .checked_add(refund_bytes.len())
            .and_then(|value| value.checked_add(funding_bytes.len()))
            .and_then(|value| value.checked_add(DIGEST_LEN))
            .ok_or(SessionStoreError::InvalidDomTransaction)?;
        if total > FUNDING_ARTIFACT_MAX_LEN {
            return Err(SessionStoreError::InvalidDomTransaction);
        }
        let funding_digest = tagged_hash(FUNDING_HASH_TAG, funding_bytes);
        let refund_digest = tagged_hash(REFUND_HASH_TAG, refund_bytes);
        let mut bytes = vec![0; total];
        bytes[..8].copy_from_slice(ARTIFACT_MAGIC);
        bytes[8..10].copy_from_slice(&FORMAT_VERSION.to_le_bytes());
        bytes[16..48].copy_from_slice(&session_id);
        bytes[48..80].copy_from_slice(&terms_hash);
        bytes[80..88].copy_from_slice(&authorized_revision.to_le_bytes());
        bytes[88..96].copy_from_slice(&refund_unlock_height.to_le_bytes());
        bytes[96..100].copy_from_slice(&refund_len.to_le_bytes());
        bytes[100..104].copy_from_slice(&funding_len.to_le_bytes());
        bytes[104..136].copy_from_slice(&refund_digest);
        bytes[136..168].copy_from_slice(&funding_digest);
        let refund_end = ARTIFACT_PREFIX_LEN + refund_bytes.len();
        bytes[ARTIFACT_PREFIX_LEN..refund_end].copy_from_slice(refund_bytes);
        bytes[refund_end..total - DIGEST_LEN].copy_from_slice(funding_bytes);
        let digest = tagged_hash(ARTIFACT_HASH_TAG, &bytes[..total - DIGEST_LEN]);
        bytes[total - DIGEST_LEN..].copy_from_slice(&digest);
        Ok(Self {
            bytes,
            session_id,
            terms_hash,
            authorized_revision,
            refund_unlock_height,
            refund_bytes: refund_bytes.to_vec(),
            funding_bytes: funding_bytes.to_vec(),
            digest,
        })
    }

    fn new(
        session_id: [u8; 32],
        terms_hash: [u8; 32],
        authorized_revision: u64,
        verified: VerifiedFundingArtifactsV1,
    ) -> Result<Self, SessionStoreError> {
        let refund_len = u32::try_from(verified.refund_bytes.len())
            .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let funding_len = u32::try_from(verified.funding_bytes.len())
            .map_err(|_| SessionStoreError::InvalidDomTransaction)?;
        let payload_len = verified
            .refund_bytes
            .len()
            .checked_add(verified.funding_bytes.len())
            .ok_or(SessionStoreError::InvalidDomTransaction)?;
        let total = ARTIFACT_PREFIX_LEN
            .checked_add(payload_len)
            .and_then(|value| value.checked_add(DIGEST_LEN))
            .ok_or(SessionStoreError::InvalidDomTransaction)?;
        if total > FUNDING_ARTIFACT_MAX_LEN
            || verified.session_id != session_id
            || verified.terms_hash != terms_hash
        {
            return Err(SessionStoreError::InvalidDomTransaction);
        }
        let mut bytes = vec![0; total];
        bytes[..8].copy_from_slice(ARTIFACT_MAGIC);
        bytes[8..10].copy_from_slice(&FORMAT_VERSION.to_le_bytes());
        bytes[16..48].copy_from_slice(&session_id);
        bytes[48..80].copy_from_slice(&terms_hash);
        bytes[80..88].copy_from_slice(&authorized_revision.to_le_bytes());
        bytes[88..96].copy_from_slice(&verified.refund_unlock_height.to_le_bytes());
        bytes[96..100].copy_from_slice(&refund_len.to_le_bytes());
        bytes[100..104].copy_from_slice(&funding_len.to_le_bytes());
        bytes[104..136].copy_from_slice(&verified.refund_digest);
        bytes[136..168].copy_from_slice(&verified.funding_digest);
        let refund_end = ARTIFACT_PREFIX_LEN + verified.refund_bytes.len();
        bytes[ARTIFACT_PREFIX_LEN..refund_end].copy_from_slice(&verified.refund_bytes);
        bytes[refund_end..total - DIGEST_LEN].copy_from_slice(&verified.funding_bytes);
        let digest = tagged_hash(ARTIFACT_HASH_TAG, &bytes[..total - DIGEST_LEN]);
        bytes[total - DIGEST_LEN..].copy_from_slice(&digest);
        Ok(Self {
            bytes,
            session_id,
            terms_hash,
            authorized_revision,
            refund_unlock_height: verified.refund_unlock_height,
            refund_bytes: verified.refund_bytes,
            funding_bytes: verified.funding_bytes,
            digest,
        })
    }

    fn from_bytes(bytes: &[u8]) -> Result<Self, SessionStoreError> {
        if bytes.len() < ARTIFACT_PREFIX_LEN + DIGEST_LEN
            || bytes.len() > FUNDING_ARTIFACT_MAX_LEN
            || &bytes[..8] != ARTIFACT_MAGIC
            || u16::from_le_bytes([bytes[8], bytes[9]]) != FORMAT_VERSION
            || bytes[10..16] != [0; 6]
        {
            return Err(SessionStoreError::Quarantined);
        }
        let refund_len = u32::from_le_bytes(copy_array(&bytes[96..100])?) as usize;
        let funding_len = u32::from_le_bytes(copy_array(&bytes[100..104])?) as usize;
        let refund_unlock_height = u64::from_le_bytes(copy_array(&bytes[88..96])?);
        let total = ARTIFACT_PREFIX_LEN
            .checked_add(refund_len)
            .and_then(|value| value.checked_add(funding_len))
            .and_then(|value| value.checked_add(DIGEST_LEN))
            .ok_or(SessionStoreError::Quarantined)?;
        if total != bytes.len() || refund_len == 0 || funding_len == 0 || refund_unlock_height == 0
        {
            return Err(SessionStoreError::Quarantined);
        }
        let digest = tagged_hash(ARTIFACT_HASH_TAG, &bytes[..total - DIGEST_LEN]);
        if bytes[total - DIGEST_LEN..] != digest {
            return Err(SessionStoreError::Quarantined);
        }
        let refund_end = ARTIFACT_PREFIX_LEN + refund_len;
        if tagged_hash(REFUND_HASH_TAG, &bytes[ARTIFACT_PREFIX_LEN..refund_end]) != bytes[104..136]
            || tagged_hash(FUNDING_HASH_TAG, &bytes[refund_end..total - DIGEST_LEN])
                != bytes[136..168]
        {
            return Err(SessionStoreError::Quarantined);
        }
        let session_id = copy_array(&bytes[16..48])?;
        let terms_hash = copy_array(&bytes[48..80])?;
        if session_id == [0; 32] || terms_hash == [0; 32] {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(Self {
            bytes: bytes.to_vec(),
            session_id,
            terms_hash,
            authorized_revision: u64::from_le_bytes(copy_array(&bytes[80..88])?),
            refund_unlock_height,
            refund_bytes: bytes[ARTIFACT_PREFIX_LEN..refund_end].to_vec(),
            funding_bytes: bytes[refund_end..total - DIGEST_LEN].to_vec(),
            digest,
        })
    }
}

struct FundingConsumptionRecordV1 {
    bytes: Vec<u8>,
    session_id: [u8; 32],
    authorized_revision: u64,
    artifact_digest: [u8; 32],
    broadcast_record_digest: [u8; 32],
}

impl FundingConsumptionRecordV1 {
    fn new(
        session_id: [u8; 32],
        authorized_revision: u64,
        artifact_digest: [u8; 32],
        broadcast_record: &SessionRecordV1,
    ) -> Result<Self, SessionStoreError> {
        let successor_len = u32::try_from(broadcast_record.as_bytes().len())
            .map_err(|_| SessionStoreError::Canonical)?;
        let total = CONSUMPTION_PREFIX_LEN
            .checked_add(broadcast_record.as_bytes().len())
            .and_then(|value| value.checked_add(DIGEST_LEN))
            .ok_or(SessionStoreError::Canonical)?;
        if total > CONSUMPTION_MAX_LEN {
            return Err(SessionStoreError::Canonical);
        }
        let mut bytes = vec![0; total];
        bytes[..8].copy_from_slice(CONSUMPTION_MAGIC);
        bytes[8..10].copy_from_slice(&FORMAT_VERSION.to_le_bytes());
        bytes[16..48].copy_from_slice(&session_id);
        bytes[48..56].copy_from_slice(&authorized_revision.to_le_bytes());
        bytes[56..88].copy_from_slice(&artifact_digest);
        bytes[88..120].copy_from_slice(broadcast_record.digest());
        bytes[120..124].copy_from_slice(&successor_len.to_le_bytes());
        bytes[CONSUMPTION_PREFIX_LEN..total - DIGEST_LEN]
            .copy_from_slice(broadcast_record.as_bytes());
        let digest = tagged_hash(CONSUMPTION_HASH_TAG, &bytes[..total - DIGEST_LEN]);
        bytes[total - DIGEST_LEN..].copy_from_slice(&digest);
        Ok(Self {
            bytes,
            session_id,
            authorized_revision,
            artifact_digest,
            broadcast_record_digest: *broadcast_record.digest(),
        })
    }

    fn from_bytes(bytes: &[u8]) -> Result<Self, SessionStoreError> {
        if bytes.len() < CONSUMPTION_PREFIX_LEN + DIGEST_LEN
            || bytes.len() > CONSUMPTION_MAX_LEN
            || &bytes[..8] != CONSUMPTION_MAGIC
            || u16::from_le_bytes([bytes[8], bytes[9]]) != FORMAT_VERSION
            || bytes[10..16] != [0; 6]
            || bytes[124..128] != [0; 4]
        {
            return Err(SessionStoreError::Quarantined);
        }
        let successor_len = u32::from_le_bytes(copy_array(&bytes[120..124])?) as usize;
        let total = CONSUMPTION_PREFIX_LEN
            .checked_add(successor_len)
            .and_then(|value| value.checked_add(DIGEST_LEN))
            .ok_or(SessionStoreError::Quarantined)?;
        if total != bytes.len()
            || successor_len == 0
            || bytes[total - DIGEST_LEN..]
                != tagged_hash(CONSUMPTION_HASH_TAG, &bytes[..total - DIGEST_LEN])
        {
            return Err(SessionStoreError::Quarantined);
        }
        let successor =
            SessionRecordV1::from_bytes(&bytes[CONSUMPTION_PREFIX_LEN..total - DIGEST_LEN])?;
        let session_id = copy_array(&bytes[16..48])?;
        let authorized_revision = u64::from_le_bytes(copy_array(&bytes[48..56])?);
        let broadcast_record_digest = copy_array(&bytes[88..120])?;
        if successor.session_id() != session_id
            || successor.revision()
                != authorized_revision
                    .checked_add(1)
                    .ok_or(SessionStoreError::Quarantined)?
            || successor.phase() != SessionPhaseV1::FundingBroadcast
            || successor.digest() != &broadcast_record_digest
        {
            return Err(SessionStoreError::Quarantined);
        }
        Ok(Self {
            bytes: bytes.to_vec(),
            session_id,
            authorized_revision,
            artifact_digest: copy_array(&bytes[56..88])?,
            broadcast_record_digest,
        })
    }

    fn broadcast_record(&self) -> Result<SessionRecordV1, SessionStoreError> {
        let end = self
            .bytes
            .len()
            .checked_sub(DIGEST_LEN)
            .ok_or(SessionStoreError::Quarantined)?;
        SessionRecordV1::from_bytes(&self.bytes[CONSUMPTION_PREFIX_LEN..end])
            .map_err(SessionStoreError::from)
    }
}

fn require_exact_successor(
    current: &SessionRecordV1,
    expected_revision: u64,
    successor: &SessionRecordV1,
) -> Result<(), SessionStoreError> {
    let reconstructed = current.advance(
        expected_revision,
        successor.phase(),
        successor.transcript_hash(),
        successor.irreversible(),
        successor.chain(),
        successor.encrypted_payload(),
    )?;
    if reconstructed.as_bytes() != successor.as_bytes() {
        return Err(SessionStoreError::Canonical);
    }
    Ok(())
}

/// Whether an observed claim is buried at least `required_depth` blocks under
/// the tip it was proved against.
///
/// The caller supplies the tip, and every caller in this file supplies the pair
/// the observation carried. That pair is walked to from the observed block only
/// when the observation came through the sealed producer path; the
/// `evidence-only` seam accepts any pair a caller writes, and neither this
/// predicate nor its callers can tell the two apart. So this answers "is it
/// buried this deep under that tip", never "is that tip a descendant of it" —
/// ancestry is the producer's guarantee, not a property established here.
///
/// The separate question of whether the session is looking at that same chain
/// is answered by its own crossing at each call site, and this predicate never
/// answers it either.
///
/// This is the arithmetic of [`confirmed_funding_projection_has_depth`]: the
/// depth policy is one number frozen in canonical settlement terms —
/// `dom_minimum_confirmations` — and applying it to the claim with a second
/// formula would let the claim and the funding disagree about what "confirmed"
/// means. Depth one means the observed block is the tip, and only then must the
/// tip identity be that block.
///
/// One guard is deliberately stricter here, and it is not a copy: an observed
/// height of zero is refused. The funding side does not need that check
/// because its height comes from a `Confirmed` projection the Store itself
/// wrote; the claim's height comes from an observation, and genesis is not a
/// place a claim is observed. The divergence is toward refusal, never toward
/// acceptance.
fn observed_claim_has_depth(
    observed_height: u64,
    observed_block_id: [u8; 32],
    tip_height: u64,
    tip_id: [u8; 32],
    required_depth: u32,
) -> bool {
    if required_depth == 0
        || observed_height == 0
        || observed_block_id == [0; 32]
        || tip_id == [0; 32]
    {
        return false;
    }
    let Some(minimum_tip_height) = observed_height.checked_add(u64::from(required_depth) - 1)
    else {
        return false;
    };
    tip_height >= minimum_tip_height
        && (tip_height != observed_height || tip_id == observed_block_id)
}

fn confirmed_funding_projection_has_depth(
    chain: SessionChainProjectionV1,
    required_depth: u32,
) -> bool {
    let SessionTxObservationV1::Confirmed { block_id, height } = chain.funding else {
        return false;
    };
    if required_depth == 0 || block_id == [0; 32] || chain.tip_id == [0; 32] {
        return false;
    }
    let Some(minimum_tip_height) = height.checked_add(u64::from(required_depth) - 1) else {
        return false;
    };
    chain.tip_height >= minimum_tip_height
        && (chain.tip_height != height || chain.tip_id == block_id)
}

fn post_anchor_claim_projection_is_live(
    issued: &PostAnchorClaimAuthorizationRecordV1,
    bound: &SessionRecordV1,
    current: &SessionRecordV1,
    chain: SessionChainProjectionV1,
) -> bool {
    current.session_id() == issued.session_id
        && current.revision() >= bound.revision()
        && current.phase() == SessionPhaseV1::FundingConfirmed
        && current.terms_hash() == bound.terms_hash()
        && current.irreversible() == bound.irreversible()
        && current.encrypted_payload() == bound.encrypted_payload()
        && chain.funding == bound.chain().funding
        && chain.claim == bound.chain().claim
        && chain.refund == bound.chain().refund
        && confirmed_funding_projection_has_depth(chain, issued.dom_minimum_confirmations)
}

fn is_projection_only_descendant(anchor: &SessionRecordV1, descendant: &SessionRecordV1) -> bool {
    descendant.session_id() == anchor.session_id()
        && descendant.revision() >= anchor.revision()
        && descendant.phase() == anchor.phase()
        && descendant.terms_hash() == anchor.terms_hash()
        && descendant.transcript_hash() == anchor.transcript_hash()
        && descendant.irreversible() == anchor.irreversible()
        && descendant.encrypted_payload() == anchor.encrypted_payload()
}

fn publish_immutable(
    directory: &RetainedDirectory,
    staging_name: &str,
    final_name: &str,
    exact_bytes: &[u8],
    maximum_length: usize,
) -> Result<(), SessionStoreError> {
    let final_component = ValidatedComponent::registered(final_name)?;
    match directory.read_bounded_file(&final_component, maximum_length) {
        Ok(existing) if existing == exact_bytes => return Ok(()),
        Ok(_) => return Err(SessionStoreError::Conflict),
        Err(LinuxCapabilityError::NotFound) => {}
        Err(error) => return Err(error.into()),
    }
    let staging_component = ValidatedComponent::registered(staging_name)?;
    if let Ok(stale) = directory.open_file(&staging_component, false) {
        directory.unlink_verified_file(&staging_component, &stale)?;
    }
    let staging = directory.create_immutable_file(&staging_component, exact_bytes)?;
    directory.rename_no_replace(&staging_component, &final_component, &staging)?;
    let persisted = directory.read_bounded_file(&final_component, maximum_length)?;
    if persisted != exact_bytes {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

/// Whether one M.8/F7 artifact participates in the per-session profile choice.
///
/// Only an artifact that exists in *both* profiles can express a V1-versus-V2
/// decision. `BackupProvenance` and `FinalRefund` are declared V2-only in
/// [`M8_F7_DURABLE_PROFILE_DESCRIPTORS`]: they are the single encoding written
/// in both lanes, not profile markers. The answer is derived from that table
/// rather than from a fixed list, so a future V2-only artifact cannot silently
/// start poisoning the mask.
fn m8_f7_artifact_selects_profile(artifact: M8F7DurableArtifact) -> bool {
    M8_F7_DURABLE_PROFILE_DESCRIPTORS.iter().any(|descriptor| {
        descriptor.profile == M8F7DurableProfileVersion::LegacyV1 && descriptor.artifact == artifact
    })
}

/// Census of the retained M.8/F7 durable profiles before any recovery write.
///
/// The frozen rule is `V1 xor V2` **per session over the profile chain**
/// gate -> issuance -> commit -> issued -> consumed -> binding -> pre-signature.
/// Those seven artifacts are the only ones that exist in both profiles, so only
/// they fold into the per-session mask; an artifact declared V2-only is an
/// encoding shared by both lanes and never decides a profile. Everything else
/// stays exact: magic must match its descriptor, the descriptor must match the
/// directory the file was found in, and one `(session, profile, artifact)` may
/// never hold a final and a staging copy at the same time.
fn census_m8_f7_durable_profiles(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
) -> Result<M8F7DurableCensus, SessionStoreError> {
    let mut session_profiles = BTreeMap::<[u8; 32], u8>::new();
    let mut publications =
        BTreeMap::<([u8; 32], M8F7DurableProfileVersion, M8F7DurableArtifact), u8>::new();
    let mut v2_finals = BTreeMap::<[u8; 32], BTreeSet<M8F7DurableArtifact>>::new();

    for (directory_identity, directory) in directories {
        let mut relevant_names = Vec::new();
        directory.scan_lexicographic(|name, node| {
            if parse_m8_f7_durable_profile_name(name).is_some() {
                if node.node_type != ExpectedNodeType::RegularFile {
                    return Err(LinuxCapabilityError::InvalidObject);
                }
                relevant_names.push(name.to_owned());
            }
            Ok(())
        })?;

        for name in relevant_names {
            let (session_id, descriptor, staging) =
                parse_m8_f7_durable_profile_name(&name).ok_or(SessionStoreError::Quarantined)?;
            let component = ValidatedComponent::registered(&name)?;
            let magic: [u8; 8] = directory.read_exact_file_prefix(&component)?;
            if magic != *descriptor.magic || descriptor.directory != *directory_identity {
                return Err(SessionStoreError::Quarantined);
            }
            if descriptor.profile == M8F7DurableProfileVersion::V2 && !staging {
                v2_finals
                    .entry(session_id)
                    .or_default()
                    .insert(descriptor.artifact);
            }

            if m8_f7_artifact_selects_profile(descriptor.artifact) {
                let profile_mask = match descriptor.profile {
                    M8F7DurableProfileVersion::LegacyV1 => 0b01,
                    M8F7DurableProfileVersion::V2 => 0b10,
                };
                let observed_profiles = session_profiles.entry(session_id).or_insert(0);
                *observed_profiles |= profile_mask;
                if *observed_profiles == 0b11 {
                    return Err(SessionStoreError::Quarantined);
                }
            }

            let publication_mask = if staging { 0b10 } else { 0b01 };
            let observed_publication = publications
                .entry((session_id, descriptor.profile, descriptor.artifact))
                .or_insert(0);
            *observed_publication |= publication_mask;
            if *observed_publication == 0b11 {
                return Err(SessionStoreError::Quarantined);
            }
        }
    }
    Ok(M8F7DurableCensus { v2_finals })
}

fn m8_f7_directory<'directory>(
    directories: &[(M8F7DurableDirectory, &'directory RetainedDirectory); 6],
    identity: M8F7DurableDirectory,
) -> Result<&'directory RetainedDirectory, SessionStoreError> {
    directories
        .iter()
        .find_map(|(candidate, directory)| (*candidate == identity).then_some(*directory))
        .ok_or(SessionStoreError::Quarantined)
}

fn m8_f7_v2_descriptor(
    artifact: M8F7DurableArtifact,
) -> Result<M8F7DurableProfileDescriptor, SessionStoreError> {
    M8_F7_DURABLE_PROFILE_DESCRIPTORS
        .iter()
        .copied()
        .find(|descriptor| {
            descriptor.profile == M8F7DurableProfileVersion::V2 && descriptor.artifact == artifact
        })
        .ok_or(SessionStoreError::Quarantined)
}

fn required_m8_f7_v2_preflight_read<T>(
    result: Result<T, LinuxCapabilityError>,
) -> Result<T, SessionStoreError> {
    match result {
        Ok(value) => Ok(value),
        Err(LinuxCapabilityError::NotFound) => Err(SessionStoreError::Quarantined),
        Err(error) => Err(error.into()),
    }
}

/// Folds the absence of a record the V2 claim issuance requires onto durable
/// inconsistency rather than onto absence.
///
/// The readers that start from `ClaimSigningIssued` address several records at
/// once, and their absences do not mean the same thing. A missing issuance is
/// a session this Store never authorized, which is absence. A missing gate,
/// commit, signing binding or round binding *while the issuance is there* is
/// a durable graph that contradicts itself, and reporting it as absence would
/// tell the caller to go create what is in fact broken.
///
/// This is the reader-side twin of [`required_m8_f7_v2_preflight_read`], which
/// draws exactly the same line for the ancestry the Store walks before it
/// opens.
///
/// The partial graph is, as far as this crate can establish, not reachable
/// through a legitimate restart: `preflight_m8_f7_v2_finals` applies a strict
/// prefix rule over `order`, so a session holding `ClaimSigningIssued` without
/// `FundingGate` or `FundingCommit` quarantines the whole Store at open and no
/// `&self` ever exists to call these readers. That argument covers the durable
/// tree the Store opened; it does not cover a tree mutated out of band
/// afterwards, and the fold below is what covers that.
fn required_m8_f7_v2_companion<T>(
    loaded: Result<T, SessionStoreError>,
) -> Result<T, SessionStoreError> {
    match loaded {
        Err(SessionStoreError::SessionNotFound) => Err(SessionStoreError::Quarantined),
        other => other,
    }
}

fn m8_f7_v2_final_bytes(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    session_id: [u8; 32],
    artifact: M8F7DurableArtifact,
    maximum_length: usize,
) -> Result<Vec<u8>, SessionStoreError> {
    let descriptor = m8_f7_v2_descriptor(artifact)?;
    let directory = m8_f7_directory(directories, descriptor.directory)?;
    let name = format!("{}{}", hex_lower(&session_id), descriptor.suffix);
    let bytes = required_m8_f7_v2_preflight_read(
        directory.read_bounded_file(&ValidatedComponent::registered(&name)?, maximum_length),
    )?;
    if bytes.get(..8) != Some(descriptor.magic.as_slice()) {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(bytes)
}

/// Reads one session revision, telling absence apart from corruption.
///
/// [`preflight_session_revision`] folds a missing record into `Quarantined`,
/// which is right for every ancestry that must already be complete before the
/// Store opens. The two FinalClaim markers need the distinction, and only
/// them: each embeds the exact bytes of the successor it produced, so a marker
/// whose successor is not yet durable is a persist-before-successor cut whose
/// repair is fully determined — not an unsound graph.
///
/// This is the same distinction the transport side already draws in
/// [`ContractsSessionStoreV1::transport_successor_revision_is_pending`], whose
/// doc-comment states the reason: demanding that a pending successor already
/// be durable is the exact opposite of the question being asked. Here the case
/// is stronger, because the durable record carries the missing bytes verbatim
/// instead of naming them.
fn optional_preflight_session_revision(
    records: &RetainedDirectory,
    session_id: [u8; 32],
    revision: u64,
) -> Result<Option<SessionRecordV1>, SessionStoreError> {
    match records.read_bounded_file(
        &ValidatedComponent::registered(&session_record_name(session_id, revision))?,
        SESSION_RECORD_MAX_LEN,
    ) {
        Ok(bytes) => {
            let record = SessionRecordV1::from_bytes(&bytes).map_err(SessionStoreError::from)?;
            if record.session_id() != session_id || record.revision() != revision {
                return Err(SessionStoreError::Quarantined);
            }
            Ok(Some(record))
        }
        Err(LinuxCapabilityError::NotFound) => Ok(None),
        Err(error) => Err(error.into()),
    }
}

fn preflight_session_revision(
    records: &RetainedDirectory,
    session_id: [u8; 32],
    revision: u64,
) -> Result<SessionRecordV1, SessionStoreError> {
    let bytes = required_m8_f7_v2_preflight_read(records.read_bounded_file(
        &ValidatedComponent::registered(&session_record_name(session_id, revision))?,
        SESSION_RECORD_MAX_LEN,
    ))?;
    let record = SessionRecordV1::from_bytes(&bytes).map_err(SessionStoreError::from)?;
    if record.session_id() != session_id || record.revision() != revision {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(record)
}

fn require_operational_m8_backup_provenance_ancestry(
    record: &OperationalM8BackupProvenanceRecordV2,
    roster: &TransportRosterRecordV1,
    early: &EarlyTransportAuthorityRecordV1,
    bp: &BpTransportAuthorityRecordV1,
) -> Result<(), SessionStoreError> {
    let participant_ids = [
        record.participants[0].participant_id,
        record.participants[1].participant_id,
    ];
    if roster.session_id != record.session_id
        || roster.chain_id != record.chain_id
        || copy_array(&roster.bytes[212..244])? != record.transport_roster_record_digest
        || early.session_id != record.session_id
        || early.chain_id != record.chain_id
        || early.terms_hash != record.terms_hash
        || early.recovery_binding_hash != record.recovery_binding_hash
        || early.digest != record.early_authority_record_digest
        || bp.session_id != record.session_id
        || bp.chain_id != record.chain_id
        || bp.terms_hash != record.terms_hash
        || bp.early_authority_digest != early.digest
        || bp.digest != record.bp_authority_record_digest
        || bp.statement.chain_id() != record.chain_id
        || bp.statement.session_id() != record.session_id
        || bp.statement.recovery_binding_hash() != &record.recovery_binding_hash
        || blake2b_256(bp.recovery_capsule.as_bytes()).as_bytes() != &record.recovery_binding_hash
        || roster.participants.len() != record.participants.len()
        || bp.statement.participant_ids() != participant_ids.as_slice()
        || bp.statement.commitment_shares().len() != participant_ids.len()
    {
        return Err(SessionStoreError::Quarantined);
    }
    for participant in &record.participants {
        let transport = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == participant.participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let proven = early
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == participant.participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let bp_index = bp
            .statement
            .participant_ids()
            .iter()
            .position(|candidate| candidate == &participant.participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        if transport.direction != participant.direction
            || proven.direction != participant.direction
            || proven.participant_index != participant.participant_index
            || proven.binding_digest != participant.binding_digest
            || proven.share_point.to_compressed_bytes() != participant.committed_share_point
            || participant.committed_share_point != participant.recovered_share_point
            || bp
                .statement
                .commitment_shares()
                .get(bp_index)
                .ok_or(SessionStoreError::Quarantined)?
                .to_compressed_bytes()
                != participant.committed_share_point
        {
            return Err(SessionStoreError::Quarantined);
        }
    }
    DomCollaborativeRangeProofV1::new(&bp.statement, bp.recovery_capsule.as_bytes().to_vec())
        .map_err(|_| SessionStoreError::Quarantined)?;
    Ok(())
}

/// Authenticates the retained `DOMSM8B2` backup provenance of one session.
///
/// The authoritative boundary is the gate's: `preflight_m8_f7_v2_gate_ancestry`
/// calls this unconditionally and then binds the record digest to
/// `gate.ready_binding.backup_receipt_hash()`, so a session that carries a V2
/// funding gate must carry the provenance object the gate committed to. The
/// conditional call in `preflight_m8_f7_v2_finals` covers only sessions with a
/// backup provenance final and no gate; it can never relax the gate's binding,
/// and a gate whose receipt digest names no retained record stays refused.
fn preflight_m8_f7_v2_backup_provenance_ancestry(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    session_id: [u8; 32],
) -> Result<OperationalM8BackupProvenanceRecordV2, SessionStoreError> {
    let rosters = m8_f7_directory(directories, M8F7DurableDirectory::Rosters)?;
    let read_roster = |name: String, maximum_length: usize| {
        required_m8_f7_v2_preflight_read(
            rosters.read_bounded_file(&ValidatedComponent::registered(&name)?, maximum_length),
        )
    };
    let roster = TransportRosterRecordV1::from_bytes(&read_roster(
        roster_name(session_id),
        TRANSPORT_ROSTER_LEN,
    )?)?;
    let early = EarlyTransportAuthorityRecordV1::from_bytes(&read_roster(
        early_transport_authority_name(session_id),
        EARLY_TRANSPORT_AUTHORITY_LEN,
    )?)?;
    let bp = BpTransportAuthorityRecordV1::from_bytes(&read_roster(
        bp_transport_authority_name(session_id),
        BP_TRANSPORT_AUTHORITY_MAX_LEN,
    )?)?;
    let record = OperationalM8BackupProvenanceRecordV2::from_bytes(&m8_f7_v2_final_bytes(
        directories,
        session_id,
        M8F7DurableArtifact::BackupProvenance,
        M8_BACKUP_PROVENANCE_V2_RECORD_LEN,
    )?)?;
    require_operational_m8_backup_provenance_ancestry(&record, &roster, &early, &bp)?;
    Ok(record)
}

fn preflight_m8_f7_v2_final_refund_ancestry(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    session_id: [u8; 32],
) -> Result<OperationalFinalRefundRecordV2, SessionStoreError> {
    let records = m8_f7_directory(directories, M8F7DurableDirectory::Records)?;
    let rosters = m8_f7_directory(directories, M8F7DurableDirectory::Rosters)?;
    let messages = m8_f7_directory(directories, M8F7DurableDirectory::Messages)?;
    let read_roster = |name: String, maximum_length: usize| {
        required_m8_f7_v2_preflight_read(
            rosters.read_bounded_file(&ValidatedComponent::registered(&name)?, maximum_length),
        )
    };
    let roster = TransportRosterRecordV1::from_bytes(&read_roster(
        roster_name(session_id),
        TRANSPORT_ROSTER_LEN,
    )?)?;
    let identities = TransportIdentityBindingRecordV1::from_bytes(&read_roster(
        transport_identity_binding_name(session_id),
        TRANSPORT_IDENTITY_BINDING_LEN,
    )?)?;
    require_transport_identity_binding(&roster, &identities)?;
    let early = EarlyTransportAuthorityRecordV1::from_bytes(&read_roster(
        early_transport_authority_name(session_id),
        EARLY_TRANSPORT_AUTHORITY_LEN,
    )?)?;
    let bp = BpTransportAuthorityRecordV1::from_bytes(&read_roster(
        bp_transport_authority_name(session_id),
        BP_TRANSPORT_AUTHORITY_MAX_LEN,
    )?)?;
    let template = TemplateTransportAuthorityRecordV1::from_bytes(&read_roster(
        template_transport_authority_name(session_id),
        TEMPLATE_TRANSPORT_AUTHORITY_LEN,
    )?)?;
    let signing = SigningSessionBindingRecordV1::from_bytes(&read_roster(
        signing_binding_name(session_id, PurposeV1::Refund),
        SIGNING_BINDING_MAX_LEN,
    )?)?;
    let final_refund = OperationalFinalRefundRecordV2::from_bytes(&m8_f7_v2_final_bytes(
        directories,
        session_id,
        M8F7DurableArtifact::FinalRefund,
        OPERATIONAL_FINAL_REFUND_V2_RECORD_MAX_LEN,
    )?)?;
    let initial = preflight_session_revision(records, session_id, 0)?;
    let bp_round_start = preflight_session_revision(records, session_id, bp.round_start_revision)?;
    let template_round_start =
        preflight_session_revision(records, session_id, template.round_start_revision)?;
    let signing_round_start =
        preflight_session_revision(records, session_id, final_refund.round_start_revision)?;
    let terminal = preflight_session_revision(records, session_id, final_refund.terminal_revision)?;
    let signing_digest_offset = signing
        .bytes
        .len()
        .checked_sub(DIGEST_LEN)
        .ok_or(SessionStoreError::Quarantined)?;
    let transaction_bytes = signing
        .bytes
        .get(SIGNING_BINDING_PREFIX_LEN..signing_digest_offset)
        .ok_or(SessionStoreError::Quarantined)?;
    let transaction = <Transaction as DomDeserialize>::from_bytes(transaction_bytes)
        .map_err(|_| SessionStoreError::Quarantined)?;
    let canonical_transaction = transaction
        .to_bytes()
        .map_err(|_| SessionStoreError::Quarantined)?;
    let (_, signing_template_hash) =
        canonical_template_v1(&transaction).map_err(|_| SessionStoreError::Quarantined)?;
    let failed_static_check = [
        (
            "session",
            roster.session_id != session_id
                || identities.session_id != session_id
                || early.session_id != session_id
                || bp.session_id != session_id
                || template.session_id != session_id
                || signing.session_id != session_id
                || final_refund.session_id != session_id
                || signing.purpose != PurposeV1::Refund,
        ),
        (
            "chain-and-terms",
            roster.chain_id != final_refund.chain_id
                || identities.chain_id != final_refund.chain_id
                || early.chain_id != final_refund.chain_id
                || bp.chain_id != final_refund.chain_id
                || template.chain_id != final_refund.chain_id
                || early.terms_hash != final_refund.terms_hash
                || bp.terms_hash != final_refund.terms_hash
                || template.terms_hash != final_refund.terms_hash
                || signing.bytes[80..112] != final_refund.terms_hash,
        ),
        (
            "durable-digests",
            copy_array(&roster.bytes[212..244])? != final_refund.transport_roster_record_digest
                || copy_array(&identities.bytes[338..370])?
                    != final_refund.transport_identity_record_digest
                || early.digest != final_refund.early_authority_record_digest
                || bp.early_authority_digest != early.digest
                || bp.digest != final_refund.bp_authority_record_digest
                || template.bp_authority_digest != bp.digest
                || template.digest != final_refund.template_authority_record_digest
                || copy_array(&signing.bytes[signing_digest_offset..])?
                    != final_refund.signing_binding_record_digest
                || operational_signing_roster_digest_v2(&signing)?
                    != final_refund.signing_roster_digest,
        ),
        (
            "authority-revisions",
            initial.phase() != SessionPhaseV1::Created
                || initial.terms_hash() != final_refund.terms_hash
                || early.initial_record_digest != *initial.digest()
                || early.initial_transcript_hash != initial.transcript_hash()
                || bp.round_start_record_digest != *bp_round_start.digest()
                || bp.round_start_transcript_hash != bp_round_start.transcript_hash()
                || template.round_start_record_digest != *template_round_start.digest()
                || template.round_start_transcript_hash != template_round_start.transcript_hash()
                || !signing_round_start_phase_is_valid(
                    signing_round_start.phase(),
                    PurposeV1::Refund,
                    SessionPhaseV1::RefundSigning,
                )
                || final_refund.round_start_record_digest != *signing_round_start.digest()
                || final_refund.round_start_transcript_hash
                    != signing_round_start.transcript_hash()
                || terminal.phase() != SessionPhaseV1::RefundSigning
                || final_refund.terminal_record_digest != *terminal.digest()
                || final_refund.terminal_transcript_hash != terminal.transcript_hash(),
        ),
        (
            "signing-layout",
            signing.bytes[112..120] != final_refund.round_start_revision.to_le_bytes()
                || signing.bytes[120..152] != final_refund.round_start_record_digest
                || signing.bytes[184..216] != final_refund.round_start_transcript_hash
                || u32::from_le_bytes(copy_array(&signing.bytes[232..236])?) != 0
                || signing.bytes[240..272] != final_refund.template_hash
                || signing.bytes[11] != 0
                || signing.bytes[272..305] != [0; 33]
                || signing.bytes[312..472] != template.template_commit_payload,
        ),
        (
            "template-and-bp",
            template_hash_for_purpose(&template.template_commit_payload, PurposeV1::Refund)
                != final_refund.template_hash
                || template.template_commit_payload[96..128] != bp.statement.statement_hash()
                || template.template_commit_payload[128..160]
                    != *bp.statement.recovery_binding_hash()
                || bp.statement.participant_ids().len() != 2
                || bp.statement.commitment_shares().len() != 2,
        ),
        (
            "unsigned-transaction",
            canonical_transaction != transaction_bytes
                || signing_template_hash != final_refund.template_hash
                || transaction.inputs.len() != 1
                || transaction.outputs.is_empty()
                || transaction.kernels.len() != 1
                || transaction.kernels[0].features != KERNEL_FEAT_HEIGHT_LOCKED
                || transaction.kernels[0].lock_height != final_refund.refund_unlock_height
                || transaction.kernels[0].excess_signature != [0; 65]
                || transaction.inputs[0].commitment.as_bytes()
                    != &bp.statement.aggregate_commitment().to_compressed_bytes(),
        ),
    ]
    .into_iter()
    .find(|(_, failed)| *failed);
    if failed_static_check.is_some() {
        return Err(SessionStoreError::Quarantined);
    }

    let mut semantic_participants = Vec::with_capacity(2);
    for index in 0..2 {
        let offset = 472 + index * 99;
        let participant_id: [u8; 32] = copy_array(&signing.bytes[offset..offset + 32])?;
        let signing_identity =
            PublicKey::from_compressed_bytes(&signing.bytes[offset + 32..offset + 65])
                .map_err(|_| SessionStoreError::Quarantined)?;
        let signing_share =
            PublicKey::from_compressed_bytes(&signing.bytes[offset + 65..offset + 98])
                .map_err(|_| SessionStoreError::Quarantined)?;
        let direction = DirectionV1::try_from(signing.bytes[offset + 98])
            .map_err(|_| SessionStoreError::Quarantined)?;
        let transport = roster
            .participants
            .iter()
            .find(|participant| participant.participant_id == participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let identity = identities
            .references
            .iter()
            .find(|reference| reference.participant_id == participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let proven = early
            .participants
            .iter()
            .find(|participant| participant.participant_id == participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let bp_index = bp
            .statement
            .participant_ids()
            .iter()
            .position(|candidate| candidate == &participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        let bp_share = bp
            .statement
            .commitment_shares()
            .get(bp_index)
            .ok_or(SessionStoreError::Quarantined)?;
        if signing_identity != transport.identity_key
            || signing_identity != identity.schnorr_public_key
            || signing_share != proven.share_point
            || signing_share != *bp_share
            || direction != transport.direction
            || direction != proven.direction
        {
            return Err(SessionStoreError::Quarantined);
        }
        semantic_participants.push(SigningSemanticParticipantV1 {
            participant_id,
            signing_public_key: signing_share,
            direction,
        });
    }
    let semantic_participants: [SigningSemanticParticipantV1; 2] = semantic_participants
        .try_into()
        .map_err(|_| SessionStoreError::Quarantined)?;
    let sender_sequence_bases = [
        u64::from_le_bytes(copy_array(&signing.bytes[216..224])?),
        u64::from_le_bytes(copy_array(&signing.bytes[224..232])?),
    ];
    let canonical_sender_sequence = u64::from_le_bytes(copy_array(&signing.bytes[216..224])?)
        .checked_add(3)
        .ok_or(SessionStoreError::Quarantined)?;
    if final_refund.canonical_sender_id != signing.bytes[472..504]
        || final_refund.canonical_sender_sequence != canonical_sender_sequence
    {
        return Err(SessionStoreError::Quarantined);
    }

    let replay_binding = AuthenticatedSigningReplayBindingV1 {
        participants: semantic_participants,
        transaction_template: transaction,
        template_hash: final_refund.template_hash,
        kernel_index: 0,
        adaptor_point: None,
        round_start_revision: final_refund.round_start_revision,
        round_start_record_digest: final_refund.round_start_record_digest,
        round_start_transcript_hash: final_refund.round_start_transcript_hash,
        sender_sequence_bases,
        template_commit_payload: copy_array(&signing.bytes[312..472])?,
    };
    let mut predecessor = signing_round_start;
    let mut accepted_messages = Vec::with_capacity(6);
    let mut reveal_transcript_hash = None;
    for position in 0..6 {
        let participant_index = position % 2;
        let stage_index = position / 2;
        let participant = replay_binding
            .participants
            .get(participant_index)
            .ok_or(SessionStoreError::Quarantined)?;
        let sequence = sender_sequence_bases[participant_index]
            .checked_add(u64::try_from(stage_index).map_err(|_| SessionStoreError::Quarantined)?)
            .ok_or(SessionStoreError::Quarantined)?;
        let name = transport_message_name(session_id, participant.participant_id, sequence, false);
        let record = TransportMessageRecordV1::from_bytes(&required_m8_f7_v2_preflight_read(
            messages.read_bounded_file(
                &ValidatedComponent::registered(&name)?,
                TRANSPORT_MESSAGE_MAX_LEN,
            ),
        )?)?;
        let envelope = ParsedTransportEnvelopeV1::parse(&record.signed_bytes)?;
        let transport = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == participant.participant_id)
            .ok_or(SessionStoreError::Quarantined)?;
        envelope
            .verify(&transport.identity_key)
            .map_err(|_| SessionStoreError::Quarantined)?;
        let expected_message_type = 0x0c_u8
            .checked_add(u8::try_from(stage_index).map_err(|_| SessionStoreError::Quarantined)?)
            .ok_or(SessionStoreError::Quarantined)?;
        let expected_revision = final_refund
            .round_start_revision
            .checked_add(u64::try_from(position + 1).map_err(|_| SessionStoreError::Quarantined)?)
            .ok_or(SessionStoreError::Quarantined)?;
        let durable_successor = preflight_session_revision(records, session_id, expected_revision)?;
        if record.equivocation
            || record.session_id != session_id
            || record.sender_id != participant.participant_id
            || record.sequence != sequence
            || record.message_type != expected_message_type
            || record.direction != participant.direction
            || envelope.chain_id != final_refund.chain_id
            || envelope.session_id != session_id
            || envelope.sender_id != participant.participant_id
            || envelope.sequence != sequence
            || envelope.message_type != expected_message_type
            || signing_payload_purpose(
                expected_message_type,
                envelope
                    .payload(&record.signed_bytes)
                    .map_err(|_| SessionStoreError::Quarantined)?,
            )
            .map_err(|_| SessionStoreError::Quarantined)?
                != PurposeV1::Refund
            || record.successor.phase() != SessionPhaseV1::RefundSigning
            || record.successor.revision() != expected_revision
            || record.successor.as_bytes() != durable_successor.as_bytes()
            || require_transport_successor(
                &predecessor,
                &envelope,
                participant.direction,
                &record.successor,
            )
            .is_err()
        {
            return Err(SessionStoreError::Quarantined);
        }
        predecessor = record.successor;
        if position == 3 {
            reveal_transcript_hash = Some(predecessor.transcript_hash());
        }
        accepted_messages.push(record.signed_bytes);
    }
    if predecessor.as_bytes() != terminal.as_bytes() {
        return Err(SessionStoreError::Quarantined);
    }
    let round = OperationalSigningRoundAuditV1 {
        round_start_revision: final_refund.round_start_revision,
        round_start_record_digest: final_refund.round_start_record_digest,
        round_start_transcript_hash: final_refund.round_start_transcript_hash,
        reveal_transcript_hash,
        terminal_revision: final_refund.terminal_revision,
        terminal_record_digest: final_refund.terminal_record_digest,
        terminal_transcript_hash: final_refund.terminal_transcript_hash,
        sender_sequence_bases,
        template_commit_payload: replay_binding.template_commit_payload,
        accepted_messages,
    };
    let final_signature = validate_operational_signing_round_semantics(
        &final_refund.chain_id,
        session_id,
        PurposeV1::Refund,
        &replay_binding,
        &round,
    )
    .map_err(|_| SessionStoreError::Quarantined)?
    .ok_or(SessionStoreError::Quarantined)?;
    let mut expected_transaction = replay_binding.transaction_template.clone();
    expected_transaction.kernels[0].excess_signature = final_signature.to_bytes();
    let expected_transaction_bytes = expected_transaction
        .to_bytes()
        .map_err(|_| SessionStoreError::Quarantined)?;
    if expected_transaction_bytes != final_refund.exact_transaction_bytes {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(final_refund)
}

fn preflight_m8_f7_v2_gate_ancestry(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    session_id: [u8; 32],
    gate: &OperationalM8FundingGateRecordV2,
) -> Result<SessionRecordV1, SessionStoreError> {
    let records = m8_f7_directory(directories, M8F7DurableDirectory::Records)?;
    let rosters = m8_f7_directory(directories, M8F7DurableDirectory::Rosters)?;
    let messages = m8_f7_directory(directories, M8F7DurableDirectory::Messages)?;
    let read_roster = |name: String, maximum_length: usize| {
        required_m8_f7_v2_preflight_read(
            rosters.read_bounded_file(&ValidatedComponent::registered(&name)?, maximum_length),
        )
    };
    let roster = TransportRosterRecordV1::from_bytes(&read_roster(
        roster_name(session_id),
        TRANSPORT_ROSTER_LEN,
    )?)?;
    let identities = TransportIdentityBindingRecordV1::from_bytes(&read_roster(
        transport_identity_binding_name(session_id),
        TRANSPORT_IDENTITY_BINDING_LEN,
    )?)?;
    require_transport_identity_binding(&roster, &identities)?;
    let early = EarlyTransportAuthorityRecordV1::from_bytes(&read_roster(
        early_transport_authority_name(session_id),
        EARLY_TRANSPORT_AUTHORITY_LEN,
    )?)?;
    let bp = BpTransportAuthorityRecordV1::from_bytes(&read_roster(
        bp_transport_authority_name(session_id),
        BP_TRANSPORT_AUTHORITY_MAX_LEN,
    )?)?;
    let template = TemplateTransportAuthorityRecordV1::from_bytes(&read_roster(
        template_transport_authority_name(session_id),
        TEMPLATE_TRANSPORT_AUTHORITY_LEN,
    )?)?;
    let initial = preflight_session_revision(records, session_id, 0)?;
    let bp_round_start = preflight_session_revision(records, session_id, bp.round_start_revision)?;
    let template_round_start =
        preflight_session_revision(records, session_id, template.round_start_revision)?;
    let bound = preflight_session_revision(records, session_id, gate.bound_session_revision)?;
    let backup = preflight_m8_f7_v2_backup_provenance_ancestry(directories, session_id)?;
    let final_refund = preflight_m8_f7_v2_final_refund_ancestry(directories, session_id)?;
    let final_refund_name = transport_message_name(
        session_id,
        final_refund.canonical_sender_id,
        final_refund.canonical_sender_sequence,
        false,
    );
    let final_refund_transport = TransportMessageRecordV1::from_bytes(
        &required_m8_f7_v2_preflight_read(messages.read_bounded_file(
            &ValidatedComponent::registered(&final_refund_name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        ))?,
    )?;
    let final_refund_envelope =
        ParsedTransportEnvelopeV1::parse(&final_refund_transport.signed_bytes)?;
    let final_refund_sender = roster
        .participants
        .iter()
        .find(|participant| participant.participant_id == final_refund.canonical_sender_id)
        .ok_or(SessionStoreError::Quarantined)?;
    final_refund_envelope
        .verify(&final_refund_sender.identity_key)
        .map_err(|_| SessionStoreError::Quarantined)?;
    let final_refund_terminal =
        preflight_session_revision(records, session_id, final_refund.terminal_revision)?;
    let final_refund_transport_digest = copy_array(
        &final_refund_transport.bytes[final_refund_transport.bytes.len() - DIGEST_LEN..],
    )?;

    if roster.session_id != session_id
        || identities.session_id != session_id
        || early.session_id != session_id
        || bp.session_id != session_id
        || template.session_id != session_id
        || gate.role_binding.session_id().0 != session_id
        || gate.ready_binding.session_id().0 != session_id
        || roster.chain_id != gate.role_binding.dom_chain_id().0
        || identities.chain_id != roster.chain_id
        || early.chain_id != roster.chain_id
        || bp.chain_id != roster.chain_id
        || template.chain_id != roster.chain_id
        || copy_array(&roster.bytes[212..244])? != gate.transport_roster_record_digest
        || copy_array(&identities.bytes[338..370])? != gate.transport_identity_record_digest
        || early.digest != gate.early_authority_record_digest
        || bp.digest != gate.bp_authority_record_digest
        || template.digest != gate.template_authority_record_digest
        || gate.ready_binding.backup_receipt_hash() != backup.digest
        || gate.final_refund_record_digest != final_refund.digest
        || gate.final_refund_transport_record_digest != final_refund_transport_digest
        || backup.chain_id != roster.chain_id
        || backup.session_id != session_id
        || backup.terms_hash != early.terms_hash
        || backup.recovery_binding_hash != early.recovery_binding_hash
        || final_refund.chain_id != roster.chain_id
        || final_refund.session_id != session_id
        || final_refund.terms_hash != early.terms_hash
        || final_refund.template_hash != gate.ready_binding.refund_template_hash()
        || final_refund.refund_unlock_height != gate.ready_binding.refund_unlock_height()
        || final_refund.refund_tx_hash != gate.ready_binding.refund_tx_hash()
        || final_refund.exact_transaction_bytes != gate.refund_bytes
        || final_refund_transport.equivocation
        || final_refund_transport.session_id != session_id
        || final_refund_transport.sender_id != final_refund.canonical_sender_id
        || final_refund_transport.sequence != final_refund.canonical_sender_sequence
        || final_refund_transport.message_type != 0x10
        || final_refund_transport.direction != final_refund_sender.direction
        || final_refund_envelope.chain_id != roster.chain_id
        || final_refund_envelope.session_id != session_id
        || final_refund_envelope.sender_id != final_refund.canonical_sender_id
        || final_refund_envelope.sequence != final_refund.canonical_sender_sequence
        || final_refund_envelope.previous_transcript_hash != final_refund.terminal_transcript_hash
        || final_refund_envelope.message_type != 0x10
        || final_refund_envelope
            .payload(&final_refund_transport.signed_bytes)
            .map_err(|_| SessionStoreError::Quarantined)?
            != final_refund.exact_transaction_bytes
        || final_refund_transport.successor.as_bytes() != bound.as_bytes()
        || require_transport_successor(
            &final_refund_terminal,
            &final_refund_envelope,
            final_refund_sender.direction,
            &final_refund_transport.successor,
        )
        .is_err()
    {
        return Err(SessionStoreError::Quarantined);
    }
    for role_entry in gate.role_binding.roster_entries() {
        let transport = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == role_entry.participant_id())
            .ok_or(SessionStoreError::Quarantined)?;
        let identity = identities
            .references
            .iter()
            .find(|candidate| candidate.participant_id == role_entry.participant_id())
            .ok_or(SessionStoreError::Quarantined)?;
        let proven = early
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == role_entry.participant_id())
            .ok_or(SessionStoreError::Quarantined)?;
        if transport.identity_key.to_compressed_bytes() != role_entry.identity_public_key_sec1()
            || identity.schnorr_public_key.to_compressed_bytes()
                != role_entry.identity_public_key_sec1()
            || transport.direction != role_entry.direction()
            || proven.direction != role_entry.direction()
            || proven.share_point.to_compressed_bytes() != role_entry.signing_public_key_sec1()
        {
            return Err(SessionStoreError::Quarantined);
        }
    }
    if initial.revision() != 0
        || initial.phase() != SessionPhaseV1::Created
        || initial.terms_hash() != early.terms_hash
        || initial.transcript_hash() != early.initial_transcript_hash
        || initial.digest() != &early.initial_record_digest
        || early.participants.iter().any(|participant| {
            match roster
                .participants
                .iter()
                .find(|candidate| candidate.participant_id == participant.participant_id)
            {
                Some(candidate) => candidate.direction != participant.direction,
                None => true,
            }
        })
        || bp.early_authority_digest != early.digest
        || bp.round_start_revision != bp_round_start.revision()
        || bp.round_start_record_digest != *bp_round_start.digest()
        || bp.round_start_transcript_hash != bp_round_start.transcript_hash()
        || bp_round_start.phase() != SessionPhaseV1::SharesRevealed
        || bp_round_start.terms_hash() != bp.terms_hash
        || bp.statement.chain_id() != roster.chain_id
        || bp.statement.session_id() != session_id
        || bp.statement.participant_ids()
            != [
                early.participants[0].participant_id,
                early.participants[1].participant_id,
            ]
        || bp.statement.commitment_shares().len() != 2
        || bp.statement.commitment_shares()[0] != early.participants[0].share_point
        || bp.statement.commitment_shares()[1] != early.participants[1].share_point
        || bp.statement.recovery_binding_hash() != &early.recovery_binding_hash
        || blake2b_256(bp.recovery_capsule.as_bytes()).as_bytes()
            != bp.statement.recovery_binding_hash()
        || template.bp_authority_digest != bp.digest
        || template.round_start_revision != template_round_start.revision()
        || template.round_start_record_digest != *template_round_start.digest()
        || template.round_start_transcript_hash != template_round_start.transcript_hash()
        || template_round_start.phase() != SessionPhaseV1::OutputFinalized
        || template_round_start.terms_hash() != template.terms_hash
        || template.template_commit_payload[96..128] != bp.statement.statement_hash()
        || template.template_commit_payload[128..160] != *bp.statement.recovery_binding_hash()
    {
        return Err(SessionStoreError::Quarantined);
    }
    DomCollaborativeRangeProofV1::new(&bp.statement, bp.recovery_capsule.as_bytes().to_vec())
        .map_err(|_| SessionStoreError::Quarantined)?;
    let role_terms_hash = gate
        .role_binding
        .terms_hash()
        .map_err(|_| SessionStoreError::Quarantined)?;
    if role_terms_hash != early.terms_hash
        || role_terms_hash != bp.terms_hash
        || role_terms_hash != template.terms_hash
        || gate.ready_binding.terms_hash() != role_terms_hash
        || gate.ready_binding.roster_digest() != gate.role_binding.roster_digest()
        || gate.ready_binding.funding_template_hash()
            != template_hash_for_purpose(&template.template_commit_payload, PurposeV1::Funding)
        || gate.ready_binding.claim_template_hash()
            != template_hash_for_purpose(&template.template_commit_payload, PurposeV1::ClaimAdaptor)
        || gate.ready_binding.refund_template_hash()
            != template_hash_for_purpose(&template.template_commit_payload, PurposeV1::Refund)
        || gate.ready_binding.bp_statement_hash() != bp.statement.statement_hash()
        || gate.ready_binding.recovery_binding_hash() != *bp.statement.recovery_binding_hash()
        || gate.bp_statement_bytes != bp.statement.to_bytes()
        || bound.phase() != SessionPhaseV1::RefundSigned
        || bound.irreversible().funding_authorized
        || bound.terms_hash() != role_terms_hash
        || bound.digest() != &gate.bound_session_record_digest
        || bound.chain().tip_id != gate.validation_tip_hash
        || bound.chain().tip_height != gate.validation_tip_height
        || operational_abort_chain_projection_digest(bound.chain()) != gate.chain_projection_digest
    {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(bound)
}

fn require_post_anchor_role_v2(
    authorization: &PostAnchorClaimAuthorizationRecordV2,
    gate: &OperationalM8FundingGateRecordV2,
) -> Result<(), SessionStoreError> {
    let role = &gate.role_binding;
    let ready = &gate.ready_binding;
    if authorization.session_id != role.session_id().0
        || authorization.settlement_id != role.settlement_id().0
        || authorization.terms_hash
            != role
                .terms_hash()
                .map_err(|_| SessionStoreError::Quarantined)?
        || authorization.m8_policy_digest != ready.m8_policy_digest()
        || authorization.chain_id != role.dom_chain_id().0
        || authorization.dom_shared_output_commitment != role.shared_output_commitment()
        || authorization.claim_template_hash != role.claim_template_hash()
        || authorization.adaptor_point.to_compressed_bytes() != role.adaptor_point_sec1()
        || authorization.final_claim_role_binding_digest != role.digest()
        || authorization.ready_binding_digest != ready.digest()
        || authorization.reveal_mode != role.reveal_mode()
        || authorization.secret_source != role.secret_source()
        || authorization.sender_direction != role.sender_direction()
        || authorization.receiver_direction != role.receiver_direction()
        || authorization.origin_direction != role.origin_direction()
        || authorization.route_leg != role.route_leg()
        || authorization.adaptor_secret_origin_id != role.adaptor_secret_origin_id().0
        || authorization.dom_claim_sender_id != role.dom_claim_sender_id().0
        || authorization.final_claim_receiver_id != role.final_claim_receiver_id().0
        || authorization.composition_binding_digest != role.composition_binding_digest()
    {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn require_m8_f7_v2_issuance_cross_binding(
    expected_chain_id: &[u8; 32],
    gate: &OperationalM8FundingGateRecordV2,
    issuance: &OperationalM8FundingIssuanceRecordV2,
) -> Result<(), SessionStoreError> {
    if issuance.gate_record_digest != gate.digest
        || issuance.binding.session_id() != &gate.role_binding.session_id().0
        || issuance.binding.chain_id() != expected_chain_id
        || issuance.binding.terms_hash() != &gate.ready_binding.terms_hash()
        || issuance.binding.shared_output_commitment()
            != &gate.ready_binding.shared_output_commitment()
        || issuance.binding.bp_statement_hash() != &gate.ready_binding.bp_statement_hash()
        || issuance.binding.funding_template_hash() != &gate.ready_binding.funding_template_hash()
        || issuance.binding.claim_template_hash() != &gate.ready_binding.claim_template_hash()
        || issuance.binding.claim_adaptor_point() != &gate.ready_binding.adaptor_point_sec1()
        || issuance.binding.m8_policy_digest() != &gate.ready_binding.m8_policy_digest()
        || issuance.binding.refund_tx_hash() != &gate.ready_binding.refund_tx_hash()
        || issuance.binding.backup_receipt_hash() != &gate.ready_binding.backup_receipt_hash()
        || issuance.binding.final_claim_role_binding_digest() != &gate.role_binding.digest()
        || issuance.binding.ready_binding_digest() != &gate.ready_binding.digest()
    {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn preflight_m8_f7_v2_ready_vote_ancestry(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    roster: &TransportRosterRecordV1,
    gate: &OperationalM8FundingGateRecordV2,
    gate_bound: &SessionRecordV1,
) -> Result<SessionRecordV1, SessionStoreError> {
    let records = m8_f7_directory(directories, M8F7DurableDirectory::Records)?;
    let messages = m8_f7_directory(directories, M8F7DurableDirectory::Messages)?;
    let prefix = format!("{}-", hex_lower(&gate.role_binding.session_id().0));
    let mut retained = Vec::<(String, Vec<u8>)>::new();
    messages.scan_lexicographic(|name, node| {
        if node.node_type != ExpectedNodeType::RegularFile || name.starts_with('.') {
            return Err(LinuxCapabilityError::InvalidObject);
        }
        if !name.starts_with(&prefix) {
            return Ok(());
        }
        let bytes = messages.read_bounded_file(
            &ValidatedComponent::registered(name)?,
            TRANSPORT_MESSAGE_MAX_LEN,
        )?;
        let record = TransportMessageRecordV1::from_bytes(&bytes)
            .map_err(|_| LinuxCapabilityError::ExactBytesMismatch)?;
        if record.message_type == 0x11 {
            retained.push((name.to_owned(), bytes));
        }
        Ok(())
    })?;
    let mut votes = retained
        .into_iter()
        .map(|(name, bytes)| Ok((name, TransportMessageRecordV1::from_bytes(&bytes)?)))
        .collect::<Result<Vec<_>, SessionStoreError>>()?;
    votes.sort_by_key(|(_, record)| record.successor.revision());
    if votes.len() != 2 || roster.participants.len() != 2 {
        return Err(SessionStoreError::FundingAuthorityUnavailable);
    }
    let mut predecessor = gate_bound.clone();
    for (index, (name, record)) in votes.iter().enumerate() {
        let participant = roster
            .participants
            .get(index)
            .ok_or(SessionStoreError::Quarantined)?;
        let envelope = ParsedTransportEnvelopeV1::parse(&record.signed_bytes)?;
        envelope
            .verify(&participant.identity_key)
            .map_err(|_| SessionStoreError::Quarantined)?;
        let durable = preflight_session_revision(
            records,
            gate.role_binding.session_id().0,
            record.successor.revision(),
        )?;
        if name
            != &transport_message_name(
                gate.role_binding.session_id().0,
                participant.participant_id,
                record.sequence,
                false,
            )
            || record.equivocation
            || record.session_id != gate.role_binding.session_id().0
            || record.sender_id != participant.participant_id
            || record.direction != participant.direction
            || envelope.chain_id != roster.chain_id
            || envelope.session_id != gate.role_binding.session_id().0
            || envelope.sender_id != participant.participant_id
            || envelope.sequence != record.sequence
            || envelope.previous_transcript_hash != predecessor.transcript_hash()
            || envelope.message_type != 0x11
            || envelope
                .payload(&record.signed_bytes)
                .map_err(|_| SessionStoreError::Quarantined)?
                != gate.ready_binding.digest()
            || record.message_digest != envelope.message_digest
            || predecessor.revision().checked_add(1) != Some(record.successor.revision())
            || record.successor.phase() != SessionPhaseV1::RefundSigned
            || record.successor.irreversible() != predecessor.irreversible()
            || record.successor.chain() != predecessor.chain()
            || record.successor.encrypted_payload() != predecessor.encrypted_payload()
            || durable.as_bytes() != record.successor.as_bytes()
            || require_transport_successor(
                &predecessor,
                &envelope,
                participant.direction,
                &record.successor,
            )
            .is_err()
        {
            return Err(SessionStoreError::Quarantined);
        }
        predecessor = record.successor.clone();
    }
    Ok(predecessor)
}

fn authenticate_m8_f7_v2_issuance_with_vote_ancestry(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
    expected_chain_id: &[u8; 32],
    roster: &TransportRosterRecordV1,
    gate: &OperationalM8FundingGateRecordV2,
    gate_bound: &SessionRecordV1,
    issuance: &OperationalM8FundingIssuanceRecordV2,
) -> Result<(), SessionStoreError> {
    require_m8_f7_v2_issuance_cross_binding(expected_chain_id, gate, issuance)?;
    let ready_head = preflight_m8_f7_v2_ready_vote_ancestry(directories, roster, gate, gate_bound)
        .map_err(|_| SessionStoreError::Quarantined)?;
    let mut irreversible = ready_head.irreversible();
    irreversible.funding_authorized = true;
    let expected = ready_head.advance(
        ready_head.revision(),
        SessionPhaseV1::FundingAuthorized,
        ready_head.transcript_hash(),
        irreversible,
        ready_head.chain(),
        ready_head.encrypted_payload(),
    )?;
    if issuance.authorized_revision != expected.revision()
        || issuance.funding_authorized_record.as_bytes() != expected.as_bytes()
    {
        return Err(SessionStoreError::Quarantined);
    }

    Ok(())
}

fn preflight_m8_f7_v2_finals(
    census: &M8F7DurableCensus,
    directories: &[(M8F7DurableDirectory, &RetainedDirectory); 6],
) -> Result<BTreeMap<[u8; 32], AuthenticatedM8F7V2Graph>, SessionStoreError> {
    let mut authenticated = BTreeMap::new();
    let records = m8_f7_directory(directories, M8F7DurableDirectory::Records)?;
    let artifacts = m8_f7_directory(directories, M8F7DurableDirectory::Artifacts)?;
    let consumptions = m8_f7_directory(directories, M8F7DurableDirectory::Consumptions)?;
    let rosters = m8_f7_directory(directories, M8F7DurableDirectory::Rosters)?;
    let order = [
        M8F7DurableArtifact::FundingGate,
        M8F7DurableArtifact::FundingIssuance,
        M8F7DurableArtifact::FundingCommit,
        M8F7DurableArtifact::ClaimSigningIssued,
        M8F7DurableArtifact::ClaimSigningConsumed,
        M8F7DurableArtifact::ClaimSigningBinding,
        M8F7DurableArtifact::ClaimPreSignature,
    ];
    for (session_id, finals) in &census.v2_finals {
        if finals.contains(&M8F7DurableArtifact::BackupProvenance) {
            preflight_m8_f7_v2_backup_provenance_ancestry(directories, *session_id)?;
        }
        if finals.contains(&M8F7DurableArtifact::FinalRefund) {
            preflight_m8_f7_v2_final_refund_ancestry(directories, *session_id)?;
        }
        if finals.iter().all(|artifact| {
            matches!(
                artifact,
                M8F7DurableArtifact::BackupProvenance | M8F7DurableArtifact::FinalRefund
            )
        }) {
            continue;
        }
        let mut missing_predecessor = false;
        for artifact in order {
            if finals.contains(&artifact) {
                if missing_predecessor {
                    return Err(SessionStoreError::Quarantined);
                }
            } else {
                missing_predecessor = true;
            }
        }
        // The FinalClaim artifacts continue the same chain, but they must NOT
        // be appended to `order`, and this is deliberate rather than an
        // oversight to be tidied up later. `order` is a strict prefix rule:
        // the first absent artifact marks every later one as a gap. Exposure
        // and observation are the two exclusive roles of a session, so a
        // receiver legitimately holds the observation and not the exposure —
        // under a prefix rule that receiver would be quarantined for being a
        // receiver. The rule they do obey is stated directly here instead, and
        // it is strictly stronger than a prefix: none of the three may exist
        // unless the whole chain they spend is complete, and an admission may
        // never precede its exposure.
        let carries_final_claim = finals.contains(&M8F7DurableArtifact::FinalClaimExposure)
            || finals.contains(&M8F7DurableArtifact::FinalClaimAdmission)
            || finals.contains(&M8F7DurableArtifact::FinalClaimObservation);
        if carries_final_claim && !order.iter().all(|artifact| finals.contains(artifact)) {
            return Err(SessionStoreError::Quarantined);
        }
        if finals.contains(&M8F7DurableArtifact::FinalClaimAdmission)
            && !finals.contains(&M8F7DurableArtifact::FinalClaimExposure)
        {
            return Err(SessionStoreError::Quarantined);
        }
        let roster_bytes = required_m8_f7_v2_preflight_read(rosters.read_bounded_file(
            &ValidatedComponent::registered(&roster_name(*session_id))?,
            TRANSPORT_ROSTER_LEN,
        ))?;
        let transport_roster = TransportRosterRecordV1::from_bytes(&roster_bytes)?;
        if transport_roster.session_id != *session_id {
            return Err(SessionStoreError::Quarantined);
        }
        let gate = OperationalM8FundingGateRecordV2::from_bytes(
            &transport_roster.chain_id,
            &m8_f7_v2_final_bytes(
                directories,
                *session_id,
                M8F7DurableArtifact::FundingGate,
                M8_FUNDING_GATE_V2_MAX_LEN,
            )?,
        )?;
        let gate_bound = preflight_m8_f7_v2_gate_ancestry(directories, *session_id, &gate)?;

        let issuance: Option<OperationalM8FundingIssuanceRecordV2> =
            if finals.contains(&M8F7DurableArtifact::FundingIssuance) {
                let issuance =
                    OperationalM8FundingIssuanceRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                        directories,
                        *session_id,
                        M8F7DurableArtifact::FundingIssuance,
                        M8_FUNDING_ISSUANCE_V2_MAX_LEN,
                    )?)?;
                authenticate_m8_f7_v2_issuance_with_vote_ancestry(
                    directories,
                    &transport_roster.chain_id,
                    &transport_roster,
                    &gate,
                    &gate_bound,
                    &issuance,
                )?;
                Some(issuance)
            } else {
                None
            };

        let commit = if finals.contains(&M8F7DurableArtifact::FundingCommit) {
            let issuance = issuance.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let commit = OperationalM8FundingCommitRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                directories,
                *session_id,
                M8F7DurableArtifact::FundingCommit,
                M8_FUNDING_COMMIT_V2_MAX_LEN,
            )?)?;
            let funding = validate_exact_dom_transaction(
                &commit.artifact.funding_bytes,
                DomTransactionValidationContextV1::new(
                    gate.validation_tip_height,
                    transport_roster.chain_id,
                    gate.validation_now_unix_seconds,
                ),
            )
            .map_err(|_| SessionStoreError::Quarantined)?;
            let (funding_template_bytes, funding_template_hash) =
                canonical_template_v1(&funding).map_err(|_| SessionStoreError::Quarantined)?;
            let broadcast = commit.consumption.broadcast_record()?;
            let terminal = preflight_session_revision(
                records,
                *session_id,
                commit.artifact.authorized_revision,
            )?;
            if commit.issuance_record_digest != issuance.digest
                || commit.final_claim_role_binding_digest != gate.role_binding.digest()
                || commit.ready_binding_digest != gate.ready_binding.digest()
                || commit.artifact.session_id != *session_id
                || commit.artifact.terms_hash != gate.ready_binding.terms_hash()
                || commit.artifact.authorized_revision < issuance.authorized_revision
                || commit.artifact.refund_unlock_height != gate.ready_binding.refund_unlock_height()
                || commit.artifact.refund_bytes != gate.refund_bytes
                || commit.consumption.authorized_revision != commit.artifact.authorized_revision
                || terminal.phase() != SessionPhaseV1::FundingAuthorized
                || !terminal.irreversible().funding_authorized
                || terminal.terms_hash() != gate.ready_binding.terms_hash()
                || funding_template_bytes != issuance.unsigned_template_bytes
                || funding_template_hash != *issuance.binding.funding_template_hash()
                || funding
                    .outputs
                    .iter()
                    .filter(|output| {
                        output.commitment.as_bytes()
                            == &gate.ready_binding.shared_output_commitment()
                    })
                    .count()
                    != 1
                || require_exact_successor(&terminal, terminal.revision(), &broadcast).is_err()
                || broadcast.phase() != SessionPhaseV1::FundingBroadcast
                || broadcast.digest() != &commit.consumption.broadcast_record_digest
            {
                return Err(SessionStoreError::Quarantined);
            }
            let artifact_name = artifact_name(*session_id);
            match artifacts.read_bounded_file(
                &ValidatedComponent::registered(&artifact_name)?,
                FUNDING_ARTIFACT_MAX_LEN,
            ) {
                Ok(bytes) if bytes != commit.artifact.bytes => {
                    return Err(SessionStoreError::Quarantined)
                }
                Ok(_) | Err(LinuxCapabilityError::NotFound) => {}
                Err(error) => return Err(error.into()),
            }
            let consumption_name = consumption_name(*session_id);
            match consumptions.read_bounded_file(
                &ValidatedComponent::registered(&consumption_name)?,
                CONSUMPTION_MAX_LEN,
            ) {
                Ok(bytes) if bytes != commit.consumption.bytes => {
                    return Err(SessionStoreError::Quarantined)
                }
                Ok(_) | Err(LinuxCapabilityError::NotFound) => {}
                Err(error) => return Err(error.into()),
            }
            Some(commit)
        } else {
            None
        };

        let issued = if finals.contains(&M8F7DurableArtifact::ClaimSigningIssued) {
            let issuance = issuance.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let commit = commit.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let issued = PostAnchorClaimAuthorizationRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                directories,
                *session_id,
                M8F7DurableArtifact::ClaimSigningIssued,
                POST_ANCHOR_CLAIM_AUTH_V2_RECORD_LEN,
            )?)?;
            require_post_anchor_role_v2(&issued, &gate)?;
            let issued_bound =
                preflight_session_revision(records, *session_id, issued.bound_session_revision)?;
            if issued.state != PostAnchorClaimAuthorizationStateV2::Issued
                || issued.m8_funding_gate_digest != gate.digest
                || issued.m8_funding_issuance_digest != issuance.digest
                || issued.operational_funding_commit_digest != commit.digest
                || issued.bound_session_record_digest != *issued_bound.digest()
                || issued_bound.phase() != SessionPhaseV1::FundingConfirmed
                || !issued_bound.irreversible().funding_authorized
                || issued_bound.terms_hash() != issued.terms_hash
                || issued_bound.transcript_hash() != issued.round_start_transcript_hash
                || !confirmed_funding_projection_has_depth(
                    issued_bound.chain(),
                    issued.dom_minimum_confirmations,
                )
            {
                return Err(SessionStoreError::Quarantined);
            }
            Some(issued)
        } else {
            None
        };

        let consumed = if finals.contains(&M8F7DurableArtifact::ClaimSigningConsumed) {
            let issued = issued.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let consumed =
                PostAnchorClaimAuthorizationRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                    directories,
                    *session_id,
                    M8F7DurableArtifact::ClaimSigningConsumed,
                    POST_ANCHOR_CLAIM_AUTH_V2_RECORD_LEN,
                )?)?;
            let expected = PostAnchorClaimAuthorizationRecordV2::new_consumed(issued)?;
            if consumed.state != PostAnchorClaimAuthorizationStateV2::Consumed
                || consumed.bytes != expected.bytes
            {
                return Err(SessionStoreError::Quarantined);
            }
            Some(consumed)
        } else {
            None
        };

        let signing_binding = if finals.contains(&M8F7DurableArtifact::ClaimSigningBinding) {
            let issued = issued.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let consumed = consumed.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let retained =
                PostAnchorClaimSigningBindingRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                    directories,
                    *session_id,
                    M8F7DurableArtifact::ClaimSigningBinding,
                    POST_ANCHOR_CLAIM_BINDING_V2_RECORD_LEN,
                )?)?;
            let signing_name = signing_binding_name(*session_id, PurposeV1::ClaimAdaptor);
            let signing_bytes = required_m8_f7_v2_preflight_read(rosters.read_bounded_file(
                &ValidatedComponent::registered(&signing_name)?,
                SIGNING_BINDING_MAX_LEN,
            ))?;
            let signing = SigningSessionBindingRecordV1::from_bytes(&signing_bytes)?;
            let mut roster_bytes = Vec::with_capacity(202);
            roster_bytes.extend_from_slice(&2_u16.to_le_bytes());
            for index in 0..2 {
                let offset = 472 + index * 99;
                roster_bytes.extend_from_slice(&signing.bytes[offset..offset + 99]);
            }
            let signing_digest =
                copy_array(&signing.bytes[signing.bytes.len().saturating_sub(DIGEST_LEN)..])?;
            if retained.session_id != *session_id
                || retained.issuance_record_digest != issued.digest
                || retained.consumption_record_digest != consumed.digest
                || retained.signing_binding_record_digest != signing_digest
                || retained.roster_digest
                    != tagged_hash(POST_ANCHOR_CLAIM_ROSTER_HASH_TAG, &roster_bytes)
                || retained.round_start_record_digest != signing.bytes[120..152]
                || retained.final_claim_role_binding_digest != gate.role_binding.digest()
                || retained.ready_binding_digest != gate.ready_binding.digest()
                || signing.session_id != *session_id
                || signing.purpose != PurposeV1::ClaimAdaptor
                || signing.bytes[48..80] != transport_roster.chain_id
                || signing.bytes[80..112] != issued.terms_hash
                || signing.bytes[184..216] != issued.round_start_transcript_hash
                || signing.bytes[240..272] != issued.claim_template_hash
                || signing.bytes[272..305] != issued.adaptor_point.to_compressed_bytes()
            {
                return Err(SessionStoreError::Quarantined);
            }
            Some(retained)
        } else {
            None
        };

        if finals.contains(&M8F7DurableArtifact::ClaimPreSignature) {
            let issued = issued.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let consumed = consumed.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let binding = signing_binding
                .as_ref()
                .ok_or(SessionStoreError::Quarantined)?;
            let retained = PostAnchorClaimPreSignatureRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                directories,
                *session_id,
                M8F7DurableArtifact::ClaimPreSignature,
                POST_ANCHOR_CLAIM_PRE_SIGNATURE_V2_RECORD_LEN,
            )?)?;
            let terminal =
                preflight_session_revision(records, *session_id, retained.terminal_revision)?;
            if retained.session_id != *session_id
                || retained.chain_id != issued.chain_id
                || retained.claim_template_hash != issued.claim_template_hash
                || retained.adaptor_point != issued.adaptor_point
                || retained.issuance_record_digest != issued.digest
                || retained.consumption_record_digest != consumed.digest
                || retained.signing_binding_record_digest != binding.signing_binding_record_digest
                || retained.round_binding_record_digest != binding.digest
                || retained.round_start_record_digest != binding.round_start_record_digest
                || retained.roster_digest != binding.roster_digest
                || retained.final_claim_role_binding_digest != gate.role_binding.digest()
                || retained.ready_binding_digest != gate.ready_binding.digest()
                || retained.terminal_record_digest != *terminal.digest()
                || retained.terminal_transcript_hash != terminal.transcript_hash()
            {
                return Err(SessionStoreError::Quarantined);
            }
        }

        // FinalClaim V2. Order matters and is the order of causation:
        // exposure and observation are the two mutually exclusive roles one
        // session can take over its own claim, and admission is a successor
        // of exposure. None of the three may exist without the consumed
        // claim-signing authority it spends, so each requires that ancestry
        // before its own cross-binding is even read.
        if finals.contains(&M8F7DurableArtifact::FinalClaimExposure)
            && finals.contains(&M8F7DurableArtifact::FinalClaimObservation)
        {
            // One session is the sender or the receiver of its FinalClaim,
            // never both. The Store is the primary barrier for that; a cross
            // detector downstream is a second opinion, not the rule.
            return Err(SessionStoreError::Quarantined);
        }

        let exposure = if finals.contains(&M8F7DurableArtifact::FinalClaimExposure) {
            let issued = issued.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let consumed = consumed.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let exposure =
                OperationalFinalClaimExposureRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                    directories,
                    *session_id,
                    M8F7DurableArtifact::FinalClaimExposure,
                    OPERATIONAL_FINAL_CLAIM_EXPOSURE_V2_RECORD_MAX_LEN,
                )?)?;
            // The successor may legitimately be absent here, and only here:
            // that is the persist-before-successor cut this marker can repair
            // by itself. Everything that does not depend on the successor
            // being durable is demanded unconditionally below; the crossings
            // that do are demanded only when it is. The recovery pass
            // republishes it from the bytes embedded in this very record, and
            // `audit_locked` then re-runs this whole preflight with the
            // successor present, so nothing is skipped — it is deferred by one
            // step of the same opening.
            let bound = optional_preflight_session_revision(
                records,
                *session_id,
                exposure.bound_session_revision,
            )?;
            let predecessor = preflight_session_revision(
                records,
                *session_id,
                exposure.exposure_predecessor_revision,
            )?;
            if exposure.session_id != *session_id
                || exposure.chain_id != issued.chain_id
                || exposure.settlement_id != issued.settlement_id
                || exposure.terms_hash != issued.terms_hash
                || exposure.claim_template_hash != issued.claim_template_hash
                || exposure.dom_shared_output_commitment != issued.dom_shared_output_commitment
                || exposure.adaptor_point != issued.adaptor_point.to_compressed_bytes()
                || exposure.round_start_transcript_hash != issued.round_start_transcript_hash
                || exposure.final_claim_role_binding_digest
                    != issued.final_claim_role_binding_digest
                || exposure.ready_binding_digest != issued.ready_binding_digest
                || exposure.dom_claim_sender_id != issued.dom_claim_sender_id
                || exposure.final_claim_receiver_id != issued.final_claim_receiver_id
                || exposure.reveal_mode_tag != issued.reveal_mode.to_byte()
                || exposure.secret_source_tag != issued.secret_source.to_byte()
                || exposure.dom_minimum_confirmations != issued.dom_minimum_confirmations
                || exposure.dom_confirmation_depth != issued.dom_confirmation_depth
                || exposure.bitcoin_confirmation_depth != issued.bitcoin_confirmation_depth
                || exposure.issuance_record_digest != issued.digest
                || exposure.consumption_record_digest != consumed.digest
                // A claim validated against genesis is not a validated claim,
                // and `random_nonzero` never mints a zero instance id.
                || exposure.validation_height == 0
                || exposure.open_instance_id == [0; 32]
                // The predecessor named by the record must be the retained one.
                || exposure.exposure_predecessor_record_digest != *predecessor.digest()
                || exposure.exposure_predecessor_transcript_hash != predecessor.transcript_hash()
            {
                return Err(SessionStoreError::Quarantined);
            }
            require_final_claim_exposure_delta_v1(&predecessor, &exposure.successor_record)?;
            if let Some(bound) = bound.as_ref() {
                if exposure.bound_session_record_digest != *bound.digest()
                    || bound.session_id() != *session_id
                    // Belt and braces: the digest crossing above already makes
                    // `bound` the exact record embedded in the marker, and the
                    // codec refuses an embedded successor without the bit.
                    // Kept so the audit states the invariant it depends on.
                    || !bound.irreversible().adaptor_secret_exposed
                    // The successor embedded in the record must be
                    // byte-identical to the durable head it claims to have
                    // produced. This is what makes the irreversible marker
                    // provably born exactly once rather than merely present.
                    || exposure.successor_record.as_bytes() != bound.as_bytes()
                    // Belt and braces given the codec, which already ties the
                    // successor revision to `bound_session_revision` and to
                    // `exposure_predecessor_revision + 1`. Kept so the audit
                    // does not silently depend on that tie surviving a codec
                    // change.
                    || exposure.exposure_successor_revision != bound.revision()
                {
                    return Err(SessionStoreError::Quarantined);
                }
            }
            Some(exposure)
        } else {
            None
        };

        if finals.contains(&M8F7DurableArtifact::FinalClaimAdmission) {
            // An admission with no exposure would claim a node accepted a
            // transaction this Store never proved it had exposed.
            let exposure = exposure.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let admission =
                OperationalFinalClaimAdmissionRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                    directories,
                    *session_id,
                    M8F7DurableArtifact::FinalClaimAdmission,
                    OPERATIONAL_FINAL_CLAIM_ADMISSION_V2_LEN,
                )?)?;
            let bound =
                preflight_session_revision(records, *session_id, admission.bound_session_revision)?;
            if admission.session_id != *session_id
                || admission.chain_id != exposure.chain_id
                || admission.settlement_id != exposure.settlement_id
                || admission.exposure_record_digest != exposure.digest
                || admission.tx_hash != exposure.tx_hash
                || admission.dom_claim_sender_id != exposure.dom_claim_sender_id
                || admission.final_claim_receiver_id != exposure.final_claim_receiver_id
                || admission.action_scope_digest != exposure.action_scope_digest
                || admission.open_instance_id != exposure.open_instance_id
                || admission.bound_session_revision < exposure.bound_session_revision
                || admission.bound_session_record_digest != *bound.digest()
                || bound.session_id() != *session_id
                || !bound.irreversible().adaptor_secret_exposed
                // Admission cannot precede the height the claim was validated
                // against.
                || admission.admitted_height < exposure.validation_height
            {
                return Err(SessionStoreError::Quarantined);
            }
            // The economic proof is the node's own facts recomputed against
            // their domain-separated commitment, by the same authority that
            // minted them. A durable "admitted" byte proves nothing on its own.
            let state = submission_state_from_tag_v1(admission.receipt_state_tag)
                .ok_or(SessionStoreError::Quarantined)?;
            validate_submission_receipt_facts_v1(
                admission.tx_hash,
                state,
                admission.receipt_relayed == 1,
                admission.receipt_facts_digest,
            )
            .map_err(|_| SessionStoreError::Quarantined)?;
        }

        if finals.contains(&M8F7DurableArtifact::FinalClaimObservation) {
            let issued = issued.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let consumed = consumed.as_ref().ok_or(SessionStoreError::Quarantined)?;
            let observation =
                OperationalFinalClaimObservationRecordV2::from_bytes(&m8_f7_v2_final_bytes(
                    directories,
                    *session_id,
                    M8F7DurableArtifact::FinalClaimObservation,
                    OPERATIONAL_FINAL_CLAIM_OBSERVATION_V2_RECORD_MAX_LEN,
                )?)?;
            // Absent successor: the same repairable cut as in the exposure
            // arm above, and repaired by the same pass from the bytes this
            // record embeds.
            let bound = optional_preflight_session_revision(
                records,
                *session_id,
                observation.bound_session_revision,
            )?;
            let predecessor = preflight_session_revision(
                records,
                *session_id,
                observation.exposure_predecessor_revision,
            )?;
            if observation.session_id != *session_id
                || observation.chain_id != issued.chain_id
                || observation.settlement_id != issued.settlement_id
                || observation.claim_template_hash != issued.claim_template_hash
                || observation.dom_shared_output_commitment != issued.dom_shared_output_commitment
                || observation.adaptor_point != issued.adaptor_point.to_compressed_bytes()
                || observation.final_claim_role_binding_digest
                    != issued.final_claim_role_binding_digest
                || observation.final_claim_receiver_id != issued.final_claim_receiver_id
                || observation.dom_claim_sender_id != issued.dom_claim_sender_id
                || observation.issuance_record_digest != issued.digest
                || observation.consumption_record_digest != consumed.digest
                // A claim observed at genesis is not an observation, and
                // `random_nonzero` never mints a zero instance id. The block
                // identity is what makes the marker auditable against a
                // reorganisation and is refused when zeroed by the codec.
                || observation.observed_height == 0
                || observation.open_instance_id == [0; 32]
                || observation.exposure_predecessor_record_digest != *predecessor.digest()
                || observation.exposure_predecessor_transcript_hash
                    != predecessor.transcript_hash()
                // `tx_hash` is deliberately not crossed here, and this is the
                // note rather than a silence: nothing in the retained V2 graph
                // fixes it. The claim template hash is frozen, but the
                // transaction identity depends on the final signature, which
                // the receiver never holds. The codec fixes it against zero,
                // and it is crossed for real the moment the claim is carried —
                // the `0x12` arm of the successor authenticator recomputes the
                // identity from the accepted payload and requires it to equal
                // this field, and the message phase of `audit_transport`
                // re-runs that on every open.
                //
                // The tip the marker retained must still agree with the tip
                // this session was looking at when the marker was minted,
                // in both halves. The delta forbids the projection from moving
                // in that step, so the predecessor carries it — which is why
                // this crossing needs no durable successor and belongs here
                // rather than below.
                //
                // Subsumed, exactly as in the resume: codec plus delta already
                // imply it, and no mutation distinguishes it from absent. Kept
                // as a statement of the invariant, not as the thing enforcing
                // it.
                || observation.observed_tip_height != predecessor.chain().tip_height
                || observation.observed_tip_id != predecessor.chain().tip_id
                // And the burial depth, measured against the retained tip —
                // never against the projection — with the same frozen
                // number and the same arithmetic as at mint time. This
                // subsumes the old same-height block-identity rule: depth one
                // is the only case where the tip must be the observed block,
                // and the predicate already says so.
                || !observed_claim_has_depth(
                    observation.observed_height,
                    observation.observed_block_id,
                    observation.observed_tip_height,
                    observation.observed_tip_id,
                    issued.dom_minimum_confirmations,
                )
            {
                return Err(SessionStoreError::Quarantined);
            }
            require_final_claim_exposure_delta_v1(&predecessor, &observation.successor_record)?;
            if let Some(bound) = bound.as_ref() {
                if observation.bound_session_record_digest != *bound.digest()
                    || bound.session_id() != *session_id
                    // Belt and braces, exactly as in the exposure arm above.
                    || !bound.irreversible().adaptor_secret_exposed
                    || observation.successor_record.as_bytes() != bound.as_bytes()
                    // Belt and braces, exactly as in the exposure arm above.
                    || observation.exposure_successor_revision != bound.revision()
                {
                    return Err(SessionStoreError::Quarantined);
                }
            }
        }

        authenticated.insert(*session_id, AuthenticatedM8F7V2Graph { gate, issuance });
    }
    Ok(authenticated)
}

fn parse_m8_f7_durable_profile_name(
    name: &str,
) -> Option<([u8; 32], M8F7DurableProfileDescriptor, bool)> {
    for descriptor in M8_F7_DURABLE_PROFILE_DESCRIPTORS {
        if let Some(session_id) = name.strip_suffix(descriptor.suffix).and_then(decode_hex_32) {
            return Some((session_id, descriptor, false));
        }

        let staging_suffix = format!("{}.staging", descriptor.suffix);
        if let Some(session_id) = name
            .strip_prefix('.')
            .and_then(|body| body.strip_suffix(&staging_suffix))
            .and_then(decode_hex_32)
        {
            return Some((session_id, descriptor, true));
        }
    }
    None
}

impl PreRecoveryStagingInventoryV1 {
    fn capture(
        directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
    ) -> Result<Self, SessionStoreError> {
        require_complete_pre_recovery_directory_set(directories)?;
        let mut entries = Vec::new();
        for (directory_kind, directory) in directories {
            let mut finals = BTreeSet::new();
            let mut staged = Vec::new();
            directory.scan_lexicographic_including_exclusions(|name, node| {
                if node.node_type != ExpectedNodeType::RegularFile {
                    return Err(LinuxCapabilityError::InvalidObject);
                }
                if name.starts_with('.') {
                    let final_name = pre_recovery_staging_final_name(*directory_kind, name)
                        .ok_or(LinuxCapabilityError::InvalidDirectoryEntry)?;
                    let staging = ValidatedComponent::registered(name)?;
                    let mut retained = directory.open_file(&staging, false)?;
                    let bytes = retained.read_bounded(PRE_RECOVERY_STAGING_MAX_LEN)?;
                    directory.require_named_file_identity(&staging, &retained)?;
                    staged.push((
                        staging,
                        ValidatedComponent::registered(final_name)?,
                        retained,
                        tagged_hash(RECOVERY_SOURCE_HASH_TAG, &bytes),
                    ));
                } else {
                    finals.insert(name.to_owned());
                }
                Ok(())
            })?;
            for (staging, final_name, retained, exact_digest) in staged {
                if finals.contains(final_name.as_str()) {
                    return Err(SessionStoreError::Quarantined);
                }
                entries.push(PreRecoveryStagingEntryV1 {
                    directory: *directory_kind,
                    staging,
                    final_name,
                    retained,
                    exact_digest,
                });
                if entries.len() > MAX_PREPARED_RECOVERY_SOURCES {
                    return Err(SessionStoreError::CapacityExceeded);
                }
            }
        }
        Ok(Self { entries })
    }

    fn install_scan_exclusions(
        &self,
        directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
    ) -> Result<(), SessionStoreError> {
        require_complete_pre_recovery_directory_set(directories)?;
        for (directory_kind, directory) in directories {
            let exclusions = self
                .entries
                .iter()
                .filter(|entry| entry.directory == *directory_kind)
                .map(|entry| (entry.staging.as_str().to_owned(), entry.retained.identity))
                .collect::<BTreeMap<_, _>>();
            directory.install_scan_exclusions(exclusions)?;
        }
        Ok(())
    }

    fn clear_scan_exclusions(
        directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
    ) -> Result<(), SessionStoreError> {
        require_complete_pre_recovery_directory_set(directories)?;
        for (_, directory) in directories {
            directory.clear_scan_exclusions()?;
        }
        Ok(())
    }

    fn revalidate(
        &mut self,
        directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
    ) -> Result<(), SessionStoreError> {
        require_complete_pre_recovery_directory_set(directories)?;
        let expected = self
            .entries
            .iter()
            .map(|entry| (entry.directory, entry.staging.as_str().to_owned(), true))
            .collect::<BTreeSet<_>>();
        let mut observed = BTreeSet::new();
        for (directory_kind, directory) in directories {
            directory.scan_lexicographic_including_exclusions(|name, node| {
                if node.node_type != ExpectedNodeType::RegularFile {
                    return Err(LinuxCapabilityError::InvalidObject);
                }
                let staging = name.starts_with('.');
                if staging {
                    pre_recovery_staging_final_name(*directory_kind, name)
                        .ok_or(LinuxCapabilityError::InvalidDirectoryEntry)?;
                }
                if staging {
                    observed.insert((*directory_kind, name.to_owned(), true));
                }
                Ok(())
            })?;
        }
        if observed != expected {
            return Err(SessionStoreError::Quarantined);
        }
        for entry in &mut self.entries {
            let directory = pre_recovery_directory(directories, entry.directory)?;
            directory.require_named_file_identity(&entry.staging, &entry.retained)?;
            let bytes = entry.retained.read_bounded(PRE_RECOVERY_STAGING_MAX_LEN)?;
            if tagged_hash(RECOVERY_SOURCE_HASH_TAG, &bytes) != entry.exact_digest {
                return Err(SessionStoreError::Quarantined);
            }
            directory.require_named_file_identity(&entry.staging, &entry.retained)?;
            match directory.open_file(&entry.final_name, false) {
                Err(LinuxCapabilityError::NotFound) => {}
                Ok(_) => return Err(SessionStoreError::Quarantined),
                Err(error) => return Err(error.into()),
            }
        }
        Ok(())
    }

    fn recover(
        mut self,
        directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
    ) -> Result<(), SessionStoreError> {
        self.revalidate(directories)?;
        for entry in self.entries {
            let directory = pre_recovery_directory(directories, entry.directory)?;
            directory.unlink_verified_file(&entry.staging, &entry.retained)?;
        }
        Ok(())
    }
}

fn require_complete_pre_recovery_directory_set(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
) -> Result<(), SessionStoreError> {
    let observed = directories
        .iter()
        .map(|(directory, _)| *directory)
        .collect::<BTreeSet<_>>();
    let expected = BTreeSet::from([
        M8F7DurableDirectory::Records,
        M8F7DurableDirectory::Artifacts,
        M8F7DurableDirectory::Consumptions,
        M8F7DurableDirectory::Rosters,
        M8F7DurableDirectory::Messages,
        M8F7DurableDirectory::ReservationLookups,
    ]);
    if directories.len() != expected.len() || observed != expected {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn require_canonical_pre_recovery_inventory(
    directories: &[(M8F7DurableDirectory, &RetainedDirectory)],
) -> Result<(), SessionStoreError> {
    require_complete_pre_recovery_directory_set(directories)?;
    for (directory_kind, directory) in directories {
        directory.scan_lexicographic_including_exclusions(|name, node| {
            if node.node_type != ExpectedNodeType::RegularFile {
                return Err(LinuxCapabilityError::InvalidObject);
            }
            let canonical = if name.starts_with('.') {
                pre_recovery_staging_final_name(*directory_kind, name).is_some()
            } else {
                canonical_pre_recovery_final_name(*directory_kind, name)
            };
            if !canonical {
                return Err(LinuxCapabilityError::InvalidDirectoryEntry);
            }
            Ok(())
        })?;
    }
    Ok(())
}

fn pre_recovery_directory<'a>(
    directories: &'a [(M8F7DurableDirectory, &'a RetainedDirectory)],
    expected: M8F7DurableDirectory,
) -> Result<&'a RetainedDirectory, SessionStoreError> {
    directories
        .iter()
        .find_map(|(directory, retained)| (*directory == expected).then_some(*retained))
        .ok_or(SessionStoreError::Quarantined)
}

fn pre_recovery_staging_final_name(
    directory: M8F7DurableDirectory,
    staging_name: &str,
) -> Option<&str> {
    let final_name = staging_name.strip_prefix('.')?.strip_suffix(".staging")?;
    canonical_pre_recovery_final_name(directory, final_name).then_some(final_name)
}

/// Whether a final name is one this Store can itself have published.
///
/// # This set has to mirror the names `publish_immutable` can generate
///
/// `publish_immutable` writes `.{final}.staging` and then renames it, so a
/// process that dies between the two leaves that staging file behind. The next
/// `open` hands it to `PreRecoveryStagingInventoryV1::capture`, which refuses
/// outright — before the census, before the preflight — any dotted entry whose
/// name this function does not recognize. A published name missing from here
/// is therefore not a cosmetic gap: it turns an ordinary crash cut into a
/// store that can never be opened again.
///
/// That is not hypothetical. The operational V1 funding gate, issuance and
/// commit were all outside this set while being published on live paths
/// (`persist_funding_gate`, `persist_funding_issuance`, `persist_funding_commit`),
/// and a crash in any of the three left an unopenable store. The census does
/// not catch it either: it only looks at names the M.8/F7 descriptor table
/// parses, and those three are not in the table, so it ignores them entirely.
///
/// **The rule, for whoever adds the next artifact:** every `final_name` passed
/// to `publish_immutable` must be accepted here, in the directory it is
/// published to. There are thirty-seven such call sites in this file; the
/// descriptor table covers most of them automatically through the branch
/// below, and the per-directory lists carry the rest. Nothing checks the two
/// sets against each other mechanically — adding a publication and forgetting
/// this function compiles and passes every other test. What does exercise the
/// relation is
/// `every_published_staging_name_survives_a_crash_cut_and_is_recovered`, which
/// plants a crash-cut staging file for each of the three that were wrong and
/// requires the store to open and to have swept it. Add a case there when you
/// add a publication.
fn canonical_pre_recovery_final_name(directory: M8F7DurableDirectory, name: &str) -> bool {
    if parse_m8_f7_durable_profile_name(name)
        .is_some_and(|(_, descriptor, staging)| !staging && descriptor.directory == directory)
    {
        return true;
    }
    match directory {
        M8F7DurableDirectory::Records => parse_session_record_name(name).is_some(),
        M8F7DurableDirectory::Artifacts => [
            ".funding-artifacts",
            ".operational-final-refund",
            // Published by `persist_funding_gate` and
            // `persist_funding_issuance`. Neither is in the M.8/F7 descriptor
            // table, so the branch above never covers them.
            ".operational-funding-gate",
            ".operational-funding-issuance",
        ]
        .iter()
        .any(|suffix| exact_session_scoped_name(name, suffix)),
        M8F7DurableDirectory::Consumptions => [
            ".funding-consumed",
            // Published by `persist_funding_commit`, and likewise absent from
            // the descriptor table.
            ".operational-funding-commit",
        ]
        .iter()
        .any(|suffix| exact_session_scoped_name(name, suffix)),
        M8F7DurableDirectory::Rosters => {
            [
                ".transport-roster",
                ".transport-identities",
                ".local-transport-signer",
                ".early-transport-authority",
                ".bp-transport-authority",
                ".template-transport-authority",
                ".operational-abort-authority",
            ]
            .iter()
            .any(|suffix| exact_session_scoped_name(name, suffix))
                || parse_signing_binding_name(name).is_some()
                || parse_outbound_dsc1_name(name).is_some()
                || parse_outbound_dsc1_reconciled_name(name).is_some()
        }
        M8F7DurableDirectory::Messages => canonical_transport_message_name(name),
        M8F7DurableDirectory::ReservationLookups => {
            parse_reservation_lookup_record_name(name).is_some()
        }
    }
}

fn exact_session_scoped_name(name: &str, suffix: &str) -> bool {
    name.strip_suffix(suffix).and_then(decode_hex_32).is_some()
}

fn canonical_transport_message_name(name: &str) -> bool {
    let body = if let Some(body) = name.strip_suffix(".message") {
        body
    } else if let Some(body) = name.strip_suffix(".equivocation") {
        body
    } else {
        return false;
    };
    body.len() == 150
        && body.as_bytes().get(64) == Some(&b'-')
        && body.as_bytes().get(129) == Some(&b'-')
        && decode_hex_32(&body[..64]).is_some()
        && decode_hex_32(&body[65..129]).is_some()
        && body[130..].parse::<u64>().is_ok()
}

#[cfg(test)]
fn recover_staging(directory: &RetainedDirectory) -> Result<(), SessionStoreError> {
    let mut staging = Vec::new();
    directory.scan_lexicographic(|name, node| {
        if node.node_type != ExpectedNodeType::RegularFile {
            return Err(LinuxCapabilityError::InvalidObject);
        }
        if name.starts_with('.') && name.ends_with(".staging") {
            staging.push(name.to_owned());
        }
        Ok(())
    })?;
    for name in staging {
        let component = ValidatedComponent::registered(&name)?;
        let retained = directory.open_file(&component, false)?;
        directory.unlink_verified_file(&component, &retained)?;
    }
    Ok(())
}

fn resumable_store_id(
    root: &RetainedDirectory,
    root_name: &str,
    policy: &BudgetPolicyV1,
    creation_binding: [u8; 32],
) -> Result<[u8; 32], SessionStoreError> {
    root.revalidate()?;
    let mut material = Vec::with_capacity(32 + 8 + 8 + 4 + root_name.len() + 32);
    material.extend_from_slice(&creation_binding);
    material.extend_from_slice(&root.identity.device.to_le_bytes());
    material.extend_from_slice(&root.identity.inode.to_le_bytes());
    let root_name_len =
        u32::try_from(root_name.len()).map_err(|_| SessionStoreError::Quarantined)?;
    material.extend_from_slice(&root_name_len.to_le_bytes());
    material.extend_from_slice(root_name.as_bytes());
    material.extend_from_slice(policy.policy_digest());
    let store_id = tagged_hash(RESUMABLE_STORE_ID_TAG, &material);
    if store_id == [0; 32] {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(store_id)
}

#[cfg(test)]
fn test_resumable_creation_crash_hook(boundary: &str) {
    if std::env::var("DOM_CONTRACTS_STORE_CREATE_CRASH_CUT")
        .ok()
        .as_deref()
        == Some(boundary)
    {
        if let Some(marker) = std::env::var_os("DOM_CONTRACTS_STORE_CREATE_CRASH_MARKER") {
            let _result = std::fs::write(marker, boundary.as_bytes());
        }
        std::process::abort();
    }
}

#[cfg(not(test))]
const fn test_resumable_creation_crash_hook(_boundary: &str) {}

fn preflight_resumable_creation_prefix(
    root: &RetainedDirectory,
    files: &[(&str, &[u8])],
    directories: &[&str],
) -> Result<(), SessionStoreError> {
    let expected = files
        .iter()
        .map(|(name, _)| (*name, ExpectedNodeType::RegularFile))
        .chain(
            directories
                .iter()
                .map(|name| (*name, ExpectedNodeType::Directory)),
        )
        .collect::<Vec<_>>();
    let mut observed = BTreeMap::new();
    root.scan_lexicographic(|name, identity| {
        observed.insert(name.to_owned(), identity.node_type);
        Ok(())
    })?;
    if observed.iter().any(|(name, node)| {
        !expected.iter().any(|(expected_name, expected_node)| {
            name.as_str() == *expected_name && node == expected_node
        })
    }) {
        return Err(SessionStoreError::Quarantined);
    }
    let mut missing_seen = false;
    for (name, expected_type) in &expected {
        match observed.get(*name) {
            None => missing_seen = true,
            Some(actual_type) if missing_seen || actual_type != expected_type => {
                return Err(SessionStoreError::Quarantined)
            }
            Some(_) => {}
        }
    }
    for (name, expected_bytes) in files {
        if observed.contains_key(*name) {
            let component = ValidatedComponent::registered(name)?;
            let actual = root.read_bounded_file(&component, expected_bytes.len())?;
            if actual != *expected_bytes && !expected_bytes.starts_with(&actual) {
                return Err(SessionStoreError::Quarantined);
            }
        }
    }
    for name in directories {
        if observed.contains_key(*name) {
            let directory = root.open_child_directory(ValidatedComponent::registered(name)?)?;
            require_empty_resumable_creation_directory(&directory)?;
        }
    }
    Ok(())
}

fn complete_resumable_creation_file(
    root: &RetainedDirectory,
    name: &str,
    expected_bytes: &[u8],
) -> Result<(), SessionStoreError> {
    complete_resumable_creation_file_with_hook(root, name, expected_bytes, || Ok(()))
}

fn complete_resumable_creation_file_with_hook<BeforeUnlink>(
    root: &RetainedDirectory,
    name: &str,
    expected_bytes: &[u8],
    before_unlink: BeforeUnlink,
) -> Result<(), SessionStoreError>
where
    BeforeUnlink: FnOnce() -> Result<(), SessionStoreError>,
{
    let component = ValidatedComponent::registered(name)?;
    match root.open_file(&component, false) {
        Ok(mut retained) => {
            let actual = retained.read_bounded(expected_bytes.len())?;
            root.require_named_file_identity(&component, &retained)?;
            if actual == expected_bytes {
                return Ok(());
            }
            if !expected_bytes.starts_with(&actual) {
                return Err(SessionStoreError::Quarantined);
            }
            before_unlink()?;
            root.unlink_verified_file(&component, &retained)?;
        }
        Err(LinuxCapabilityError::NotFound) => {}
        Err(error) => return Err(error.into()),
    }
    root.revalidate()?;
    root.create_immutable_file(&component, expected_bytes)?;
    Ok(())
}

fn complete_resumable_creation_directory(
    root: &RetainedDirectory,
    name: &str,
) -> Result<(), SessionStoreError> {
    let component = ValidatedComponent::registered(name)?;
    match root.open_child_directory(component.clone()) {
        Ok(directory) => require_empty_resumable_creation_directory(&directory),
        Err(LinuxCapabilityError::NotFound) => {
            root.revalidate()?;
            let directory = root.create_child_directory(component)?;
            require_empty_resumable_creation_directory(&directory)
        }
        Err(error) => Err(error.into()),
    }
}

fn require_empty_resumable_creation_directory(
    directory: &RetainedDirectory,
) -> Result<(), SessionStoreError> {
    let mut empty = true;
    directory.scan_lexicographic(|_, _| {
        empty = false;
        Ok(())
    })?;
    if !empty {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn require_root_inventory(root: &RetainedDirectory) -> Result<(), SessionStoreError> {
    let expected = BTreeMap::from([
        (ROOT_IDENTITY_NAME, ExpectedNodeType::RegularFile),
        (LOCK_IDENTITY_NAME, ExpectedNodeType::RegularFile),
        (POLICY_NAME, ExpectedNodeType::RegularFile),
        (RECORDS_NAME, ExpectedNodeType::Directory),
        (ARTIFACTS_NAME, ExpectedNodeType::Directory),
        (CONSUMPTIONS_NAME, ExpectedNodeType::Directory),
        (ROSTERS_NAME, ExpectedNodeType::Directory),
        (MESSAGES_NAME, ExpectedNodeType::Directory),
        (RESERVATION_LOOKUPS_NAME, ExpectedNodeType::Directory),
    ]);
    let mut observed = BTreeMap::new();
    root.scan_lexicographic(|name, identity| {
        observed.insert(name.to_owned(), identity.node_type);
        Ok(())
    })?;
    if observed.len() != expected.len()
        || observed
            .iter()
            .any(|(name, node)| expected.get(name.as_str()) != Some(node))
    {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn encode_root_identity(store_id: [u8; 32], policy_digest: [u8; 32]) -> [u8; ROOT_IDENTITY_LEN] {
    let mut bytes = [0; ROOT_IDENTITY_LEN];
    bytes[..8].copy_from_slice(ROOT_MAGIC);
    bytes[8..10].copy_from_slice(&FORMAT_VERSION.to_le_bytes());
    bytes[16..48].copy_from_slice(&store_id);
    bytes[48..80].copy_from_slice(&policy_digest);
    let digest = tagged_hash(ROOT_HASH_TAG, &bytes[..80]);
    bytes[80..].copy_from_slice(&digest);
    bytes
}

fn decode_root_identity(
    bytes: &[u8],
    expected_policy_digest: &[u8; 32],
) -> Result<[u8; 32], SessionStoreError> {
    if bytes.len() != ROOT_IDENTITY_LEN
        || &bytes[..8] != ROOT_MAGIC
        || u16::from_le_bytes([bytes[8], bytes[9]]) != FORMAT_VERSION
        || bytes[10..16] != [0; 6]
        || bytes[48..80] != *expected_policy_digest
        || bytes[80..] != tagged_hash(ROOT_HASH_TAG, &bytes[..80])
    {
        return Err(SessionStoreError::Quarantined);
    }
    let store_id = copy_array(&bytes[16..48])?;
    if store_id == [0; 32] {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(store_id)
}

fn encode_lock_identity(store_id: [u8; 32], root_digest: [u8; 32]) -> [u8; LOCK_IDENTITY_LEN] {
    let mut bytes = [0; LOCK_IDENTITY_LEN];
    bytes[..8].copy_from_slice(LOCK_MAGIC);
    bytes[8..10].copy_from_slice(&FORMAT_VERSION.to_le_bytes());
    bytes[16..48].copy_from_slice(&store_id);
    bytes[48..80].copy_from_slice(&tagged_hash(
        LOCK_HASH_TAG,
        &[&store_id[..], &root_digest[..]].concat(),
    ));
    bytes
}

fn decode_lock_identity(
    bytes: &[u8],
    store_id: [u8; 32],
    root_digest: [u8; 32],
) -> Result<(), SessionStoreError> {
    if bytes.len() != LOCK_IDENTITY_LEN
        || &bytes[..8] != LOCK_MAGIC
        || u16::from_le_bytes([bytes[8], bytes[9]]) != FORMAT_VERSION
        || bytes[10..16] != [0; 6]
        || bytes[16..48] != store_id
        || bytes[48..80] != tagged_hash(LOCK_HASH_TAG, &[&store_id[..], &root_digest[..]].concat())
    {
        return Err(SessionStoreError::Quarantined);
    }
    Ok(())
}

fn session_record_name(session_id: [u8; 32], revision: u64) -> String {
    format!("{}-{revision:020}.session", hex_lower(&session_id))
}

fn parse_session_record_name(name: &str) -> Option<(String, u64)> {
    let body = name.strip_suffix(".session")?;
    if body.len() != 85 || body.as_bytes().get(64) != Some(&b'-') {
        return None;
    }
    let session = &body[..64];
    let revision = &body[65..];
    if decode_hex_32(session).is_none() || !revision.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    Some((session.to_owned(), revision.parse().ok()?))
}

