fn parse_outbound_dsc1_name(name: &str) -> Option<([u8; 32], [u8; 32], u64, bool)> {
    let (body, committed) = if let Some(body) = name.strip_suffix(".outbound-dsc1-request") {
        (body, false)
    } else {
        (name.strip_suffix(".outbound-dsc1-committed")?, true)
    };
    if body.len() != 150
        || body.as_bytes().get(64) != Some(&b'-')
        || body.as_bytes().get(129) != Some(&b'-')
    {
        return None;
    }
    Some((
        decode_hex_32(&body[..64])?,
        decode_hex_32(&body[65..129])?,
        body[130..].parse().ok()?,
        committed,
    ))
}

fn parse_outbound_dsc1_reconciled_name(name: &str) -> Option<([u8; 32], [u8; 32], u64)> {
    let body = name.strip_suffix(".outbound-dsc1-reconciled")?;
    if body.len() != 150
        || body.as_bytes().get(64) != Some(&b'-')
        || body.as_bytes().get(129) != Some(&b'-')
    {
        return None;
    }
    Some((
        decode_hex_32(&body[..64])?,
        decode_hex_32(&body[65..129])?,
        body[130..].parse().ok()?,
    ))
}

