    #[allow(clippy::too_many_arguments)]
    pub(super) fn transport_signed_bytes(
        key: &SecretKey,
        chain_id: [u8; 32],
        session_id: [u8; 32],
        sender_id: [u8; 32],
        sequence: u64,
        previous_transcript_hash: [u8; 32],
        message_type: u8,
        payload: &[u8],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let payload_len = u32::try_from(payload.len())?;
        let mut unsigned = vec![0; 148 + payload.len()];
        unsigned[..4].copy_from_slice(b"DSC1");
        unsigned[4..6].copy_from_slice(&1_u16.to_le_bytes());
        unsigned[6] = message_type;
        unsigned[8..40].copy_from_slice(&chain_id);
        unsigned[40..72].copy_from_slice(&session_id);
        unsigned[72..104].copy_from_slice(&sender_id);
        unsigned[104..112].copy_from_slice(&sequence.to_le_bytes());
        unsigned[112..144].copy_from_slice(&previous_transcript_hash);
        unsigned[144..148].copy_from_slice(&payload_len.to_le_bytes());
        unsigned[148..].copy_from_slice(payload);
        let digest = tagged_hash(TRANSPORT_MESSAGE_DIGEST_TAG, &unsigned);
        let signature = schnorr_sign(key, &digest, &chain_id)?;
        unsigned.extend_from_slice(&signature.to_bytes());
        Ok(unsigned)
    }

    pub(super) struct EarlyTransportTestFixture {
        pub(super) trusted_chain_id: TrustedChainIdV1,
        pub(super) recovery_capsule: RecoveryCapsule,
        pub(super) identity_keys: [SecretKey; 2],
        pub(super) participant_ids: [[u8; 32]; 2],
        pub(super) directions: [DirectionV1; 2],
        pub(super) signing_shares: [SigningShareV1; 2],
        pub(super) signing_share_bytes: [[u8; 32]; 2],
        pub(super) shared_bindings: [SharedBlindingBindingV1; 2],
    }

    impl EarlyTransportTestFixture {
        pub(super) fn new_signing_compatible(
            initial: &SessionRecordV1,
            initiator_sorts_first: bool,
        ) -> Result<Self, Box<dyn Error>> {
            let trusted_chain_id = TrustedChainIdV1::from_authenticated_genesis(
                0x4455_6677,
                &Hash256::from_bytes([0x91; 32]),
            );
            let mut identity_keys = [
                SecretKey::from_bytes(&[0x11; 32])?,
                SecretKey::from_bytes(&[0x12; 32])?,
            ];
            let mut share_a = [0; 32];
            share_a[31] = 7;
            let mut share_b = [0; 32];
            share_b[31] = 9;
            let mut signing_share_bytes = [share_a, share_b];
            let mut signing_shares = [
                SigningShareV1::from_be_bytes(share_a)?,
                SigningShareV1::from_be_bytes(share_b)?,
            ];
            let first_id = ParticipantIdentityV1::new(
                &trusted_chain_id,
                identity_keys[0].public_key(),
                signing_shares[0].public_key().clone(),
                DirectionV1::Initiator,
            )?;
            let second_id = ParticipantIdentityV1::new(
                &trusted_chain_id,
                identity_keys[1].public_key(),
                signing_shares[1].public_key().clone(),
                DirectionV1::Responder,
            )?;
            if first_id.participant_id() > second_id.participant_id() {
                identity_keys.swap(0, 1);
                signing_shares.swap(0, 1);
                signing_share_bytes.swap(0, 1);
            }
            let directions = if initiator_sorts_first {
                [DirectionV1::Initiator, DirectionV1::Responder]
            } else {
                [DirectionV1::Responder, DirectionV1::Initiator]
            };
            let participants = [
                ParticipantIdentityV1::new(
                    &trusted_chain_id,
                    identity_keys[0].public_key(),
                    signing_shares[0].public_key().clone(),
                    directions[0],
                )?,
                ParticipantIdentityV1::new(
                    &trusted_chain_id,
                    identity_keys[1].public_key(),
                    signing_shares[1].public_key().clone(),
                    directions[1],
                )?,
            ];
            let participant_ids = [
                *participants[0].participant_id(),
                *participants[1].participant_id(),
            ];
            let mut capsule_bytes = [0; 96];
            capsule_bytes[..2].copy_from_slice(&1_u16.to_le_bytes());
            capsule_bytes[14..16].copy_from_slice(&80_u16.to_le_bytes());
            let recovery_capsule = RecoveryCapsule::from_bytes(&capsule_bytes)?;
            let pending_a = PendingSharedBlindingBindingV1::new(
                &trusted_chain_id,
                initial.session_id(),
                &participant_ids,
                directions[0],
                0,
                initial.terms_hash(),
                signing_shares[0].public_key().clone(),
            )?;
            let pending_b = PendingSharedBlindingBindingV1::new(
                &trusted_chain_id,
                initial.session_id(),
                &participant_ids,
                directions[1],
                1,
                initial.terms_hash(),
                signing_shares[1].public_key().clone(),
            )?;
            let shared_bindings = [
                SharedBlindingBindingV1::bind_recovery_capsule(&pending_a, &recovery_capsule),
                SharedBlindingBindingV1::bind_recovery_capsule(&pending_b, &recovery_capsule),
            ];
            Ok(Self {
                trusted_chain_id,
                recovery_capsule,
                identity_keys,
                participant_ids,
                directions,
                signing_shares,
                signing_share_bytes,
                shared_bindings,
            })
        }

        pub(super) fn identity_key(&self, index: usize) -> &SecretKey {
            &self.identity_keys[index]
        }

        pub(super) fn index_for_direction(
            &self,
            direction: DirectionV1,
        ) -> Result<usize, SessionStoreError> {
            self.directions
                .iter()
                .position(|candidate| *candidate == direction)
                .ok_or(SessionStoreError::Canonical)
        }

        pub(super) fn canonical_reveal(
            &self,
            initial: &SessionRecordV1,
            context_commitment: [u8; 32],
            index: usize,
        ) -> Result<EarlyShareRevealV1, Box<dyn Error>> {
            let statement = SharePoPStatementV1::new(
                &self.trusted_chain_id,
                initial.session_id(),
                &self.participant_ids,
                self.directions[index],
                u16::try_from(index)?,
                self.signing_shares[index].public_key().clone(),
                initial.terms_hash(),
                *self.shared_bindings[index].capsule_hash(),
            )?;
            let proof = prove_share_knowledge_v1(&statement, &self.signing_shares[index])?;
            Ok(EarlyShareRevealV1::new(
                context_commitment,
                statement,
                proof,
            )?)
        }
    }

    pub(super) struct EarlyTransportPayloads {
        pub(super) messages: [Vec<u8>; 6],
    }

    impl EarlyTransportPayloads {
        pub(super) fn new(
            initial: &SessionRecordV1,
            fixture: &EarlyTransportTestFixture,
            authority: &PreparedEarlyTransportAuthorityV1,
        ) -> Result<Self, Box<dyn Error>> {
            Self::from_context(initial, fixture, *authority.context_commitment())
        }

        pub(super) fn from_context(
            initial: &SessionRecordV1,
            fixture: &EarlyTransportTestFixture,
            context_commitment: [u8; 32],
        ) -> Result<Self, Box<dyn Error>> {
            let reveals = [
                fixture.canonical_reveal(initial, context_commitment, 0)?,
                fixture.canonical_reveal(initial, context_commitment, 1)?,
            ];
            let commitments = [
                EarlyShareCommitmentV1::new(&reveals[0]),
                EarlyShareCommitmentV1::new(&reveals[1]),
            ];
            let initiator = fixture.index_for_direction(DirectionV1::Initiator)?;
            let responder = fixture.index_for_direction(DirectionV1::Responder)?;
            Ok(Self {
                messages: [
                    EarlyTermsBindingV1::new(EarlyTermsMessageKindV1::Offer, context_commitment)?
                        .to_bytes()
                        .to_vec(),
                    EarlyTermsBindingV1::new(EarlyTermsMessageKindV1::Accept, context_commitment)?
                        .to_bytes()
                        .to_vec(),
                    commitments[initiator].to_bytes().to_vec(),
                    commitments[responder].to_bytes().to_vec(),
                    reveals[initiator].to_bytes().to_vec(),
                    reveals[responder].to_bytes().to_vec(),
                ],
            })
        }

        pub(super) fn message(&self, position: usize) -> &[u8] {
            &self.messages[position]
        }
    }

    pub(super) struct PreparedOperationalBpPayloads {
        pub(super) statement: BpStatementV1,
        pub(super) messages: Vec<Vec<u8>>,
    }

    impl PreparedOperationalBpPayloads {
        pub(super) fn new(
            initial: &SessionRecordV1,
            fixture: &EarlyTransportTestFixture,
        ) -> Result<Self, Box<dyn Error>> {
            let commitment_shares = fixture
                .signing_shares
                .iter()
                .map(|share| share.public_key().clone())
                .collect::<Vec<_>>();
            let aggregate_commitment =
                BpStatementV1::aggregate_commitment_from_shares(&commitment_shares, 42)?;
            let statement = BpStatementV1::new(
                &fixture.trusted_chain_id,
                initial.session_id(),
                fixture.participant_ids.to_vec(),
                42,
                commitment_shares,
                aggregate_commitment,
                Some(*blake2b_256(fixture.recovery_capsule.as_bytes()).as_bytes()),
            )?;
            let driver_a = DomCollaborativeRangeProofV1::new(
                &statement,
                fixture.recovery_capsule.as_bytes().to_vec(),
            )?;
            let driver_b = DomCollaborativeRangeProofV1::new(
                &statement,
                fixture.recovery_capsule.as_bytes().to_vec(),
            )?;
            let (pending_a, common_commit_a) =
                PendingCommonNonce::new(&statement, 0, &fixture.signing_shares[0])?;
            let (pending_b, common_commit_b) =
                PendingCommonNonce::new(&statement, 1, &fixture.signing_shares[1])?;
            let common_reveal_a = pending_a.reveal_bytes();
            let common_reveal_b = pending_b.reveal_bytes();
            let accepted_common = [common_commit_a, common_commit_b];
            let local_a = pending_a.finish(
                &statement,
                &accepted_common,
                vec![common_reveal_a.clone(), common_reveal_b.clone()],
            )?;
            let local_b = pending_b.finish(
                &statement,
                &accepted_common,
                vec![common_reveal_a.clone(), common_reveal_b.clone()],
            )?;
            let round1_a = driver_a.round1(&statement, &local_a)?;
            let round1_b = driver_b.round1(&statement, &local_b)?;
            let round1_commit_a = round1_a.reveal_commitment();
            let round1_commit_b = round1_b.reveal_commitment();
            let aggregate_round1 = AggregateBpRound1::new(
                &statement,
                &[round1_commit_a, round1_commit_b],
                &[round1_a.clone(), round1_b.clone()],
            )?;
            let round2_a = driver_a
                .round2(&statement, &local_a, &aggregate_round1)?
                .into_zeroizing_bytes();
            let round2_b = driver_b
                .round2(&statement, &local_b, &aggregate_round1)?
                .into_zeroizing_bytes();
            let aggregate_round2 = AggregateBpRound2::new(
                &statement,
                vec![
                    BpRound2ShareV1::from_bytes(round2_a.as_ref(), &statement)?,
                    BpRound2ShareV1::from_bytes(round2_b.as_ref(), &statement)?,
                ],
            )?;
            let proof = driver_b.finalize(&statement, &aggregate_round1, &aggregate_round2)?;
            Ok(Self {
                statement,
                messages: vec![
                    common_commit_a.to_vec(),
                    common_commit_b.to_vec(),
                    common_reveal_a[..].to_vec(),
                    common_reveal_b[..].to_vec(),
                    round1_commit_a.to_vec(),
                    round1_commit_b.to_vec(),
                    round1_a.to_bytes().to_vec(),
                    round1_b.to_bytes().to_vec(),
                    round2_a[..].to_vec(),
                    round2_b[..].to_vec(),
                    proof.as_bytes().to_vec(),
                ],
            })
        }
    }

    pub(super) fn early_transport_position(
        position: usize,
    ) -> Result<(usize, u64, u8), SessionStoreError> {
        match position {
            0 => Ok((0, 0, 0x01)),
            1 => Ok((1, 0, 0x02)),
            2 => Ok((0, 1, 0x03)),
            3 => Ok((1, 1, 0x03)),
            4 => Ok((0, 2, 0x04)),
            5 => Ok((1, 2, 0x04)),
            _ => Err(SessionStoreError::Canonical),
        }
    }

    pub(super) fn sign_early_transport_position(
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let (role_index, sequence, message_type) = early_transport_position(position)?;
        let direction = if role_index == 0 {
            DirectionV1::Initiator
        } else {
            DirectionV1::Responder
        };
        let participant = fixture.index_for_direction(direction)?;
        transport_signed_bytes(
            fixture.identity_key(participant),
            *fixture.trusted_chain_id.as_bytes(),
            current.session_id(),
            fixture.participant_ids[participant],
            sequence,
            current.transcript_hash(),
            message_type,
            payload,
        )
    }

    pub(super) fn accept_early_transport_position(
        store: &ContractsSessionStoreV1,
        authority: &PreparedEarlyTransportAuthorityV1,
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<(SessionRecordV1, Vec<u8>), Box<dyn Error>> {
        let signed = sign_early_transport_position(fixture, current, position, payload)?;
        match store.accept_prepared_early_transport_message(authority, &signed)? {
            DurableTransportOutcomeV1::Accepted(receipt) if !receipt.duplicate => {}
            _ => return Err(Box::new(SessionStoreError::Quarantined)),
        }
        Ok((store.load_session(current.session_id())?, signed))
    }

    pub(super) fn complete_prepared_early_transport(
        store: &ContractsSessionStoreV1,
        initial: &SessionRecordV1,
        fixture: &EarlyTransportTestFixture,
    ) -> Result<SessionRecordV1, Box<dyn Error>> {
        let authority = store.prepare_early_transport_authority(
            fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        let payloads = EarlyTransportPayloads::new(initial, fixture, &authority)?;
        let mut current = initial.clone();
        for position in 0..6 {
            current = accept_early_transport_position(
                store,
                &authority,
                fixture,
                &current,
                position,
                payloads.message(position),
            )?
            .0;
        }
        Ok(current)
    }

    pub(super) fn prepared_bp_position(
        position: usize,
    ) -> Result<(usize, u64, u8), SessionStoreError> {
        if position < 10 {
            Ok((
                position % 2,
                3_u64
                    .checked_add(
                        u64::try_from(position / 2)
                            .map_err(|_| SessionStoreError::CapacityExceeded)?,
                    )
                    .ok_or(SessionStoreError::CapacityExceeded)?,
                0x05_u8
                    .checked_add(
                        u8::try_from(position / 2)
                            .map_err(|_| SessionStoreError::CapacityExceeded)?,
                    )
                    .ok_or(SessionStoreError::CapacityExceeded)?,
            ))
        } else if position == 10 {
            Ok((1, 8, 0x0a))
        } else {
            Err(SessionStoreError::InvalidTransition)
        }
    }

    pub(super) fn sign_prepared_bp_position(
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let (participant, sequence, message_type) = prepared_bp_position(position)?;
        transport_signed_bytes(
            fixture.identity_key(participant),
            *fixture.trusted_chain_id.as_bytes(),
            current.session_id(),
            fixture.participant_ids[participant],
            sequence,
            current.transcript_hash(),
            message_type,
            payload,
        )
    }

    pub(super) fn accept_prepared_bp_position(
        store: &ContractsSessionStoreV1,
        authority: &PreparedOperationalBpTransportAuthorityV1,
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<(SessionRecordV1, Vec<u8>), Box<dyn Error>> {
        let signed = sign_prepared_bp_position(fixture, current, position, payload)?;
        match store.accept_prepared_operational_bp_transport_message(authority, &signed)? {
            DurableTransportOutcomeV1::Accepted(receipt) if !receipt.duplicate => {}
            _ => return Err(Box::new(SessionStoreError::Quarantined)),
        }
        Ok((store.load_session(current.session_id())?, signed))
    }

    pub(super) fn complete_prepared_operational_bp_transport(
        store: &ContractsSessionStoreV1,
        initial: &SessionRecordV1,
        fixture: &EarlyTransportTestFixture,
    ) -> Result<(SessionRecordV1, PreparedOperationalBpPayloads), Box<dyn Error>> {
        let mut current = complete_prepared_early_transport(store, initial, fixture)?;
        let payloads = PreparedOperationalBpPayloads::new(initial, fixture)?;
        let authority = store.prepare_operational_bp_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &payloads.statement,
            &fixture.recovery_capsule,
        )?;
        for position in 0..11 {
            current = accept_prepared_bp_position(
                store,
                &authority,
                fixture,
                &current,
                position,
                &payloads.messages[position],
            )?
            .0;
        }
        Ok((current, payloads))
    }

    pub(super) fn sign_prepared_template_position(
        store: &ContractsSessionStoreV1,
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let direction = match position {
            0 => DirectionV1::Initiator,
            1 => DirectionV1::Responder,
            _ => return Err(Box::new(SessionStoreError::InvalidTransition)),
        };
        let participant = fixture.index_for_direction(direction)?;
        let participant_id = *fixture
            .participant_ids
            .get(participant)
            .ok_or(SessionStoreError::InvalidTransition)?;
        let sequence = store.transport_sequence_at_revision(
            current.session_id(),
            participant_id,
            current.revision(),
        )?;
        transport_signed_bytes(
            fixture.identity_key(participant),
            *fixture.trusted_chain_id.as_bytes(),
            current.session_id(),
            participant_id,
            sequence,
            current.transcript_hash(),
            0x0b,
            payload,
        )
    }

    pub(super) fn accept_prepared_template_position(
        store: &ContractsSessionStoreV1,
        authority: &PreparedOperationalTemplateTransportAuthorityV1,
        fixture: &EarlyTransportTestFixture,
        current: &SessionRecordV1,
        position: usize,
    ) -> Result<(SessionRecordV1, Vec<u8>), Box<dyn Error>> {
        let signed = sign_prepared_template_position(
            store,
            fixture,
            current,
            position,
            authority.template_commit_payload(),
        )?;
        match store.accept_prepared_operational_template_transport_message(authority, &signed)? {
            DurableTransportOutcomeV1::Accepted(receipt) if !receipt.duplicate => {}
            _ => return Err(Box::new(SessionStoreError::Quarantined)),
        }
        Ok((store.load_session(current.session_id())?, signed))
    }

    pub(super) fn signing_transport_roster(
        fixture: &EarlyTransportTestFixture,
    ) -> Result<ParticipantRosterV1, Box<dyn Error>> {
        let mut participants = vec![
            ParticipantIdentityV1::new(
                &fixture.trusted_chain_id,
                fixture.identity_keys[0].public_key(),
                fixture.signing_shares[0].public_key().clone(),
                fixture.directions[0],
            )?,
            ParticipantIdentityV1::new(
                &fixture.trusted_chain_id,
                fixture.identity_keys[1].public_key(),
                fixture.signing_shares[1].public_key().clone(),
                fixture.directions[1],
            )?,
        ];
        participants.sort_by_key(|participant| *participant.participant_id());
        Ok(ParticipantRosterV1::new(participants)?)
    }

    pub(super) struct PreparedSigningPayloads {
        pub(super) messages: Vec<Vec<u8>>,
        pub(super) plain_signature: Option<SchnorrSignature>,
    }

    impl PreparedSigningPayloads {
        pub(super) fn new(
            fixture: &EarlyTransportTestFixture,
            roster: &ParticipantRosterV1,
            transaction: &Transaction,
            session_id: [u8; 32],
            purpose: PurposeV1,
            adaptor_point: Option<&PublicKey>,
            nonce_seed_base: u8,
        ) -> Result<Self, Box<dyn Error>> {
            match (purpose, adaptor_point) {
                (PurposeV1::ClaimAdaptor, Some(_))
                | (PurposeV1::Funding | PurposeV1::Refund, None) => {}
                _ => return Err(Box::new(SessionStoreError::Canonical)),
            }
            let (_, template_hash) = canonical_template_v1(transaction)?;
            let nonce_scalar = |offset: u8| -> Result<[u8; 32], SessionStoreError> {
                let byte = nonce_seed_base
                    .checked_add(offset)
                    .filter(|value| *value != 0)
                    .ok_or(SessionStoreError::Canonical)?;
                let mut value = [0; 32];
                value[31] = byte;
                Ok(value)
            };
            let nonce_scalars = [
                [nonce_scalar(0)?, nonce_scalar(1)?],
                [nonce_scalar(2)?, nonce_scalar(3)?],
            ];
            let mut commitments = Vec::with_capacity(2);
            let mut reveals = Vec::with_capacity(2);
            let mut public_nonces = Vec::with_capacity(2);
            for (protocol_index, nonce_pair) in nonce_scalars.iter().enumerate() {
                let participant = &roster.entries()[protocol_index];
                let signing_index = roster.signing_index(participant.participant_id())?;
                let first = secret_scalar_public_key(&nonce_pair[0])?;
                let second = secret_scalar_public_key(&nonce_pair[1])?;
                let commitment = nonce_commitment_hash_v1(
                    fixture.trusted_chain_id.as_bytes(),
                    &session_id,
                    participant.participant_id(),
                    purpose,
                    &template_hash,
                    &first,
                    &second,
                    adaptor_point,
                )?;
                commitments.push(
                    NonceCommitmentV1::new(purpose, signing_index, *commitment.as_bytes())
                        .to_bytes()
                        .to_vec(),
                );
                reveals.push(
                    NonceRevealV1::new(purpose, signing_index, first.clone(), second.clone())
                        .to_bytes()
                        .to_vec(),
                );
                public_nonces.push(ParticipantPublicNoncesV1 {
                    participant_index: signing_index,
                    signing_key: participant.signing_public_key().clone(),
                    first_nonce: first,
                    second_nonce: second,
                });
            }
            public_nonces.sort_by_key(|entry| entry.participant_index);
            let binding = binding_factor_v1(
                &BindingContextV1 {
                    chain_id: *fixture.trusted_chain_id.as_bytes(),
                    session_id,
                    purpose,
                    template_hash,
                },
                &public_nonces,
                adaptor_point,
            )?;
            let effective_nonces: Vec<PublicKey> = public_nonces
                .iter()
                .map(|entry| binding.bind_public_nonces(&entry.first_nonce, &entry.second_nonce))
                .collect::<Result<_, _>>()?;
            let aggregate_nonce = aggregate_public_nonces_v1(&effective_nonces)?;
            let aggregate_nonce_hat = match adaptor_point {
                Some(point) => {
                    aggregate_public_nonces_v1(&[aggregate_nonce.clone(), point.clone()])?
                }
                None => aggregate_nonce.clone(),
            };
            let mut signing_keys: Vec<PublicKey> = roster
                .entries()
                .iter()
                .map(|participant| participant.signing_public_key().clone())
                .collect();
            signing_keys.sort_by_key(PublicKey::to_compressed_bytes);
            let aggregate_signing_key = aggregate_public_nonces_v1(&signing_keys)?;
            let kernel = transaction
                .kernels
                .first()
                .ok_or(SessionStoreError::InvalidDomTransaction)?;
            let kernel_message = scriptless_kernel_message_digest_v1(kernel);
            let challenge = schnorr_challenge(
                &aggregate_nonce_hat.to_compressed_bytes(),
                &aggregate_signing_key,
                fixture.trusted_chain_id.as_bytes(),
                kernel_message.as_bytes(),
            );
            let binding_bytes = binding.to_be_bytes();
            let mut partials = Vec::with_capacity(2);
            let mut typed_partials = Vec::with_capacity(2);
            for (protocol_index, nonce_pair) in nonce_scalars.iter().enumerate() {
                let participant = &roster.entries()[protocol_index];
                let fixture_index = fixture
                    .participant_ids
                    .iter()
                    .position(|candidate| candidate == participant.participant_id())
                    .ok_or(SessionStoreError::Canonical)?;
                let signing_index = roster.signing_index(participant.participant_id())?;
                let mut partial = Zeroizing::new(nonce_pair[0]);
                secret_scalar_mul_add_assign(&mut partial, &nonce_pair[1], &binding_bytes)?;
                secret_scalar_mul_add_assign(
                    &mut partial,
                    &fixture.signing_share_bytes[fixture_index],
                    challenge.as_bytes(),
                )?;
                let typed = PartialSignatureV1::new(
                    purpose,
                    signing_index,
                    template_hash,
                    PartialSig::from_bytes(partial.as_ref())?,
                );
                partials.push(typed.to_bytes().to_vec());
                typed_partials.push(typed);
            }
            let plain_signature = match purpose {
                PurposeV1::Funding | PurposeV1::Refund => Some(finalize_plain_signature_v1(
                    &typed_partials,
                    purpose,
                    &template_hash,
                    &aggregate_nonce,
                    &aggregate_signing_key,
                    fixture.trusted_chain_id.as_bytes(),
                    kernel_message.as_bytes(),
                )?),
                PurposeV1::ClaimAdaptor => None,
                PurposeV1::Sponsor => return Err(Box::new(SessionStoreError::Canonical)),
            };
            let mut messages = Vec::with_capacity(6);
            messages.extend(commitments);
            messages.extend(reveals);
            messages.extend(partials);
            Ok(Self {
                messages,
                plain_signature,
            })
        }
    }

    pub(super) fn sign_prepared_signing_position(
        store: &ContractsSessionStoreV1,
        fixture: &EarlyTransportTestFixture,
        roster: &ParticipantRosterV1,
        round_start_revision: u64,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let protocol_index = position % 2;
        let stage_index = position / 2;
        let participant_id = *roster
            .entries()
            .get(protocol_index)
            .ok_or(SessionStoreError::Canonical)?
            .participant_id();
        let fixture_index = fixture
            .participant_ids
            .iter()
            .position(|candidate| candidate == &participant_id)
            .ok_or(SessionStoreError::Canonical)?;
        let sequence = store
            .transport_sequence_at_revision(
                current.session_id(),
                participant_id,
                round_start_revision,
            )?
            .checked_add(u64::try_from(stage_index)?)
            .ok_or(SessionStoreError::CapacityExceeded)?;
        transport_signed_bytes(
            fixture.identity_key(fixture_index),
            *fixture.trusted_chain_id.as_bytes(),
            current.session_id(),
            participant_id,
            sequence,
            current.transcript_hash(),
            0x0c_u8
                .checked_add(u8::try_from(stage_index)?)
                .ok_or(SessionStoreError::CapacityExceeded)?,
            payload,
        )
    }

    pub(super) fn accept_prepared_signing_position(
        store: &ContractsSessionStoreV1,
        authority: &PreparedOperationalSigningTransportAuthorityV1,
        fixture: &EarlyTransportTestFixture,
        roster: &ParticipantRosterV1,
        current: &SessionRecordV1,
        position: usize,
        payload: &[u8],
    ) -> Result<(SessionRecordV1, Vec<u8>), Box<dyn Error>> {
        let signed = sign_prepared_signing_position(
            store,
            fixture,
            roster,
            authority.round_start_revision,
            current,
            position,
            payload,
        )?;
        let outcome = store
            .accept_prepared_operational_signing_transport_message(authority, &signed)
            .map_err(|error| {
                std::io::Error::other(format!(
                    "prepared signing position {position} failed: {error}"
                ))
            })?;
        match outcome {
            DurableTransportOutcomeV1::Accepted(receipt) if !receipt.duplicate => {}
            _ => return Err(Box::new(SessionStoreError::Quarantined)),
        }
        Ok((store.load_session(current.session_id())?, signed))
    }

    pub(super) struct CryptoRealM8Templates {
        pub(super) funding: ScriptlessTransactionTemplateV1,
        pub(super) claim: ScriptlessTransactionTemplateV1,
        pub(super) refund: ScriptlessTransactionTemplateV1,
    }

    pub(super) fn crypto_real_m8_templates(
        initial: &SessionRecordV1,
        fixture: &EarlyTransportTestFixture,
        bp: &PreparedOperationalBpPayloads,
    ) -> Result<CryptoRealM8Templates, Box<dyn Error>> {
        let contributions = (0..2)
            .map(|index| -> Result<_, Box<dyn Error>> {
                Ok(contribute_blinding_share_v1(
                    &fixture.trusted_chain_id,
                    initial.session_id(),
                    &fixture.participant_ids,
                    fixture.directions[index],
                    u16::try_from(index)?,
                    &fixture.signing_shares[index],
                    initial.terms_hash(),
                    *bp.statement.recovery_binding_hash(),
                )?)
            })
            .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
        let shared = aggregate_shared_commitment_v1(
            &fixture.trusted_chain_id,
            initial.session_id(),
            &fixture.participant_ids,
            42,
            initial.terms_hash(),
            *bp.statement.recovery_binding_hash(),
            &contributions,
        )?;
        if shared.commitment_bytes() != &bp.statement.aggregate_commitment().to_compressed_bytes() {
            return Err(Box::new(SessionStoreError::Canonical));
        }
        let proof = RangeProof739::try_from(
            bp.messages
                .get(10)
                .ok_or(SessionStoreError::Canonical)?
                .as_slice(),
        )?;
        let shared_output = VerifiedSharedOutputV1::from_collaborative_proof_and_capsule(
            &shared,
            proof,
            Some(&fixture.recovery_capsule),
        )?;

        let aggregate_blinding = scalar(16)?;
        let unsigned_kernel = |features: u8,
                               fee: u64,
                               lock_height: u64|
         -> Result<TransactionKernel, Box<dyn Error>> {
            Ok(TransactionKernel {
                features,
                fee: Amount::from_noms(fee)?,
                lock_height,
                excess: Commitment::commit(0, &aggregate_blinding),
                excess_signature: [0; 65],
            })
        };
        let funding_input_blinding = scalar(5)?;
        let change_blinding = scalar(5)?;
        let (change_proof, _) = dom_crypto::bp2_prove(7, &change_blinding)?;
        let payout_blinding = scalar(32)?;
        let (payout_proof, _) = dom_crypto::bp2_prove(40, &payout_blinding)?;
        let funding = ScriptlessTransactionTemplateV1::funding(
            &shared_output,
            vec![TransactionInput {
                commitment: Commitment::commit(50, &funding_input_blinding),
            }],
            vec![TransactionOutput {
                commitment: Commitment::commit(7, &change_blinding),
                proof: change_proof,
            }],
            0,
            unsigned_kernel(KERNEL_FEAT_PLAIN, 1, 0)?,
            [0; 32],
        )?;
        let payout = TransactionOutput {
            commitment: Commitment::commit(40, &payout_blinding),
            proof: payout_proof,
        };
        let claim = ScriptlessTransactionTemplateV1::claim(
            &shared_output,
            vec![payout.clone()],
            unsigned_kernel(KERNEL_FEAT_PLAIN, 2, 0)?,
            [0; 32],
        )?;
        let refund = ScriptlessTransactionTemplateV1::refund(
            &shared_output,
            vec![payout],
            unsigned_kernel(KERNEL_FEAT_HEIGHT_LOCKED, 2, 500)?,
            [0; 32],
            100,
        )?;
        Ok(CryptoRealM8Templates {
            funding,
            claim,
            refund,
        })
    }

