    #[derive(Debug)]
    struct TestSharedBlindingVaultError;

    impl fmt::Display for TestSharedBlindingVaultError {
        fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            formatter.write_str("test shared-blinding vault failure")
        }
    }

    impl Error for TestSharedBlindingVaultError {}

    #[derive(Default)]
    struct TestSharedBlindingVault {
        plaintext: Option<[u8; 32]>,
        pending: Option<PendingSharedBlindingBindingV1>,
        bound: Option<SharedBlindingBindingV1>,
    }

    impl SharedBlindingVaultV1 for TestSharedBlindingVault {
        type Error = TestSharedBlindingVaultError;

        fn seal_fresh_share(
            &mut self,
            binding: &PendingSharedBlindingBindingV1,
            material: SharedBlindingMaterialV1,
            capability: SharedBlindingSealCapabilityV1,
        ) -> Result<(), Self::Error> {
            if self.plaintext.is_some() {
                return Err(TestSharedBlindingVaultError);
            }
            self.plaintext = Some(*capability.into_plaintext(material));
            self.pending = Some(binding.clone());
            Ok(())
        }

        fn open_persisted_pending_share(
            &mut self,
            binding: &PendingSharedBlindingBindingV1,
            capability: SharedBlindingImportCapabilityV1,
        ) -> Result<SharedBlindingMaterialV1, Self::Error> {
            if self.pending.as_ref() != Some(binding) {
                return Err(TestSharedBlindingVaultError);
            }
            capability
                .import(Zeroizing::new(
                    self.plaintext.ok_or(TestSharedBlindingVaultError)?,
                ))
                .map_err(|_| TestSharedBlindingVaultError)
        }

        fn confirm_pending_backup_roundtrip(
            &mut self,
            binding: &PendingSharedBlindingBindingV1,
            capability: DurableShareBackupAckCapabilityV1,
        ) -> Result<ShareBackupAckV1, Self::Error> {
            capability
                .acknowledge_pending(binding, binding.share_point().clone())
                .map_err(|_| TestSharedBlindingVaultError)
        }

        fn bind_recovery_capsule(
            &mut self,
            pending: &PendingSharedBlindingBindingV1,
            bound: &SharedBlindingBindingV1,
            capability: SharedBlindingBindingUpgradeCapabilityV1,
        ) -> Result<(), Self::Error> {
            capability
                .authorize_upgrade(pending, bound)
                .map_err(|_| TestSharedBlindingVaultError)?;
            if self.pending.as_ref() != Some(pending) || self.bound.is_some() {
                return Err(TestSharedBlindingVaultError);
            }
            self.bound = Some(bound.clone());
            self.pending = None;
            Ok(())
        }

        fn open_persisted_share(
            &mut self,
            binding: &SharedBlindingBindingV1,
            capability: SharedBlindingImportCapabilityV1,
        ) -> Result<SharedBlindingMaterialV1, Self::Error> {
            if self.bound.as_ref() != Some(binding) {
                return Err(TestSharedBlindingVaultError);
            }
            capability
                .import(Zeroizing::new(
                    self.plaintext.ok_or(TestSharedBlindingVaultError)?,
                ))
                .map_err(|_| TestSharedBlindingVaultError)
        }

        fn confirm_backup_roundtrip(
            &mut self,
            binding: &SharedBlindingBindingV1,
            capability: DurableShareBackupAckCapabilityV1,
        ) -> Result<ShareBackupAckV1, Self::Error> {
            capability
                .acknowledge(binding, binding.share_point().clone())
                .map_err(|_| TestSharedBlindingVaultError)
        }

        fn retire_pending_share(
            &mut self,
            _binding: &PendingSharedBlindingBindingV1,
            _capability: SharedBlindingRetirementCapabilityV1,
        ) -> Result<(), Self::Error> {
            Err(TestSharedBlindingVaultError)
        }

        fn retire_bound_share(
            &mut self,
            _binding: &SharedBlindingBindingV1,
            _capability: SharedBlindingRetirementCapabilityV1,
        ) -> Result<(), Self::Error> {
            Err(TestSharedBlindingVaultError)
        }
    }

    #[derive(Debug, Eq, PartialEq)]
    enum StoreTreeNodeKind {
        Directory,
        File(Vec<u8>),
        Symlink(PathBuf),
    }

    #[derive(Debug, Eq, PartialEq)]
    struct StoreTreeNodeSnapshot {
        mode: u32,
        kind: StoreTreeNodeKind,
    }

    fn snapshot_store_tree(
        root: &Path,
    ) -> Result<BTreeMap<PathBuf, StoreTreeNodeSnapshot>, Box<dyn Error>> {
        fn visit(
            root: &Path,
            path: &Path,
            snapshot: &mut BTreeMap<PathBuf, StoreTreeNodeSnapshot>,
        ) -> Result<(), Box<dyn Error>> {
            let metadata = fs::symlink_metadata(path)?;
            let relative = path.strip_prefix(root)?.to_path_buf();
            let mode = metadata.permissions().mode();
            let file_type = metadata.file_type();
            if file_type.is_dir() {
                snapshot.insert(
                    relative,
                    StoreTreeNodeSnapshot {
                        mode,
                        kind: StoreTreeNodeKind::Directory,
                    },
                );
                let mut children = fs::read_dir(path)?
                    .map(|entry| entry.map(|entry| entry.path()))
                    .collect::<Result<Vec<_>, _>>()?;
                children.sort();
                for child in children {
                    visit(root, &child, snapshot)?;
                }
            } else if file_type.is_file() {
                snapshot.insert(
                    relative,
                    StoreTreeNodeSnapshot {
                        mode,
                        kind: StoreTreeNodeKind::File(fs::read(path)?),
                    },
                );
            } else if file_type.is_symlink() {
                snapshot.insert(
                    relative,
                    StoreTreeNodeSnapshot {
                        mode,
                        kind: StoreTreeNodeKind::Symlink(fs::read_link(path)?),
                    },
                );
            } else {
                return Err(Box::new(SessionStoreError::Filesystem));
            }
            Ok(())
        }

        let mut snapshot = BTreeMap::new();
        visit(root, root, &mut snapshot)?;
        Ok(snapshot)
    }

    fn write_store_test_file(
        temporary: &TestDirectory,
        store_name: &str,
        directory_name: &str,
        file_name: &str,
        exact_bytes: &[u8],
    ) -> Result<PathBuf, Box<dyn Error>> {
        let path = temporary
            .path()
            .join(store_name)
            .join(directory_name)
            .join(file_name);
        fs::write(&path, exact_bytes)?;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;
        Ok(path)
    }

    fn profile_test_bytes(magic: &[u8; 8], suffix: &[u8]) -> Vec<u8> {
        let mut bytes = magic.to_vec();
        bytes.extend_from_slice(suffix);
        bytes
    }

    fn rechecksum_test_record(bytes: &mut [u8], domain: &str) -> Result<(), SessionStoreError> {
        let digest_start = bytes
            .len()
            .checked_sub(DIGEST_LEN)
            .ok_or(SessionStoreError::Canonical)?;
        let digest = tagged_hash(domain, &bytes[..digest_start]);
        bytes[digest_start..].copy_from_slice(&digest);
        Ok(())
    }

    fn assert_quarantined<T>(result: Result<T, SessionStoreError>) {
        assert!(matches!(result, Err(SessionStoreError::Quarantined)));
    }

