    /// Pins this crate's payload ceilings against the closed Master 8.3
    /// registry that `dom-scriptless-transport` publishes.
    ///
    /// The expected column is transcribed from `MessageTypeV1::payload_cap`,
    /// not from the table under test, so the two are compared rather than
    /// echoed. It is the check that did not exist when `0x13` drifted to four
    /// kibibytes against the registry's thirty-two, and it is deliberately a
    /// transcription: this crate has no dependency on that one, so no compiler
    /// or guard can do the comparison, and only a person updating both columns
    /// can. If a type's ceiling changes there, this fails here.
    #[test]
    fn transport_payload_caps_match_the_closed_message_registry() {
        // (type, cap in dom-scriptless-transport::MessageTypeV1::payload_cap)
        let registry: [(u8, usize); 20] = [
            (0x01, 8 * 1024),   // Offer
            (0x02, 8 * 1024),   // Accept
            (0x03, 4 * 1024),   // ShareCommit
            (0x04, 8 * 1024),   // ShareReveal
            (0x05, 4 * 1024),   // BpCommonCommit
            (0x06, 4 * 1024),   // BpCommonReveal
            (0x07, 4 * 1024),   // BpRoundCommit
            (0x08, 8 * 1024),   // BpRound1
            (0x09, 8 * 1024),   // BpRound2
            (0x0a, 16 * 1024),  // BpFinal
            (0x0b, 8 * 1024),   // TxTemplateCommit
            (0x0c, 4 * 1024),   // SigNonceCommit
            (0x0d, 8 * 1024),   // SigNonceReveal
            (0x0e, 8 * 1024),   // PartialSignature
            (0x0f, 8 * 1024),   // AdaptorPreSignature
            (0x10, 512 * 1024), // FinalRefund
            (0x11, 4 * 1024),   // ReadyToFund
            (0x12, 512 * 1024), // FinalClaim
            (0x13, 32),         // Abort == ABORT_PAYLOAD_LEN_V1
            (0x14, 4 * 1024),   // Ack
        ];
        for (message_type, expected) in registry {
            assert_eq!(
                transport_payload_cap(message_type),
                Some(expected),
                "payload cap for message type {message_type:#04x} left the registry"
            );
        }
        // The registry is closed at twenty types, and so is this table.
        for message_type in [0x00_u8, 0x15, 0x7f, 0xff] {
            assert_eq!(transport_payload_cap(message_type), None);
        }
        // The abort ceiling and the exact-length rule the acceptance paths
        // impose are now the same number, which is the whole point of closing
        // the divergence: the outer barrier stopped being looser than the
        // inner one.
        assert_eq!(
            transport_payload_cap(0x13),
            Some(OPERATIONAL_ABORT_PAYLOAD_LEN)
        );
    }

