    /// The seven artifacts that exist in both profiles, i.e. the frozen M.8/F7
    /// chain gate -> issuance -> commit -> issued -> consumed -> binding ->
    /// pre-signature.
    const M8_F7_PROFILE_CHAIN_ARTIFACTS: [M8F7DurableArtifact; 7] = [
        M8F7DurableArtifact::FundingGate,
        M8F7DurableArtifact::FundingIssuance,
        M8F7DurableArtifact::FundingCommit,
        M8F7DurableArtifact::ClaimSigningIssued,
        M8F7DurableArtifact::ClaimSigningConsumed,
        M8F7DurableArtifact::ClaimSigningBinding,
        M8F7DurableArtifact::ClaimPreSignature,
    ];

    fn m8_f7_descriptor_for(
        profile: M8F7DurableProfileVersion,
        artifact: M8F7DurableArtifact,
    ) -> Result<M8F7DurableProfileDescriptor, SessionStoreError> {
        M8_F7_DURABLE_PROFILE_DESCRIPTORS
            .iter()
            .copied()
            .find(|descriptor| descriptor.profile == profile && descriptor.artifact == artifact)
            .ok_or(SessionStoreError::Quarantined)
    }

    const fn m8_f7_directory_name(directory: M8F7DurableDirectory) -> &'static str {
        match directory {
            M8F7DurableDirectory::Records => RECORDS_NAME,
            M8F7DurableDirectory::Artifacts => ARTIFACTS_NAME,
            M8F7DurableDirectory::Consumptions => CONSUMPTIONS_NAME,
            M8F7DurableDirectory::Rosters => ROSTERS_NAME,
            M8F7DurableDirectory::Messages => MESSAGES_NAME,
            M8F7DurableDirectory::ReservationLookups => RESERVATION_LOOKUPS_NAME,
        }
    }

    #[test]
    fn m8_f7_profile_choice_covers_only_the_artifacts_present_in_both_profiles() {
        for artifact in M8_F7_PROFILE_CHAIN_ARTIFACTS {
            assert!(
                m8_f7_artifact_selects_profile(artifact),
                "{artifact:?} belongs to the profile chain"
            );
        }
        for artifact in [
            M8F7DurableArtifact::BackupProvenance,
            M8F7DurableArtifact::FinalRefund,
        ] {
            assert!(
                !m8_f7_artifact_selects_profile(artifact),
                "{artifact:?} is a V2-only encoding, never a profile marker"
            );
        }
    }

    #[test]
    fn m8_f7_census_rejects_v1_and_v2_coexistence_for_every_chain_artifact_without_mutation(
    ) -> Result<(), Box<dyn Error>> {
        for artifact in M8_F7_PROFILE_CHAIN_ARTIFACTS {
            let temporary = TestDirectory::create()?;
            let store_name = "m8-f7-chain-coexistence";
            create_closed_test_store(&temporary, store_name)?;
            let legacy = m8_f7_descriptor_for(M8F7DurableProfileVersion::LegacyV1, artifact)?;
            let productive = m8_f7_descriptor_for(M8F7DurableProfileVersion::V2, artifact)?;
            let session_hex = hex_lower(&[0x7c; 32]);
            let legacy_name = format!("{session_hex}{}", legacy.suffix);
            let productive_name = format!("{session_hex}{}", productive.suffix);
            let legacy_bytes = profile_test_bytes(legacy.magic, b"v1-final");
            let productive_bytes = profile_test_bytes(productive.magic, b"v2-final");
            let legacy_path = write_store_test_file(
                &temporary,
                store_name,
                m8_f7_directory_name(legacy.directory),
                &legacy_name,
                &legacy_bytes,
            )?;
            let productive_path = write_store_test_file(
                &temporary,
                store_name,
                m8_f7_directory_name(productive.directory),
                &productive_name,
                &productive_bytes,
            )?;
            let durable_root = temporary.path().join(store_name);
            let before = snapshot_store_tree(&durable_root)?;

            assert_eq!(
                ContractsSessionStoreV1::open_evidence_only(
                    temporary.capability()?,
                    store_name,
                    policy(BudgetPolicyProfileV1::EvidenceOnly)?,
                )
                .err(),
                Some(SessionStoreError::Quarantined),
                "{artifact:?}"
            );
            assert_eq!(snapshot_store_tree(&durable_root)?, before, "{artifact:?}");
            assert_eq!(fs::read(legacy_path)?, legacy_bytes, "{artifact:?}");
            assert_eq!(fs::read(productive_path)?, productive_bytes, "{artifact:?}");
        }
        Ok(())
    }

