    #[test]
    fn consumed_claim_revalidation_is_restart_scoped_and_tamper_closed(
    ) -> Result<(), Box<dyn Error>> {
        let fixture = PostAnchorClaimPreSignatureTestFixture::new(4)?;
        let first_open = [0xd1; 32];
        let restarted_open = [0xd2; 32];

        let first = fixture
            .consumed
            .consumed_capability(&fixture.issued, first_open)?;
        require_consumed_claim_capability_bindings(
            &first,
            &fixture.issued,
            &fixture.consumed,
            first_open,
        )?;
        assert!(matches!(
            require_consumed_claim_capability_bindings(
                &first,
                &fixture.issued,
                &fixture.consumed,
                restarted_open,
            ),
            Err(SessionStoreError::ClaimSigningAuthorityUnavailable)
        ));

        let resumed = fixture
            .consumed
            .consumed_capability(&fixture.issued, restarted_open)?;
        require_consumed_claim_capability_bindings(
            &resumed,
            &fixture.issued,
            &fixture.consumed,
            restarted_open,
        )?;

        let mut wrong_template = fixture
            .consumed
            .consumed_capability(&fixture.issued, restarted_open)?;
        wrong_template.claim_template_hash[0] ^= 1;
        assert!(matches!(
            require_consumed_claim_capability_bindings(
                &wrong_template,
                &fixture.issued,
                &fixture.consumed,
                restarted_open,
            ),
            Err(SessionStoreError::ClaimSigningAuthorityUnavailable)
        ));

        let mut wrong_consumption = fixture
            .consumed
            .consumed_capability(&fixture.issued, restarted_open)?;
        wrong_consumption.consumption_record_digest[0] ^= 1;
        assert!(matches!(
            require_consumed_claim_capability_bindings(
                &wrong_consumption,
                &fixture.issued,
                &fixture.consumed,
                restarted_open,
            ),
            Err(SessionStoreError::ClaimSigningAuthorityUnavailable)
        ));

        let mut retained_tamper = fixture.consumed.bytes;
        retained_tamper[80] ^= 1;
        assert!(matches!(
            PostAnchorClaimAuthorizationRecordV1::from_bytes(&retained_tamper),
            Err(SessionStoreError::Quarantined)
        ));
        Ok(())
    }

    fn real_dom_transaction_bytes(
        features: u8,
        lock_height: u64,
        input_value: u64,
        output_value: u64,
        input_seed: u8,
        kernel_seed: u8,
        chain_id: &[u8; 32],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let input_blinding = scalar(input_seed)?;
        let kernel_blinding = scalar(kernel_seed)?;
        let output_blinding = input_blinding.add(&kernel_blinding)?;
        let fee = input_value
            .checked_sub(output_value)
            .ok_or(SessionStoreError::InvalidDomTransaction)?;
        let input_commitment = Commitment::commit(input_value, &input_blinding);
        let output_commitment = Commitment::commit(output_value, &output_blinding);
        let (proof, _) = dom_crypto::bp2_prove(output_value, &output_blinding)?;
        let excess = Commitment::commit(0, &kernel_blinding);
        let secret = SecretKey::from_bytes(kernel_blinding.as_bytes())?;
        let signature = schnorr_sign(
            &secret,
            &kernel_message(features, fee, lock_height),
            chain_id,
        )?;
        let transaction = Transaction {
            inputs: vec![TransactionInput {
                commitment: input_commitment,
            }],
            outputs: vec![TransactionOutput {
                commitment: output_commitment,
                proof,
            }],
            kernels: vec![TransactionKernel {
                features,
                fee: Amount::from_noms(fee)?,
                lock_height,
                excess,
                excess_signature: signature.to_bytes(),
            }],
            offset: [0; 32],
        };
        Ok(transaction.to_bytes()?)
    }

    struct DeterministicDomTransactionInputs {
        features: u8,
        lock_height: u64,
        input_value: u64,
        output_value: u64,
        input_seed: u8,
        kernel_seed: u8,
        proof_seed: u8,
    }

    fn deterministic_dom_transaction_bytes(
        inputs: DeterministicDomTransactionInputs,
        chain_id: &[u8; 32],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let DeterministicDomTransactionInputs {
            features,
            lock_height,
            input_value,
            output_value,
            input_seed,
            kernel_seed,
            proof_seed,
        } = inputs;
        let input_blinding = scalar(input_seed)?;
        let kernel_blinding = scalar(kernel_seed)?;
        let output_blinding = input_blinding.add(&kernel_blinding)?;
        let fee = input_value
            .checked_sub(output_value)
            .ok_or(SessionStoreError::InvalidDomTransaction)?;
        let input_commitment = Commitment::commit(input_value, &input_blinding);
        let output_commitment = Commitment::commit(output_value, &output_blinding);
        let (proof, _) =
            bp2_prove_with_nonce(output_value, &output_blinding, &[proof_seed.max(1); 32])?;
        let excess = Commitment::commit(0, &kernel_blinding);
        let secret = SecretKey::from_bytes(kernel_blinding.as_bytes())?;
        let signature = schnorr_sign(
            &secret,
            &kernel_message(features, fee, lock_height),
            chain_id,
        )?;
        Ok(Transaction {
            inputs: vec![TransactionInput {
                commitment: input_commitment,
            }],
            outputs: vec![TransactionOutput {
                commitment: output_commitment,
                proof,
            }],
            kernels: vec![TransactionKernel {
                features,
                fee: Amount::from_noms(fee)?,
                lock_height,
                excess,
                excess_signature: signature.to_bytes(),
            }],
            offset: [0; 32],
        }
        .to_bytes()?)
    }

