    fn m8_f7_v2_settlement_terms(
        trusted_chain: &TrustedChainIdV1,
        roster: &ParticipantRosterV1,
        adaptor_point: &PublicKey,
        session_id: [u8; 32],
    ) -> Result<(SettlementTermsV1, SettlementTermsV1), Box<dyn Error>> {
        if roster.entries().len() != 2 {
            return Err(Box::new(SessionStoreError::Canonical));
        }
        let sender = ParticipantId(*roster.entries()[0].participant_id());
        let receiver = ParticipantId(*roster.entries()[1].participant_id());
        let dom_chain = ChainId(*trusted_chain.as_bytes());
        let terms = |settlement: u8, session: [u8; 32], counterparty_chain: u8| SettlementTermsV1 {
            settlement_id: SettlementId([settlement; 32]),
            session_id: KaystraSessionId(session),
            intent_hash: IntentHash([0x51; 32]),
            solver_id: SolverId([0x52; 32]),
            roster: [sender, receiver],
            dom_leg: LegTermsV1 {
                role: LegRole::Dom,
                chain_id: dom_chain,
                asset_id: AssetId([0x61; 32]),
                amount: 50,
                beneficiary: sender,
                refund_to: receiver,
                mechanism: LockMechanism::DomAdaptor2of2,
                deadline: TimelockSpec::BlockHeight { value: 500 },
                finality: FinalityPolicyV1 {
                    min_confirmations: 2,
                    max_reorg_depth: 8,
                },
                adapter_profile_hash: [0x62; 32],
            },
            counterparty_leg: LegTermsV1 {
                role: LegRole::Counterparty,
                chain_id: ChainId([counterparty_chain; 32]),
                asset_id: AssetId([counterparty_chain.wrapping_add(1); 32]),
                amount: 60,
                beneficiary: receiver,
                refund_to: sender,
                mechanism: LockMechanism::ConditionLock,
                deadline: TimelockSpec::TimestampSeconds { value: 900_000 },
                finality: FinalityPolicyV1 {
                    min_confirmations: 3,
                    max_reorg_depth: 12,
                },
                adapter_profile_hash: [counterparty_chain.wrapping_add(2); 32],
            },
            adaptor_point_sec1: adaptor_point.to_compressed_bytes(),
            fee_limit: FeeLimitV1 {
                dom_max: 7,
                counterparty_max: 11,
            },
            recovery: RecoveryPolicyV1 {
                refund_before_funding: true,
                evidence_retention_blocks: 144,
            },
            assurance_policy_hash: Some([0x63; 32]),
            policy_version: 2,
            metadata: b"store-v2-record-fixture".to_vec(),
        };
        Ok((terms(0x71, session_id, 0x81), terms(0x73, [0x74; 32], 0x91)))
    }

    fn v2_record_codec_fixture() -> Result<V2RecordCodecFixture, Box<dyn Error>> {
        let trusted_chain = TrustedChainIdV1::from_authenticated_genesis(
            0xd04d_0001,
            &Hash256::from_bytes([0x42; 32]),
        );
        let expected_chain_id = *trusted_chain.as_bytes();
        let identity_a = SecretKey::from_bytes(&[0x11; 32])?.public_key();
        let identity_b = SecretKey::from_bytes(&[0x12; 32])?.public_key();
        let mut share_a_bytes = [0; 32];
        share_a_bytes[31] = 3;
        let mut share_b_bytes = [0; 32];
        share_b_bytes[31] = 5;
        let share_a = SecretKey::from_bytes(&share_a_bytes)?.public_key();
        let share_b = SecretKey::from_bytes(&share_b_bytes)?.public_key();
        let probe_a = ParticipantIdentityV1::new(
            &trusted_chain,
            identity_a.clone(),
            share_a.clone(),
            DirectionV1::Initiator,
        )?;
        let probe_b = ParticipantIdentityV1::new(
            &trusted_chain,
            identity_b.clone(),
            share_b.clone(),
            DirectionV1::Initiator,
        )?;
        let ((lower_identity, lower_share), (upper_identity, upper_share)) =
            if probe_a.participant_id() < probe_b.participant_id() {
                ((identity_a, share_a), (identity_b, share_b))
            } else {
                ((identity_b, share_b), (identity_a, share_a))
            };
        let responder = ParticipantIdentityV1::new(
            &trusted_chain,
            lower_identity,
            lower_share,
            DirectionV1::Responder,
        )?;
        let initiator = ParticipantIdentityV1::new(
            &trusted_chain,
            upper_identity,
            upper_share,
            DirectionV1::Initiator,
        )?;
        let roster = ParticipantRosterV1::new(vec![responder, initiator])?;
        let sender = ParticipantId(*roster.entries()[0].participant_id());
        let receiver = ParticipantId(*roster.entries()[1].participant_id());
        let participant_ids = [sender.0, receiver.0];
        let commitment_shares = roster
            .entries()
            .iter()
            .map(|participant| participant.signing_public_key().clone())
            .collect::<Vec<_>>();
        let aggregate_commitment =
            BpStatementV1::aggregate_commitment_from_shares(&commitment_shares, 42)?;
        let recovery_binding_hash = [0x44; 32];
        let session_id = [0x31; 32];
        let statement = BpStatementV1::new(
            &trusted_chain,
            session_id,
            participant_ids.to_vec(),
            42,
            commitment_shares,
            aggregate_commitment.clone(),
            Some(recovery_binding_hash),
        )?;

        let funding_bytes = deterministic_dom_transaction_bytes(
            DeterministicDomTransactionInputs {
                features: KERNEL_FEAT_PLAIN,
                lock_height: 0,
                input_value: 44,
                output_value: 42,
                input_seed: 3,
                kernel_seed: 5,
                proof_seed: 0x31,
            },
            &expected_chain_id,
        )?;
        let claim_bytes = deterministic_dom_transaction_bytes(
            DeterministicDomTransactionInputs {
                features: KERNEL_FEAT_PLAIN,
                lock_height: 0,
                input_value: 42,
                output_value: 40,
                input_seed: 8,
                kernel_seed: 13,
                proof_seed: 0x32,
            },
            &expected_chain_id,
        )?;
        let refund_bytes = deterministic_dom_transaction_bytes(
            DeterministicDomTransactionInputs {
                features: KERNEL_FEAT_HEIGHT_LOCKED,
                lock_height: 500,
                input_value: 42,
                output_value: 40,
                input_seed: 8,
                kernel_seed: 14,
                proof_seed: 0x33,
            },
            &expected_chain_id,
        )?;
        let funding_transaction = <Transaction as DomDeserialize>::from_bytes(&funding_bytes)?;
        let claim_transaction = <Transaction as DomDeserialize>::from_bytes(&claim_bytes)?;
        let refund_transaction = <Transaction as DomDeserialize>::from_bytes(&refund_bytes)?;
        let (funding_template_bytes, funding_template_hash) =
            canonical_template_v1(&funding_transaction)?;
        let (claim_template_bytes, claim_template_hash) =
            canonical_template_v1(&claim_transaction)?;
        let (refund_template_bytes, refund_template_hash) =
            canonical_template_v1(&refund_transaction)?;
        let adaptor_point = SecretKey::from_bytes(&[0x17; 32])?.public_key();
        let dom_chain = ChainId(expected_chain_id);
        let terms = |settlement: u8, session: [u8; 32], counterparty_chain: u8| SettlementTermsV1 {
            settlement_id: SettlementId([settlement; 32]),
            session_id: KaystraSessionId(session),
            intent_hash: IntentHash([0x51; 32]),
            solver_id: SolverId([0x52; 32]),
            roster: [sender, receiver],
            dom_leg: LegTermsV1 {
                role: LegRole::Dom,
                chain_id: dom_chain,
                asset_id: AssetId([0x61; 32]),
                amount: 50,
                beneficiary: sender,
                refund_to: receiver,
                mechanism: LockMechanism::DomAdaptor2of2,
                deadline: TimelockSpec::BlockHeight { value: 500 },
                finality: FinalityPolicyV1 {
                    min_confirmations: 2,
                    max_reorg_depth: 8,
                },
                adapter_profile_hash: [0x62; 32],
            },
            counterparty_leg: LegTermsV1 {
                role: LegRole::Counterparty,
                chain_id: ChainId([counterparty_chain; 32]),
                asset_id: AssetId([counterparty_chain.wrapping_add(1); 32]),
                amount: 60,
                beneficiary: receiver,
                refund_to: sender,
                mechanism: LockMechanism::ConditionLock,
                deadline: TimelockSpec::TimestampSeconds { value: 900_000 },
                finality: FinalityPolicyV1 {
                    min_confirmations: 3,
                    max_reorg_depth: 12,
                },
                adapter_profile_hash: [counterparty_chain.wrapping_add(2); 32],
            },
            adaptor_point_sec1: adaptor_point.to_compressed_bytes(),
            fee_limit: FeeLimitV1 {
                dom_max: 7,
                counterparty_max: 11,
            },
            recovery: RecoveryPolicyV1 {
                refund_before_funding: true,
                evidence_retention_blocks: 144,
            },
            assurance_policy_hash: Some([0x63; 32]),
            policy_version: 2,
            metadata: b"store-v2-record-fixture".to_vec(),
        };
        let upstream = terms(0x71, session_id, 0x81);
        let downstream = terms(0x73, [0x74; 32], 0x91);
        let route_id = [0xa1; 32];
        let route_scope_digest = [0xa2; 32];
        let composition_binding_digest = [0xa3; 32];
        let upstream_scope =
            FinalClaimSecretSourceScopeV1::new(FinalClaimSecretSourceScopeInputV1 {
                secret_source: FinalClaimSecretSourceV1::LocalOrigin,
                reveal_mode: FinalClaimRevealModeV1::DomRevealsFirst,
                route_id,
                composition_binding_digest,
                source_chain_id: upstream.dom_leg.chain_id,
                source_settlement_id: upstream.settlement_id,
                source_session_id: upstream.session_id,
                source_claim_template_hash: claim_template_hash,
                adaptor_point_sec1: upstream.adaptor_point_sec1,
                adaptor_secret_origin_id: sender,
                dom_claim_sender_id: sender,
            })?;
        let downstream_scope =
            FinalClaimSecretSourceScopeV1::new(FinalClaimSecretSourceScopeInputV1 {
                secret_source: FinalClaimSecretSourceV1::LocalOrigin,
                reveal_mode: FinalClaimRevealModeV1::DomRevealsFirst,
                route_id,
                composition_binding_digest,
                source_chain_id: downstream.dom_leg.chain_id,
                source_settlement_id: downstream.settlement_id,
                source_session_id: downstream.session_id,
                source_claim_template_hash: [0xb2; 32],
                adaptor_point_sec1: downstream.adaptor_point_sec1,
                adaptor_secret_origin_id: sender,
                dom_claim_sender_id: sender,
            })?;
        let upstream_selection = FinalClaimRoleSelectionV1::new(
            sender,
            sender,
            receiver,
            FinalClaimRevealModeV1::DomRevealsFirst,
            FinalClaimSecretSourceV1::LocalOrigin,
            upstream_scope.clone(),
        )?;
        let downstream_selection = FinalClaimRoleSelectionV1::new(
            sender,
            sender,
            receiver,
            FinalClaimRevealModeV1::DomRevealsFirst,
            FinalClaimSecretSourceV1::LocalOrigin,
            downstream_scope,
        )?;
        let plan = ComposedFinalClaimRolePlanV1::bind(ComposedFinalClaimRolePlanInputV1 {
            route_id,
            route_scope_digest,
            composition_binding_digest,
            upstream_terms: &upstream,
            downstream_terms: &downstream,
            upstream_selection,
            downstream_selection,
        })?;
        let role = FinalClaimRoleBindingV1::bind(
            &trusted_chain,
            FinalClaimRoleBindingInputV1 {
                terms: &upstream,
                roster: &roster,
                role_plan: &plan,
                source_scope: &upstream_scope,
                route_leg: ComposedSettlementLegV1::Upstream,
                funding_template_hash,
                claim_template_hash,
                refund_template_hash,
                shared_output_commitment: aggregate_commitment.to_compressed_bytes(),
                claim_kernel_index: 0,
            },
        )?;
        let terms_hash = upstream.terms_hash()?;
        let policy = v2_timing_policy(terms_hash);
        let policy_digest = policy.policy_digest()?;
        let refund_tx_hash = *blake2b_256(&refund_bytes).as_bytes();
        let backup_receipt_hash = [0xd5; 32];
        let ready = OperationalM8ReadyBindingV2::new(OperationalM8ReadyBindingInputV2 {
            role_binding: &role,
            m8_policy_digest: policy_digest,
            refund_tx_hash,
            bp_statement_hash: statement.statement_hash(),
            recovery_binding_hash,
            backup_receipt_hash,
            refund_unlock_height: 500,
        })?;
        let role_bytes = role.canonical_bytes()?;
        let role_audit = RetainedFinalClaimRoleBindingAuditV1::decode_canonical(
            &expected_chain_id,
            &role_bytes,
        )?;
        let ready_audit = RetainedOperationalM8ReadyBindingAuditV2::decode_canonical(
            &role_audit,
            &ready.canonical_bytes(),
        )?;
        let bound = SessionRecordV1::new(
            SessionRecordFieldsV1 {
                session_id,
                revision: 1,
                phase: SessionPhaseV1::RefundSigned,
                terms_hash,
                transcript_hash: [0x33; 32],
                irreversible: SessionIrreversibleV1 {
                    any_signing_share_sent: true,
                    funding_authorized: false,
                    adaptor_secret_exposed: false,
                    nonce_epoch: 7,
                },
                chain: projection(100),
            },
            b"v2-record-fixture-payload",
        )?;
        let gate = OperationalM8FundingGateRecordV2::new(
            &expected_chain_id,
            &bound,
            OperationalM8FundingGateRecordInputsV2 {
                validation_now_unix_seconds: 1_700_000_000,
                transport_roster_record_digest: [0xe1; 32],
                transport_identity_record_digest: [0xe2; 32],
                early_authority_record_digest: [0xe3; 32],
                bp_authority_record_digest: [0xe4; 32],
                template_authority_record_digest: [0xe5; 32],
                final_refund_record_digest: [0xe6; 32],
                final_refund_transport_record_digest: [0xe7; 32],
                role_binding: role_audit,
                ready_binding: ready_audit,
                policy,
                refund_bytes: refund_bytes.clone(),
                claim_template_bytes,
                refund_template_bytes,
                bp_statement_bytes: statement.to_bytes().to_vec(),
            },
        )?;

        let mut irreversible = bound.irreversible();
        irreversible.funding_authorized = true;
        let funding_authorized = bound.advance(
            bound.revision(),
            SessionPhaseV1::FundingAuthorized,
            bound.transcript_hash(),
            irreversible,
            bound.chain(),
            bound.encrypted_payload(),
        )?;
        let economic_binding = OperationalM8FundingAuthorizationBindingV1::new(
            expected_chain_id,
            session_id,
            funding_authorized.transcript_hash(),
            terms_hash,
            aggregate_commitment.to_compressed_bytes(),
            statement.statement_hash(),
            funding_template_hash,
            claim_template_hash,
            adaptor_point.to_compressed_bytes(),
            policy_digest,
            refund_tx_hash,
            backup_receipt_hash,
        )?;
        let binding = OperationalM8FundingAuthorizationBindingV2::new(
            economic_binding,
            role.digest()?,
            ready.digest(),
        )?;
        let issuance = OperationalM8FundingIssuanceRecordV2::new(
            binding,
            funding_authorized.revision(),
            gate.digest,
            &funding_template_bytes,
            &funding_authorized,
        )?;
        let verified = VerifiedFundingArtifactsV1 {
            session_id,
            terms_hash,
            refund_unlock_height: 500,
            refund_digest: tagged_hash(REFUND_HASH_TAG, &refund_bytes),
            funding_digest: tagged_hash(FUNDING_HASH_TAG, &funding_bytes),
            refund_bytes,
            funding_bytes,
        };
        let artifact = FundingArtifactRecordV1::new(
            session_id,
            terms_hash,
            funding_authorized.revision(),
            verified,
        )?;
        let broadcast = funding_authorized.advance(
            funding_authorized.revision(),
            SessionPhaseV1::FundingBroadcast,
            funding_authorized.transcript_hash(),
            funding_authorized.irreversible(),
            funding_authorized.chain(),
            funding_authorized.encrypted_payload(),
        )?;
        let consumption = FundingConsumptionRecordV1::new(
            session_id,
            funding_authorized.revision(),
            artifact.digest,
            &broadcast,
        )?;
        let commit = OperationalM8FundingCommitRecordV2::new(
            issuance.digest,
            role.digest()?,
            ready.digest(),
            artifact,
            consumption,
        )?;
        let confirmed = broadcast.advance(
            broadcast.revision(),
            SessionPhaseV1::FundingConfirmed,
            broadcast.transcript_hash(),
            broadcast.irreversible(),
            confirmed_post_anchor_projection(100),
            broadcast.encrypted_payload(),
        )?;
        let issued = PostAnchorClaimAuthorizationRecordV2::new_issued(
            &gate,
            &confirmed,
            PostAnchorClaimAuthorizationInputsV2 {
                m8_anchor_evidence_digest: [0x82; 32],
                dom_funding_id: [0x8a; 32],
                bitcoin_funding_id: [0x8b; 32],
                round_start_transcript_hash: confirmed.transcript_hash(),
                m8_funding_issuance_digest: issuance.digest,
                issuance_id: [0x87; 32],
                operational_funding_commit_digest: commit.digest,
                dom_minimum_confirmations: CRYPTO_REAL_DOM_MINIMUM_CONFIRMATIONS,
                dom_confirmation_depth: 6,
                bitcoin_confirmation_depth: 7,
            },
        )?;
        let consumed = PostAnchorClaimAuthorizationRecordV2::new_consumed(&issued)?;
        let signing_binding =
            PostAnchorClaimSigningBindingRecordV2::new(PostAnchorClaimSigningBindingInputsV2 {
                session_id,
                issuance_record_digest: issued.digest,
                consumption_record_digest: consumed.digest,
                signing_binding_record_digest: [0x95; 32],
                roster_digest: role.roster_digest(),
                round_start_record_digest: *confirmed.digest(),
                final_claim_role_binding_digest: role.digest()?,
                ready_binding_digest: ready.digest(),
            })?;
        let reveal_transcript_hash = [0x91; 32];
        let mut partial_scalar = [0; 32];
        partial_scalar[31] = 0x1a;
        let adaptor_pre_signature = AdaptorPreSignatureV1::new(
            claim_template_hash,
            adaptor_point,
            SecretKey::from_bytes(&[0x19; 32])?.public_key(),
            PartialSig::from_bytes(&partial_scalar)?,
            reveal_transcript_hash,
        );
        let round = OperationalSigningRoundAuditV1 {
            round_start_revision: confirmed.revision(),
            round_start_record_digest: *confirmed.digest(),
            round_start_transcript_hash: confirmed.transcript_hash(),
            reveal_transcript_hash: Some(reveal_transcript_hash),
            terminal_revision: confirmed.revision() + 6,
            terminal_record_digest: [0x92; 32],
            terminal_transcript_hash: [0x93; 32],
            sender_sequence_bases: [4, 7],
            template_commit_payload: [0x94; 160],
            accepted_messages: (0_u8..6).map(|index| vec![0xa0 + index]).collect(),
        };
        let pre_signature =
            PostAnchorClaimPreSignatureRecordV2::new(PostAnchorClaimPreSignatureInputsV2 {
                issued: &issued,
                consumed: &consumed,
                signing_binding: &signing_binding,
                round_binding_record_digest: signing_binding.digest,
                round: &round,
                pre_signature: &adaptor_pre_signature,
            })?;
        Ok(V2RecordCodecFixture {
            expected_chain_id,
            gate,
            issuance,
            commit,
            issued,
            consumed,
            signing_binding,
            pre_signature,
        })
    }

    #[test]
    fn m8_f7_v2_six_record_codecs_pin_selected_layout_fields_and_roundtrip(
    ) -> Result<(), Box<dyn Error>> {
        let fixture = v2_record_codec_fixture()?;

        let gate = OperationalM8FundingGateRecordV2::from_bytes(
            &fixture.expected_chain_id,
            &fixture.gate.bytes,
        )?;
        assert_eq!(gate.bytes, fixture.gate.bytes);
        assert_eq!(&gate.bytes[..8], M8_FUNDING_GATE_V2_CENSUS_MAGIC);
        assert_eq!(&gate.bytes[8..10], &M8_F7_V2_FORMAT_VERSION.to_le_bytes());
        assert_eq!(gate.bytes[10], M8_F7_V2_PROFILE);
        assert_eq!(&gate.bytes[11..16], &[0; 5]);
        assert_eq!(
            u32::from_le_bytes(copy_array(&gate.bytes[16..20])?) as usize,
            OPERATIONAL_M8_READY_BINDING_ENCODED_LEN
        );
        assert_eq!(
            &gate.bytes[M8_FUNDING_GATE_V2_PREFIX_LEN
                ..M8_FUNDING_GATE_V2_PREFIX_LEN + OPERATIONAL_M8_READY_BINDING_ENCODED_LEN],
            gate.ready_binding.canonical_bytes()
        );
        assert_eq!(
            &gate.bytes[gate.bytes.len() - DIGEST_LEN..],
            &tagged_hash(
                M8_FUNDING_GATE_V2_HASH_TAG,
                &gate.bytes[..gate.bytes.len() - DIGEST_LEN],
            )
        );

        let issuance = OperationalM8FundingIssuanceRecordV2::from_bytes(&fixture.issuance.bytes)?;
        assert_eq!(issuance.bytes, fixture.issuance.bytes);
        assert_eq!(
            &issuance.bytes[..8],
            &OPERATIONAL_M8_FUNDING_ISSUANCE_MAGIC_V2
        );
        assert_eq!(&issuance.bytes[8..10], &2_u16.to_le_bytes());
        assert_eq!(issuance.bytes[10], M8_F7_V2_PROFILE);
        assert_eq!(&issuance.bytes[16..480], &issuance.binding.to_bytes());
        assert_eq!(
            &issuance.bytes[issuance.bytes.len() - DIGEST_LEN..],
            &tagged_hash(
                OPERATIONAL_M8_FUNDING_ISSUANCE_V2_DOMAIN,
                &issuance.bytes[..issuance.bytes.len() - DIGEST_LEN],
            )
        );
        let commit = OperationalM8FundingCommitRecordV2::from_bytes(&fixture.commit.bytes)?;
        assert_eq!(commit.bytes, fixture.commit.bytes);
        assert_eq!(&commit.bytes[..8], &OPERATIONAL_M8_FUNDING_COMMIT_MAGIC_V2);
        assert_eq!(&commit.bytes[8..10], &2_u16.to_le_bytes());
        assert_eq!(commit.bytes[10], M8_F7_V2_PROFILE);
        assert_eq!(&commit.bytes[152..184], &commit.artifact.digest);
        assert_eq!(
            &commit.bytes[commit.bytes.len() - DIGEST_LEN..],
            &tagged_hash(
                OPERATIONAL_M8_FUNDING_COMMIT_V2_DOMAIN,
                &commit.bytes[..commit.bytes.len() - DIGEST_LEN],
            )
        );

        let issued = PostAnchorClaimAuthorizationRecordV2::from_bytes(&fixture.issued.bytes)?;
        let consumed = PostAnchorClaimAuthorizationRecordV2::from_bytes(&fixture.consumed.bytes)?;
        assert_eq!(issued.bytes, fixture.issued.bytes);
        assert_eq!(consumed.bytes, fixture.consumed.bytes);
        assert_eq!(&issued.bytes[..8], POST_ANCHOR_CLAIM_AUTH_V2_CENSUS_MAGIC);
        assert_eq!(
            issued.bytes[10],
            PostAnchorClaimAuthorizationStateV2::Issued.byte()
        );
        assert_eq!(
            consumed.bytes[10],
            PostAnchorClaimAuthorizationStateV2::Consumed.byte()
        );
        assert_eq!(&issued.bytes[584..616], &[0; 32]);
        assert_eq!(&consumed.bytes[584..616], &issued.digest);
        assert_eq!(
            &issued.bytes[808..840],
            &tagged_hash(POST_ANCHOR_CLAIM_AUTH_V2_HASH_TAG, &issued.bytes[..808])
        );

        let signing =
            PostAnchorClaimSigningBindingRecordV2::from_bytes(&fixture.signing_binding.bytes)?;
        assert_eq!(signing.bytes, fixture.signing_binding.bytes);
        assert_eq!(
            &signing.bytes[..8],
            POST_ANCHOR_CLAIM_BINDING_V2_CENSUS_MAGIC
        );
        assert_eq!(
            &signing.bytes[208..240],
            &issued.final_claim_role_binding_digest
        );
        assert_eq!(&signing.bytes[240..272], &issued.ready_binding_digest);
        assert_eq!(
            &signing.bytes[272..304],
            &tagged_hash(POST_ANCHOR_CLAIM_BINDING_V2_HASH_TAG, &signing.bytes[..272])
        );

        let pre_signature =
            PostAnchorClaimPreSignatureRecordV2::from_bytes(&fixture.pre_signature.bytes)?;
        assert_eq!(pre_signature.bytes, fixture.pre_signature.bytes);
        assert_eq!(
            &pre_signature.bytes[..8],
            POST_ANCHOR_CLAIM_PRE_SIGNATURE_V2_CENSUS_MAGIC
        );
        assert_eq!(
            &pre_signature.bytes[473..505],
            &issued.final_claim_role_binding_digest
        );
        assert_eq!(&pre_signature.bytes[505..537], &issued.ready_binding_digest);
        assert_eq!(
            &pre_signature.bytes[699..731],
            &tagged_hash(
                POST_ANCHOR_CLAIM_PRE_SIGNATURE_V2_HASH_TAG,
                &pre_signature.bytes[..699],
            )
        );
        Ok(())
    }

    #[test]
    fn m8_f7_v2_gate_only_audit_preflight_accepts_distinct_keys_with_responder_first_role(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let store_name = "sessions";
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let fixture = crypto_real_m8_f7_v2_gate_audit_fixture(&temporary, &evidence_policy)?;
        assert_eq!(
            fixture
                .material
                .transport_roster
                .participants
                .map(|participant| participant.direction),
            [DirectionV1::Initiator, DirectionV1::Responder]
        );
        assert_eq!(
            fixture
                .gate
                .role_binding
                .roster_entries()
                .iter()
                .map(|participant| participant.direction())
                .collect::<Vec<_>>(),
            vec![DirectionV1::Responder, DirectionV1::Initiator]
        );
        for role_entry in fixture.gate.role_binding.roster_entries() {
            assert_ne!(
                role_entry.identity_public_key_sec1(),
                role_entry.signing_public_key_sec1()
            );
        }
        let session_hex = hex_lower(&fixture.material.bound.session_id());
        let gate_name = format!("{session_hex}.operational-m8-funding-gate-v2");
        write_store_test_file(
            &temporary,
            store_name,
            ARTIFACTS_NAME,
            &gate_name,
            &fixture.gate.bytes,
        )?;
        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            store_name,
            evidence_policy,
        )?;
        assert_eq!(
            reopened
                .load_session(fixture.material.bound.session_id())?
                .as_bytes(),
            fixture.material.bound.as_bytes()
        );
        Ok(())
    }

