        rechecksum_test_record(&mut signing, POST_ANCHOR_CLAIM_BINDING_V2_HASH_TAG)?;
        assert_quarantined(PostAnchorClaimSigningBindingRecordV2::from_bytes(&signing));

        let mut pre_signature = fixture.pre_signature.bytes;
