    fn real_bound_backup_ack_fixture(
        initial: &SessionRecordV1,
    ) -> Result<(EarlyTransportTestFixture, [BoundShareBackupAckV2; 2]), Box<dyn Error>> {
        let trusted_chain_id = TrustedChainIdV1::from_authenticated_genesis(
            0x4455_6677,
            &Hash256::from_bytes([0x91; 32]),
        );
        let participant_ids = [[0xa1; 32], [0xb2; 32]];
        let directions = [DirectionV1::Initiator, DirectionV1::Responder];
        let identity_keys = [
            SecretKey::from_bytes(&[0x11; 32])?,
            SecretKey::from_bytes(&[0x12; 32])?,
        ];
        let mut vault_a = TestSharedBlindingVault::default();
        let mut vault_b = TestSharedBlindingVault::default();
        let pending_a = contribute_vault_backed_blinding_share_v1(
            &trusted_chain_id,
            initial.session_id(),
            &participant_ids,
            directions[0],
            0,
            initial.terms_hash(),
            &mut vault_a,
        )?;
        let pending_b = contribute_vault_backed_blinding_share_v1(
            &trusted_chain_id,
            initial.session_id(),
            &participant_ids,
            directions[1],
            1,
            initial.terms_hash(),
            &mut vault_b,
        )?;
        let decoy_a = pending_a.derive_decoy_contribution_v1()?;
        let decoy_b = pending_b.derive_decoy_contribution_v1()?;
        let remote_commitment = decoy_b.commitment();
        let recovery_capsule = combine_decoy_capsule_v1(
            &decoy_a.into_reveal(),
            &decoy_b.into_reveal(),
            &remote_commitment,
        )?;
        let mut capability_a =
            pending_a.bind_recovery_capsule_v1(&recovery_capsule, &mut vault_a)?;
        let mut capability_b =
            pending_b.bind_recovery_capsule_v1(&recovery_capsule, &mut vault_b)?;
        let signing_share_bytes = [
            vault_a.plaintext.ok_or(SessionStoreError::Quarantined)?,
            vault_b.plaintext.ok_or(SessionStoreError::Quarantined)?,
        ];
        let signing_shares = [
            SigningShareV1::from_be_bytes(signing_share_bytes[0])?,
            SigningShareV1::from_be_bytes(signing_share_bytes[1])?,
        ];
        if signing_shares[0].public_key() != capability_a.public_key()
            || signing_shares[1].public_key() != capability_b.public_key()
        {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        let shared_bindings = [
            capability_a.binding().clone(),
            capability_b.binding().clone(),
        ];
        let acknowledgements = [
            capability_a.take_bound_durable_backup_ack_v2()?,
            capability_b.take_bound_durable_backup_ack_v2()?,
        ];
        Ok((
            EarlyTransportTestFixture {
                trusted_chain_id,
                recovery_capsule,
                identity_keys,
                participant_ids,
                directions,
                signing_shares,
                signing_share_bytes,
                shared_bindings,
            },
            acknowledgements,
        ))
    }

