    fn require_prepared_signing_rejection(
        store: &ContractsSessionStoreV1,
        authority: &PreparedOperationalSigningTransportAuthorityV1,
        current: &SessionRecordV1,
        signed: &[u8],
    ) -> Result<(), Box<dyn Error>> {
        let message_count = store.transport_message_count(current.session_id())?;
        if store
            .accept_prepared_operational_signing_transport_message(authority, signed)
            .is_ok()
        {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        if store.load_session(current.session_id())?.as_bytes() != current.as_bytes() {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        if store.transport_message_count(current.session_id())? != message_count {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        Ok(())
    }

