    fn crypto_real_m8_ready_gate_fixture(
        temporary: &TestDirectory,
        evidence_policy: &BudgetPolicyV1,
    ) -> Result<CryptoRealM8ReadyGateFixture, Box<dyn Error>> {
        let base = crypto_real_final_refund_transport_fixture(temporary, evidence_policy)?;
        assert!(matches!(
            base.store
                .accept_prepared_operational_final_refund_transport_message(
                    &base.prepared,
                    &base.signed,
                )?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: false,
                message_type: 0x10,
                ..
            })
        ));
        let current = base.store.load_session(base.initial.session_id())?;
        if current.phase() != SessionPhaseV1::RefundSigned
            || current.revision() != base.prepared.terminal_revision + 1
            || base.prepared.terminal_revision != base.terminal.revision()
        {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        let mut adaptor_scalar = [0; 32];
        adaptor_scalar[31] = 61;
        let evidence = base.m8_evidence_for_refund(
            secret_scalar_public_key(&adaptor_scalar)?,
            base.refund_bytes.clone(),
            base.refund_tx_hash,
        )?;
        let prepared = base
            .store
            .prepare_operational_m8_funding_gate_authority(evidence)?;
        let retained_gate = base.store.load_m8_funding_gate(current.session_id())?;
        if prepared.session_id != current.session_id()
            || prepared.gate_digest != retained_gate.digest
            || prepared.refund_tx_hash != retained_gate.refund_tx_hash
        {
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        let (refund_template_bytes, refund_template_hash) =
            canonical_template_v1(&base.refund_transaction)?;
        let CryptoRealFinalRefundTransportFixture { store, fixture, .. } = base;
        Ok(CryptoRealM8ReadyGateFixture {
            store,
            current,
            fixture,
            prepared,
            retained_gate,
            refund_template_bytes,
            refund_template_hash,
        })
    }

