    /// The in-process producer of the two bound backup acknowledgements.
    ///
    /// It takes the bindings and the share plaintexts instead of the whole
    /// fixture because it is now one implementation of a *parameter*: the
    /// staging chain accepts any producer with this shape, so the test double
    /// below never has to leave `mod tests`.
    fn live_bound_backup_acknowledgements_v2(
        bindings: &[SharedBlindingBindingV1; 2],
        share_bytes: &[[u8; 32]; 2],
    ) -> Result<[BoundShareBackupAckV2; 2], Box<dyn Error>> {
        let mut vault_a = TestSharedBlindingVault {
            plaintext: Some(share_bytes[0]),
            pending: None,
            bound: Some(bindings[0].clone()),
        };
        let mut vault_b = TestSharedBlindingVault {
            plaintext: Some(share_bytes[1]),
            pending: None,
            bound: Some(bindings[1].clone()),
        };
        let mut capability_a =
            open_vault_backed_blinding_share_v1(bindings[0].clone(), &mut vault_a)?;
        let mut capability_b =
            open_vault_backed_blinding_share_v1(bindings[1].clone(), &mut vault_b)?;
        Ok([
            capability_a.take_bound_durable_backup_ack_v2()?,
            capability_b.take_bound_durable_backup_ack_v2()?,
        ])
    }

