    #[test]
    fn b2_v2_identical_duplicate_and_equivocation_are_durable() -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let CryptoRealM8F7V2LiveGateFixture {
            store,
            initial,
            fixture,
            bp: _,
            funding_template: _,
            roster: _,
            role_binding: _,
            ready_binding: _,
            timing_policy: _,
            gate,
        } = crypto_real_m8_f7_v2_live_gate_fixture(&temporary, &evidence_policy)?;
        let session_id = initial.session_id();
        let vote = store
            .prepare_next_operational_m8_ready_to_fund_vote_v2(&gate)?
            .ok_or(SessionStoreError::FundingAuthorityUnavailable)?;
        let sender_id = vote.participant_id();
        let sequence = vote.sequence();
        let predecessor = vote.previous_transcript_hash();
        let payload = vote.payload();
        let sender_index = fixture
            .participant_ids
            .iter()
            .position(|candidate| candidate == &sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        let signed = sign_prepared_m8_f7_v2_vote(&fixture, &vote, &payload)?;
        store.accept_prepared_operational_m8_ready_to_fund_vote_v2(&gate, vote, &signed)?;

        let before_duplicate = snapshot_store_tree(&temporary.path().join("sessions"))?;
        assert!(matches!(
            store.accept_transport_message_derived(&signed)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                message_type: 0x11,
                ..
            })
        ));
        assert_eq!(
            snapshot_store_tree(&temporary.path().join("sessions"))?,
            before_duplicate
        );

        let mut conflicting_payload = payload;
        conflicting_payload[0] ^= 1;
        let conflict = transport_signed_bytes(
            fixture.identity_key(sender_index),
            *fixture.trusted_chain_id.as_bytes(),
            session_id,
            sender_id,
            sequence,
            predecessor,
            0x11,
            &conflicting_payload,
        )?;
        assert!(matches!(
            store.accept_transport_message_derived(&conflict)?,
            DurableTransportOutcomeV1::EquivocationPersisted
        ));
        assert_eq!(
            store.load_session(session_id)?.phase(),
            SessionPhaseV1::FailedClosed
        );
        drop(store);
        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        assert_eq!(
            reopened.load_session(session_id)?.phase(),
            SessionPhaseV1::FailedClosed
        );
        Ok(())
    }

