    #[test]
    fn b2_v2_issuance_funding_template_crossbinding_rejects_coherent_substitution(
    ) -> Result<(), Box<dyn Error>> {
        let fixture = v2_record_codec_fixture()?;
        let alternative_funding_bytes = deterministic_dom_transaction_bytes(
            DeterministicDomTransactionInputs {
                features: KERNEL_FEAT_PLAIN,
                lock_height: 0,
                input_value: 44,
                output_value: 42,
                input_seed: 4,
                kernel_seed: 6,
                proof_seed: 0x41,
            },
            &fixture.expected_chain_id,
        )?;
        let alternative_funding =
            <Transaction as DomDeserialize>::from_bytes(&alternative_funding_bytes)?;
        let (alternative_template_bytes, alternative_template_hash) =
            canonical_template_v1(&alternative_funding)?;
        let original = &fixture.issuance.binding;
        assert_ne!(alternative_template_hash, *original.funding_template_hash());
        let economic_binding = OperationalM8FundingAuthorizationBindingV1::new(
            *original.chain_id(),
            *original.session_id(),
            *original.transcript_hash(),
            *original.terms_hash(),
            *original.shared_output_commitment(),
            *original.bp_statement_hash(),
            alternative_template_hash,
            *original.claim_template_hash(),
            *original.claim_adaptor_point(),
            *original.m8_policy_digest(),
            *original.refund_tx_hash(),
            *original.backup_receipt_hash(),
        )?;
        let substituted_binding = OperationalM8FundingAuthorizationBindingV2::new(
            economic_binding,
            *original.final_claim_role_binding_digest(),
            *original.ready_binding_digest(),
        )?;
        let substituted = OperationalM8FundingIssuanceRecordV2::new(
            substituted_binding,
            fixture.issuance.authorized_revision,
            fixture.gate.digest,
            &alternative_template_bytes,
            &fixture.issuance.funding_authorized_record,
        )?;
        let decoded = OperationalM8FundingIssuanceRecordV2::from_bytes(&substituted.bytes)?;
        assert_eq!(
            decoded.binding.funding_template_hash(),
            &alternative_template_hash
        );
        assert!(matches!(
            require_m8_f7_v2_issuance_cross_binding(
                &fixture.expected_chain_id,
                &fixture.gate,
                &decoded,
            ),
            Err(SessionStoreError::Quarantined)
        ));
        Ok(())
    }

