    #[test]
    fn post_anchor_0x0f_duplicate_and_equivocation_survive_projection_and_restart(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let CryptoRealPostAnchorTransportFixture {
            store,
            fixture,
            roster: _,
            evidence,
            consumed: _,
            terminal,
            prepared,
            pre_signature_payload,
        } = crypto_real_post_anchor_transport_fixture(&temporary, &evidence_policy)?;
        let session_id = terminal.session_id();
        let signed = sign_prepared_post_anchor_claim_pre_signature(
            &fixture,
            &prepared,
            &pre_signature_payload,
        )?;
        assert!(matches!(
            store.accept_prepared_post_anchor_dom_claim_pre_signature_transport_message(
                &prepared, &signed,
            )?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: false,
                ..
            })
        ));
        let projected = revalidate_fresh_post_anchor_projection(&store, &evidence, 101)?;
        assert_eq!(projected.chain().tip_height, 101);
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        let resumed = reopened.resume_consumed_post_anchor_dom_claim_signing(session_id)?;
        let reissued = reopened.prepare_post_anchor_dom_claim_pre_signature_transport_authority(
            &resumed,
            fixture.trusted_chain_id,
        )?;
        assert!(matches!(
            reopened.accept_prepared_post_anchor_dom_claim_pre_signature_transport_message(
                &reissued, &signed,
            )?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        let projected = revalidate_fresh_post_anchor_projection(&reopened, &evidence, 102)?;
        assert_eq!(projected.chain().tip_height, 102);
        drop(reopened);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        let resumed = reopened.resume_consumed_post_anchor_dom_claim_signing(session_id)?;
        let reissued = reopened.prepare_post_anchor_dom_claim_pre_signature_transport_authority(
            &resumed,
            fixture.trusted_chain_id,
        )?;
        assert!(matches!(
            reopened.accept_prepared_post_anchor_dom_claim_pre_signature_transport_message(
                &reissued, &signed,
            )?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        let before_conflict = reopened.load_session(session_id)?;
        let mut conflicting_payload = pre_signature_payload;
        conflicting_payload[AdaptorPreSignatureV1::ENCODED_LEN - 1] ^= 1;
        let conflict = sign_prepared_post_anchor_claim_pre_signature(
            &fixture,
            &reissued,
            &conflicting_payload,
        )?;
        assert!(matches!(
            reopened.accept_prepared_post_anchor_dom_claim_pre_signature_transport_message(
                &reissued, &conflict,
            )?,
            DurableTransportOutcomeV1::EquivocationPersisted
        ));
        let failed = reopened.load_session(session_id)?;
        assert_eq!(failed.phase(), SessionPhaseV1::FailedClosed);
        assert_eq!(failed.chain(), before_conflict.chain());
        assert_eq!(failed.irreversible(), before_conflict.irreversible());
        assert_eq!(
            failed.encrypted_payload(),
            before_conflict.encrypted_payload()
        );
        drop(reopened);

        let final_reopen = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        let durable_failed = final_reopen.load_session(session_id)?;
        assert_eq!(durable_failed.phase(), SessionPhaseV1::FailedClosed);
        assert_eq!(durable_failed.chain(), before_conflict.chain());
        assert!(matches!(
            final_reopen.accept_transport_message_derived(&signed)?,
            DurableTransportOutcomeV1::EquivocationPersisted
        ));
        assert_eq!(
            final_reopen.load_session(session_id)?.as_bytes(),
            durable_failed.as_bytes()
        );
        Ok(())
    }

