    fn seed_transport_record_for_restart(
        store: &ContractsSessionStoreV1,
        signed_bytes: &[u8],
        successor: &SessionRecordV1,
        persist_successor: bool,
    ) -> Result<(), Box<dyn Error>> {
        let envelope = ParsedTransportEnvelopeV1::parse(signed_bytes)?;
        let roster = store.load_transport_roster(envelope.session_id)?;
        let participant = roster
            .participants
            .iter()
            .find(|candidate| candidate.participant_id == envelope.sender_id)
            .ok_or(SessionStoreError::Canonical)?;
        let record = TransportMessageRecordV1::new(
            &envelope,
            signed_bytes,
            successor,
            participant.direction,
            false,
        )?;
        let name = transport_message_name(
            envelope.session_id,
            envelope.sender_id,
            envelope.sequence,
            false,
        );
        publish_immutable(
            &store.messages,
            &format!(".{name}.staging"),
            &name,
            &record.bytes,
            TRANSPORT_MESSAGE_MAX_LEN,
        )?;
        if persist_successor {
            store.persist_session_record(successor)?;
        }
        Ok(())
    }

    fn late_restart_phases(
        message_type: u8,
    ) -> Result<(SessionPhaseV1, SessionPhaseV1), SessionStoreError> {
        match message_type {
            0x0b => Ok((
                SessionPhaseV1::OutputFinalized,
                SessionPhaseV1::TemplatesCommitted,
            )),
            0x0c => Ok((
                SessionPhaseV1::TemplatesCommitted,
                SessionPhaseV1::RefundSigning,
            )),
            0x0d | 0x0e => Ok((SessionPhaseV1::RefundSigning, SessionPhaseV1::RefundSigning)),
            0x0f => Ok((
                SessionPhaseV1::FundingConfirmed,
                SessionPhaseV1::FundingConfirmed,
            )),
            0x10 => Ok((SessionPhaseV1::RefundSigning, SessionPhaseV1::RefundSigned)),
            0x11 => Ok((SessionPhaseV1::RefundSigned, SessionPhaseV1::RefundSigned)),
            0x12 => Ok((
                SessionPhaseV1::FundingConfirmed,
                SessionPhaseV1::ClaimBroadcast,
            )),
            0x13 => Ok((SessionPhaseV1::Created, SessionPhaseV1::Aborted)),
            0x14 => Ok((SessionPhaseV1::Created, SessionPhaseV1::Created)),
            _ => Err(SessionStoreError::Canonical),
        }
    }

    fn canonical_late_restart_payload(
        message_type: u8,
        chain_id: &[u8; 32],
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let payload = match message_type {
            0x0b => {
                let mut payload = [0u8; 160];
                for (index, chunk) in payload.chunks_exact_mut(32).enumerate() {
                    chunk.fill(u8::try_from(index)?.saturating_add(0x31));
                }
                if !template_commit_payload_is_valid(&payload) {
                    return Err(Box::new(SessionStoreError::Canonical));
                }
                payload.to_vec()
            }
            0x0c => NonceCommitmentV1::new(PurposeV1::Refund, 0, [0x41; 32])
                .to_bytes()
                .to_vec(),
            0x0d => NonceRevealV1::new(
                PurposeV1::Refund,
                0,
                SecretKey::from_bytes(&[0x42; 32])?.public_key(),
                SecretKey::from_bytes(&[0x43; 32])?.public_key(),
            )
            .to_bytes()
            .to_vec(),
            0x0e => {
                let mut scalar = [0; 32];
                scalar[31] = 0x44;
                PartialSignatureV1::new(
                    PurposeV1::Refund,
                    0,
                    [0x45; 32],
                    PartialSig::from_bytes(&scalar)?,
                )
                .to_bytes()
                .to_vec()
            }
            0x0f => {
                let mut scalar = [0; 32];
                scalar[31] = 0x46;
                AdaptorPreSignatureV1::new(
                    [0x47; 32],
                    SecretKey::from_bytes(&[0x48; 32])?.public_key(),
                    SecretKey::from_bytes(&[0x49; 32])?.public_key(),
                    PartialSig::from_bytes(&scalar)?,
                    [0x4a; 32],
                )
                .to_bytes()
                .to_vec()
            }
            0x10 => real_dom_transaction_bytes(
                KERNEL_FEAT_HEIGHT_LOCKED,
                144,
                3_000,
                2_970,
                25,
                26,
                chain_id,
            )?,
            0x11 => vec![0x51; 32],
            0x12 => {
                real_dom_transaction_bytes(KERNEL_FEAT_PLAIN, 0, 2_000, 1_980, 27, 28, chain_id)?
            }
            0x13 => b"typed-abort".to_vec(),
            0x14 => b"typed-ack".to_vec(),
            _ => return Err(Box::new(SessionStoreError::Canonical)),
        };
        Ok(payload)
    }

    #[test]
    fn prepared_early_transport_survives_restart_and_generic_stays_closed(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (store, initial, fixture) = early_transport_store(&temporary, &evidence_policy)?;
        let authority = store.prepare_early_transport_authority(
            fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        let payloads = EarlyTransportPayloads::new(&initial, &fixture, &authority)?;
        let offer = sign_early_transport_position(&fixture, &initial, 0, payloads.message(0))?;
        assert!(matches!(
            store.accept_transport_message_derived(&offer),
            Err(SessionStoreError::InvalidTransition)
        ));
        assert_eq!(
            store.load_session(initial.session_id())?.as_bytes(),
            initial.as_bytes()
        );

        let first = store.accept_prepared_early_transport_message(&authority, &offer)?;
        assert!(matches!(
            first,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: false,
                ..
            })
        ));
        let mut current = store.load_session(initial.session_id())?;
        let mut retained_messages = vec![offer];
        for position in 1..4 {
            let (successor, signed) = accept_early_transport_position(
                &store,
                &authority,
                &fixture,
                &current,
                position,
                payloads.message(position),
            )?;
            current = successor;
            retained_messages.push(signed);
        }
        assert_eq!(current.revision(), 4);
        assert_eq!(current.phase(), SessionPhaseV1::SharesCommitted);
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        assert!(matches!(
            reopened.accept_transport_message_derived(&retained_messages[2])?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        assert!(matches!(
            reopened.accept_prepared_early_transport_message(&authority, &retained_messages[2]),
            Err(SessionStoreError::InvalidTransition)
        ));
        let resumed = reopened.prepare_early_transport_authority(
            fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        for position in 4..6 {
            let (successor, signed) = accept_early_transport_position(
                &reopened,
                &resumed,
                &fixture,
                &current,
                position,
                payloads.message(position),
            )?;
            current = successor;
            retained_messages.push(signed);
        }
        assert_eq!(current.revision(), 6);
        assert_eq!(current.phase(), SessionPhaseV1::SharesRevealed);
        drop(reopened);

        let final_reopen = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        let final_authority = final_reopen.prepare_early_transport_authority(
            fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        assert!(matches!(
            final_reopen
                .accept_prepared_early_transport_message(&final_authority, &retained_messages[5])?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        assert_eq!(
            final_reopen.load_session(initial.session_id())?.as_bytes(),
            current.as_bytes()
        );
        Ok(())
    }

    #[test]
    fn prepared_operational_bp_transport_survives_every_restart_boundary(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (mut store, initial, fixture) = early_transport_store(&temporary, &evidence_policy)?;
        let mut current = complete_prepared_early_transport(&store, &initial, &fixture)?;
        let payloads = PreparedOperationalBpPayloads::new(&initial, &fixture)?;
        let mut authority = store.prepare_operational_bp_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &payloads.statement,
            &fixture.recovery_capsule,
        )?;

        for position in 0..11 {
            let signed = sign_prepared_bp_position(
                &fixture,
                &current,
                position,
                &payloads.messages[position],
            )?;
            assert!(matches!(
                store.accept_transport_message_derived(&signed),
                Err(SessionStoreError::InvalidTransition)
            ));
            assert!(matches!(
                store.accept_prepared_operational_bp_transport_message(&authority, &signed)?,
                DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                    duplicate: false,
                    ..
                })
            ));
            assert!(matches!(
                store.accept_prepared_operational_bp_transport_message(&authority, &signed)?,
                DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                    duplicate: true,
                    ..
                })
            ));
            current = store.load_session(initial.session_id())?;

            drop(store);
            let reopened = ContractsSessionStoreV1::open_evidence_only(
                temporary.capability()?,
                "sessions",
                evidence_policy.clone(),
            )?;
            assert!(matches!(
                reopened.accept_prepared_operational_bp_transport_message(&authority, &signed),
                Err(SessionStoreError::InvalidTransition)
            ));
            authority = reopened.prepare_operational_bp_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &payloads.statement,
                &fixture.recovery_capsule,
            )?;
            let continuation = reopened.resume_operational_bp_continuation(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &payloads.statement,
                &fixture.recovery_capsule,
            )?;
            assert_eq!(continuation.session_revision(), current.revision());
            assert_eq!(continuation.transcript_hash(), current.transcript_hash());
            if position == 10 {
                assert_eq!(
                    continuation.stage(),
                    OperationalBpContinuationStageV1::Complete
                );
                assert_eq!(
                    continuation.into_final_proof()?.proof_digest(),
                    *blake2b_256(&payloads.messages[10]).as_bytes()
                );
            }
            store = reopened;
        }
        assert_eq!(current.phase(), SessionPhaseV1::OutputFinalized);
        assert_eq!(current.revision(), 17);
        Ok(())
    }

    #[test]
    fn prepared_operational_bp_rejects_context_order_tamper_and_equivocation(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (store, initial, fixture) = early_transport_store(&temporary, &evidence_policy)?;
        let round_start = complete_prepared_early_transport(&store, &initial, &fixture)?;
        let payloads = PreparedOperationalBpPayloads::new(&initial, &fixture)?;
        let authority = store.prepare_operational_bp_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &payloads.statement,
            &fixture.recovery_capsule,
        )?;

        let require_rejected = |candidate: &[u8]| -> Result<(), Box<dyn Error>> {
            assert!(store
                .accept_prepared_operational_bp_transport_message(&authority, candidate)
                .is_err());
            assert_eq!(
                store.load_session(initial.session_id())?.as_bytes(),
                round_start.as_bytes()
            );
            Ok(())
        };
        let wrong_type = transport_signed_bytes(
            fixture.identity_key(0),
            *fixture.trusted_chain_id.as_bytes(),
            initial.session_id(),
            fixture.participant_ids[0],
            3,
            round_start.transcript_hash(),
            0x06,
            &payloads.messages[2],
        )?;
        require_rejected(&wrong_type)?;
        let wrong_sender = transport_signed_bytes(
            fixture.identity_key(1),
            *fixture.trusted_chain_id.as_bytes(),
            initial.session_id(),
            fixture.participant_ids[1],
            3,
            round_start.transcript_hash(),
            0x05,
            &payloads.messages[1],
        )?;
        require_rejected(&wrong_sender)?;
        let wrong_sequence = transport_signed_bytes(
            fixture.identity_key(0),
            *fixture.trusted_chain_id.as_bytes(),
            initial.session_id(),
            fixture.participant_ids[0],
            4,
            round_start.transcript_hash(),
            0x05,
            &payloads.messages[0],
        )?;
        require_rejected(&wrong_sequence)?;
        let short_payload = transport_signed_bytes(
            fixture.identity_key(0),
            *fixture.trusted_chain_id.as_bytes(),
            initial.session_id(),
            fixture.participant_ids[0],
            3,
            round_start.transcript_hash(),
            0x05,
            &[0x33; 31],
        )?;
        require_rejected(&short_payload)?;

        let commitment_shares = fixture
            .signing_shares
            .iter()
            .map(|share| share.public_key().clone())
            .collect::<Vec<_>>();
        let alternate_aggregate =
            BpStatementV1::aggregate_commitment_from_shares(&commitment_shares, 43)?;
        let alternate_statement = BpStatementV1::new(
            &fixture.trusted_chain_id,
            initial.session_id(),
            fixture.participant_ids.to_vec(),
            43,
            commitment_shares,
            alternate_aggregate,
            Some(*blake2b_256(fixture.recovery_capsule.as_bytes()).as_bytes()),
        )?;
        assert!(matches!(
            store.prepare_operational_bp_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &alternate_statement,
                &fixture.recovery_capsule,
            ),
            Err(SessionStoreError::Conflict)
        ));
        let mut alternate_capsule_bytes = *fixture.recovery_capsule.as_bytes();
        alternate_capsule_bytes[32] ^= 1;
        let alternate_capsule = RecoveryCapsule::from_bytes(&alternate_capsule_bytes)?;
        assert!(store
            .prepare_operational_bp_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &payloads.statement,
                &alternate_capsule,
            )
            .is_err());

        let (after_first, accepted) = accept_prepared_bp_position(
            &store,
            &authority,
            &fixture,
            &round_start,
            0,
            &payloads.messages[0],
        )?;
        let (after_second, _) = accept_prepared_bp_position(
            &store,
            &authority,
            &fixture,
            &after_first,
            1,
            &payloads.messages[1],
        )?;
        let mut wrong_reveal_payload = payloads.messages[2].clone();
        wrong_reveal_payload[0] ^= 1;
        let wrong_reveal =
            sign_prepared_bp_position(&fixture, &after_second, 2, &wrong_reveal_payload)?;
        assert!(store
            .accept_prepared_operational_bp_transport_message(&authority, &wrong_reveal)
            .is_err());
        assert_eq!(
            store.load_session(initial.session_id())?.as_bytes(),
            after_second.as_bytes()
        );

        let conflicting = sign_prepared_bp_position(&fixture, &round_start, 0, &[0x99; 32])?;
        assert!(matches!(
            store.accept_prepared_operational_bp_transport_message(&authority, &conflicting)?,
            DurableTransportOutcomeV1::EquivocationPersisted
        ));
        assert_eq!(
            store.load_session(initial.session_id())?.phase(),
            SessionPhaseV1::FailedClosed
        );
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        assert!(matches!(
            reopened.accept_transport_message_derived(&accepted)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        assert!(reopened
            .prepare_operational_bp_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &payloads.statement,
                &fixture.recovery_capsule,
            )
            .is_err());
        Ok(())
    }

