    #[test]
    fn prepared_operational_template_transport_survives_restart_and_generic_stays_closed(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (store, initial, fixture) = early_transport_store(&temporary, &evidence_policy)?;
        let (round_start, bp) =
            complete_prepared_operational_bp_transport(&store, &initial, &fixture)?;
        let [funding, claim, refund] = prepared_template_transactions(&fixture)?;
        let authority = store.prepare_operational_template_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &funding,
            &claim,
            &refund,
            &bp.statement,
            &fixture.recovery_capsule,
        )?;
        assert!(template_commit_payload_is_valid(
            authority.template_commit_payload()
        ));
        let first = sign_prepared_template_position(
            &store,
            &fixture,
            &round_start,
            0,
            authority.template_commit_payload(),
        )?;
        assert!(matches!(
            store.accept_transport_message_derived(&first),
            Err(SessionStoreError::InvalidTransition)
        ));
        assert_eq!(
            store.load_session(initial.session_id())?.as_bytes(),
            round_start.as_bytes()
        );
        assert!(matches!(
            store.accept_prepared_operational_template_transport_message(&authority, &first)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: false,
                ..
            })
        ));
        assert!(matches!(
            store.accept_prepared_operational_template_transport_message(&authority, &first)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        let after_first = store.load_session(initial.session_id())?;
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        assert!(matches!(
            reopened.accept_prepared_operational_template_transport_message(&authority, &first),
            Err(SessionStoreError::InvalidTransition)
        ));
        let resumed = reopened.prepare_operational_template_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &funding,
            &claim,
            &refund,
            &bp.statement,
            &fixture.recovery_capsule,
        )?;
        assert_eq!(
            resumed.template_commit_payload(),
            authority.template_commit_payload()
        );
        assert!(matches!(
            reopened.accept_prepared_operational_template_transport_message(&resumed, &first)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        let (terminal, second) =
            accept_prepared_template_position(&reopened, &resumed, &fixture, &after_first, 1)?;
        assert_eq!(terminal.phase(), SessionPhaseV1::TemplatesCommitted);
        assert_eq!(terminal.revision(), round_start.revision() + 2);
        assert!(matches!(
            reopened.accept_transport_message_derived(&second)?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        drop(reopened);

        let final_reopen = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        let final_authority = final_reopen.prepare_operational_template_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            initial.terms_hash(),
            &funding,
            &claim,
            &refund,
            &bp.statement,
            &fixture.recovery_capsule,
        )?;
        assert!(matches!(
            final_reopen.accept_prepared_operational_template_transport_message(
                &final_authority,
                &second,
            )?,
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                duplicate: true,
                ..
            })
        ));
        assert_eq!(
            final_reopen.load_session(initial.session_id())?.as_bytes(),
            terminal.as_bytes()
        );
        Ok(())
    }

