    #[test]
    #[ignore = "subprocess helper invoked by prepared transport crash recovery"]
    fn prepared_early_transport_crash_child() -> Result<(), Box<dyn Error>> {
        let parent =
            std::env::var_os("DOM_F7_SESSION_STORE_PARENT").ok_or(SessionStoreError::Filesystem)?;
        let parent_path = PathBuf::from(parent);
        let capability = Arc::new(Dir::from_std_file(File::open(&parent_path)?));
        let store = ContractsSessionStoreV1::open_evidence_only(
            capability,
            "sessions",
            policy(BudgetPolicyProfileV1::EvidenceOnly)?,
        )?;
        let current = store.load_session([0x31; 32])?;
        let initial = store.load_session_revision(current.session_id(), 0)?;
        let fixture = EarlyTransportTestFixture::new(&initial)?;
        let crash_cut = std::env::var("DOM_F7_SESSION_STORE_CRASH_CUT")?;
        if crash_cut == "bp-transport-after-authority-persist" {
            let payloads = PreparedOperationalBpPayloads::new(&initial, &fixture)?;
            let _authority = store.prepare_operational_bp_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &payloads.statement,
                &fixture.recovery_capsule,
            )?;
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        if crash_cut == "template-transport-after-authority-persist" {
            let bp = store.load_bp_transport_authority(initial.session_id())?;
            let funding = <Transaction as DomDeserialize>::from_bytes(&fs::read(
                parent_path.join("funding-template.bin"),
            )?)?;
            let claim = <Transaction as DomDeserialize>::from_bytes(&fs::read(
                parent_path.join("claim-template.bin"),
            )?)?;
            let refund = <Transaction as DomDeserialize>::from_bytes(&fs::read(
                parent_path.join("refund-template.bin"),
            )?)?;
            let _authority = store.prepare_operational_template_transport_authority(
                fixture.trusted_chain_id,
                initial.session_id(),
                initial.terms_hash(),
                &funding,
                &claim,
                &refund,
                &bp.statement,
                &fixture.recovery_capsule,
            )?;
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        let authority = store.prepare_early_transport_authority(
            fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        if crash_cut == "transport-after-equivocation-persist" {
            let conflicting_payload =
                EarlyTermsBindingV1::new(EarlyTermsMessageKindV1::Offer, [0x92; 32])?;
            let conflict = transport_signed_bytes(
                fixture.identity_key(0),
                *fixture.trusted_chain_id.as_bytes(),
                initial.session_id(),
                fixture.participant_ids[0],
                0,
                initial.transcript_hash(),
                0x01,
                &conflicting_payload.to_bytes(),
            )?;
            let _outcome = store.accept_prepared_early_transport_message(&authority, &conflict)?;
            return Err(Box::new(SessionStoreError::Quarantined));
        }
        let offer = transport_signed_bytes(
            fixture.identity_key(0),
            *fixture.trusted_chain_id.as_bytes(),
            initial.session_id(),
            fixture.participant_ids[0],
            0,
            initial.transcript_hash(),
            0x01,
            &authority.offer_payload()?,
        )?;
        let _outcome = store.accept_prepared_early_transport_message(&authority, &offer)?;
        Err(Box::new(SessionStoreError::Quarantined))
    }

    #[test]
    fn durable_transport_survives_restart_duplicate_reorder_and_equivocation(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let store = ContractsSessionStoreV1::create_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        let initial = record(SessionPhaseV1::Created)?;
        store.create_session(&initial)?;
        let alice = SecretKey::from_bytes(&[0x11; 32])?;
        let bob = SecretKey::from_bytes(&[0x12; 32])?;
        let alice_id = [0xa1; 32];
        let bob_id = [0xb2; 32];
        let chain_id = [0xc3; 32];
        store.bind_transport_roster(
            initial.session_id(),
            chain_id,
            [
                SessionTransportParticipantV1::new(
                    alice_id,
                    alice.public_key(),
                    DirectionV1::Initiator,
                )?,
                SessionTransportParticipantV1::new(
                    bob_id,
                    bob.public_key(),
                    DirectionV1::Responder,
                )?,
            ],
        )?;
        store.bind_transport_identity_references(
            initial.session_id(),
            [
                SessionTransportIdentityReferenceV1::new(
                    alice_id,
                    [0x31; 32],
                    [0x41; 32],
                    alice.public_key(),
                )?,
                SessionTransportIdentityReferenceV1::new(
                    bob_id,
                    [0x32; 32],
                    [0x42; 32],
                    bob.public_key(),
                )?,
            ],
        )?;
        let offer = transport_signed_bytes(
            &alice,
            chain_id,
            initial.session_id(),
            alice_id,
            0,
            initial.transcript_hash(),
            0x01,
            b"offer",
        )?;
        // Seed one already phase-validated record through the evidence-only
        // compatibility boundary. The production derived boundary may then
        // redeliver it, but may not admit an unseen opaque Offer.
        let parsed_offer = ParsedTransportEnvelopeV1::parse(&offer)?;
        let accepted_offer = initial.advance(
            initial.revision(),
            SessionPhaseV1::Created,
            accepted_transport_transcript_hash(
                &initial.transcript_hash(),
                &parsed_offer.message_digest,
                DirectionV1::Initiator,
                0x01,
                SessionPhaseV1::Created,
            )?,
            initial.irreversible(),
            initial.chain(),
            initial.encrypted_payload(),
        )?;
        let first = store.accept_transport_message(&offer, &accepted_offer, None)?;
        let first_receipt = match first {
            DurableTransportOutcomeV1::Accepted(receipt) => receipt,
            DurableTransportOutcomeV1::EquivocationPersisted => {
                return Err(Box::new(SessionStoreError::Quarantined));
            }
        };
        assert!(!first_receipt.duplicate);
        let successor = store.load_session(initial.session_id())?;
        assert_eq!(successor.revision(), 1);
        assert_eq!(successor.phase(), SessionPhaseV1::Created);
        assert_eq!(successor.transcript_hash(), first_receipt.transcript_hash);
        drop(store);
        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy,
        )?;
        let duplicate = reopened.accept_transport_message_derived(&offer)?;
        let duplicate_receipt = match duplicate {
            DurableTransportOutcomeV1::Accepted(receipt) => receipt,
            DurableTransportOutcomeV1::EquivocationPersisted => {
                return Err(Box::new(SessionStoreError::Quarantined));
            }
        };
        assert!(duplicate_receipt.duplicate);
        assert_eq!(
            duplicate_receipt.message_digest,
            first_receipt.message_digest
        );
        assert_eq!(
            duplicate_receipt.transcript_hash,
            first_receipt.transcript_hash
        );

        let gap = transport_signed_bytes(
            &alice,
            chain_id,
            initial.session_id(),
            alice_id,
            2,
            successor.transcript_hash(),
            0x01,
            b"gap",
        )?;
        assert!(matches!(
            reopened.accept_transport_message_derived(&gap),
            Err(SessionStoreError::InvalidTransition)
        ));

        let different = transport_signed_bytes(
            &alice,
            chain_id,
            initial.session_id(),
            alice_id,
            0,
            initial.transcript_hash(),
            0x01,
            b"different",
        )?;
        assert_eq!(
            reopened.accept_transport_message_derived(&different)?,
            DurableTransportOutcomeV1::EquivocationPersisted
        );
        assert_eq!(
            reopened.load_session(initial.session_id())?.phase(),
            SessionPhaseV1::FailedClosed
        );
        Ok(())
    }

    #[test]
    fn derived_transport_refuses_every_unprepared_new_message_kind() -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let store = ContractsSessionStoreV1::create_evidence_only(
            temporary.capability()?,
            "sessions",
            policy(BudgetPolicyProfileV1::EvidenceOnly)?,
        )?;
        let initial = record(SessionPhaseV1::Created)?;
        store.create_session(&initial)?;
        let alice = SecretKey::from_bytes(&[0x21; 32])?;
        let bob = SecretKey::from_bytes(&[0x22; 32])?;
        let alice_id = [0xa1; 32];
        let bob_id = [0xb2; 32];
        let chain_id = [0xc3; 32];
        store.bind_transport_roster(
            initial.session_id(),
            chain_id,
            [
                SessionTransportParticipantV1::new(
                    alice_id,
                    alice.public_key(),
                    DirectionV1::Initiator,
                )?,
                SessionTransportParticipantV1::new(
                    bob_id,
                    bob.public_key(),
                    DirectionV1::Responder,
                )?,
            ],
        )?;
        store.bind_transport_identity_references(
            initial.session_id(),
            [
                SessionTransportIdentityReferenceV1::new(
                    alice_id,
                    [0x31; 32],
                    [0x41; 32],
                    alice.public_key(),
                )?,
                SessionTransportIdentityReferenceV1::new(
                    bob_id,
                    [0x32; 32],
                    [0x42; 32],
                    bob.public_key(),
                )?,
            ],
        )?;

        for message_type in 0x01..=0x14 {
            let (signer, sender_id) = if message_type == 0x02 {
                (&bob, bob_id)
            } else {
                (&alice, alice_id)
            };
            let candidate = transport_signed_bytes(
                signer,
                chain_id,
                initial.session_id(),
                sender_id,
                0,
                initial.transcript_hash(),
                message_type,
                b"opaque-unprepared-payload",
            )?;
            assert!(matches!(
                store.accept_transport_message_derived(&candidate),
                Err(SessionStoreError::InvalidTransition)
            ));
            assert_eq!(
                store.load_session(initial.session_id())?.as_bytes(),
                initial.as_bytes()
            );
        }
        Ok(())
    }

    #[test]
    fn evidence_only_caller_shaped_early_prefix_remains_recoverable() -> Result<(), Box<dyn Error>>
    {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (created, initial, fixture) = early_transport_store(&temporary, &evidence_policy)?;
        let roster = created.load_transport_roster(initial.session_id())?;

        // Build the canonical context entirely in memory. It is used only to
        // prove the six legacy payloads are genuine; no prepared authority is
        // persisted into the evidence-only migration Store.
        let model = EarlyTransportAuthorityRecordV1::new(
            &initial,
            &roster,
            &fixture.trusted_chain_id,
            [&fixture.shared_bindings[0], &fixture.shared_bindings[1]],
        )?;
        let payloads =
            EarlyTransportPayloads::from_context(&initial, &fixture, model.context_commitment)?;
        let mut commitments = [None, None];
        for position in 0..6 {
            let expected = early_transport_expected_item(position, &roster)?;
            validate_early_transport_payload(
                &model,
                expected,
                expected.sender_id,
                expected.message_type,
                payloads.message(position),
                &mut commitments,
            )?;
        }
        assert!(matches!(
            created.load_early_transport_authority(initial.session_id()),
            Err(SessionStoreError::SessionNotFound)
        ));

        let mut store = created;
        let mut current = initial;
        for position in 0..6 {
            let signed = sign_early_transport_position(
                &fixture,
                &current,
                position,
                payloads.message(position),
            )?;
            let envelope = ParsedTransportEnvelopeV1::parse(&signed)?;
            let participant = roster
                .participants
                .iter()
                .find(|candidate| candidate.participant_id == envelope.sender_id)
                .ok_or(SessionStoreError::Canonical)?;
            let expected = early_transport_expected_item(position, &roster)?;
            let successor = current.advance(
                current.revision(),
                expected.phase,
                accepted_transport_transcript_hash(
                    &current.transcript_hash(),
                    &envelope.message_digest,
                    participant.direction,
                    envelope.message_type,
                    expected.phase,
                )?,
                current.irreversible(),
                current.chain(),
                current.encrypted_payload(),
            )?;
            assert!(matches!(
                store.accept_transport_message(&signed, &successor, None)?,
                DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                    duplicate: false,
                    ..
                })
            ));
            assert_eq!(
                store.load_session(successor.session_id())?.as_bytes(),
                successor.as_bytes()
            );
            drop(store);

            store = ContractsSessionStoreV1::open_evidence_only(
                temporary.capability()?,
                "sessions",
                evidence_policy.clone(),
            )?;
            assert!(matches!(
                store.accept_transport_message(&signed, &successor, None)?,
                DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                    duplicate: true,
                    ..
                })
            ));
            assert_eq!(
                store.load_session(successor.session_id())?.as_bytes(),
                successor.as_bytes()
            );
            assert!(matches!(
                store.load_early_transport_authority(successor.session_id()),
                Err(SessionStoreError::SessionNotFound)
            ));
            current = successor;
        }
        assert_eq!(current.revision(), 6);
        assert_eq!(current.phase(), SessionPhaseV1::SharesRevealed);
        Ok(())
    }

    #[test]
    fn caller_shaped_transport_is_evidence_only_and_refuses_late_protocol_messages(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let initial = record(SessionPhaseV1::Created)?;
        let alice = SecretKey::from_bytes(&[0x21; 32])?;
        let alice_id = [0xa1; 32];
        let chain_id = [0xc3; 32];

        let evidence_store = ContractsSessionStoreV1::create_evidence_only(
            temporary.capability()?,
            "evidence-ingress",
            policy(BudgetPolicyProfileV1::EvidenceOnly)?,
        )?;
        evidence_store.create_session(&initial)?;
        for message_type in 0x0b..=0x14 {
            let candidate = transport_signed_bytes(
                &alice,
                chain_id,
                initial.session_id(),
                alice_id,
                0,
                initial.transcript_hash(),
                message_type,
                b"caller-shaped-late-payload",
            )?;
            assert!(matches!(
                evidence_store.accept_transport_message(&candidate, &initial, None),
                Err(SessionStoreError::InvalidTransition)
            ));
            assert_eq!(
                evidence_store
                    .load_session(initial.session_id())?
                    .as_bytes(),
                initial.as_bytes()
            );
            assert_eq!(
                evidence_store.transport_message_count(initial.session_id())?,
                0
            );
        }

        let production_store = ContractsSessionStoreV1::create_production(
            temporary.capability()?,
            "production-ingress",
            policy(BudgetPolicyProfileV1::ProductionRatified)?,
        )?;
        let imported_prefunding = record(SessionPhaseV1::SharesCommitted)?;
        assert!(matches!(
            production_store.create_session(&imported_prefunding),
            Err(SessionStoreError::InvalidTransition)
        ));
        let offer = transport_signed_bytes(
            &alice,
            chain_id,
            initial.session_id(),
            alice_id,
            0,
            initial.transcript_hash(),
            0x01,
            b"caller-shaped-production-offer",
        )?;
        assert!(matches!(
            production_store.accept_transport_message(&offer, &initial, None),
            Err(SessionStoreError::PolicyProfile)
        ));
        Ok(())
    }

    #[test]
    fn caller_shaped_mutators_are_selected_by_store_profile_not_unit_build(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let production_store = ContractsSessionStoreV1::create_production(
            temporary.capability()?,
            "production-mutators",
            policy(BudgetPolicyProfileV1::ProductionRatified)?,
        )?;
        let production_initial = record(SessionPhaseV1::Created)?;
        production_store.create_session(&production_initial)?;
        assert!(matches!(
            production_store.advance_session(0, &production_initial),
            Err(SessionStoreError::PolicyProfile)
        ));
        assert!(matches!(
            production_store.issue_funding_authorization(
                0,
                &production_initial,
                verified_for_test(&production_initial),
            ),
            Err(SessionStoreError::PolicyProfile)
        ));

        let evidence_store = ContractsSessionStoreV1::create_evidence_only(
            temporary.capability()?,
            "evidence-mutators",
            policy(BudgetPolicyProfileV1::EvidenceOnly)?,
        )?;
        let claim_prepared = record(SessionPhaseV1::ClaimPrepared)?;
        evidence_store.create_session(&claim_prepared)?;
        let (ready_to_fund, funding_broadcast) = funding_successors(&claim_prepared)?;
        let authorization = evidence_store.issue_funding_authorization(
            claim_prepared.revision(),
            &ready_to_fund,
            verified_for_test(&claim_prepared),
        )?;
        assert!(matches!(
            production_store.consume_funding_authorization(authorization, &funding_broadcast),
            Err(SessionStoreError::PolicyProfile)
        ));
        assert_eq!(
            production_store
                .load_session(production_initial.session_id())?
                .as_bytes(),
            production_initial.as_bytes()
        );
        Ok(())
    }

    #[test]
    fn contracts_identity_public_references_survive_restart_and_tamper_fails_closed(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let store = ContractsSessionStoreV1::create_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        let initial = record(SessionPhaseV1::Created)?;
        store.create_session(&initial)?;
        let alice = SecretKey::from_bytes(&[0x21; 32])?;
        let bob = SecretKey::from_bytes(&[0x22; 32])?;
        let alice_id = [0xa1; 32];
        let bob_id = [0xb2; 32];
        let chain_id = [0xc3; 32];
        store.bind_transport_roster(
            initial.session_id(),
            chain_id,
            [
                SessionTransportParticipantV1::new(
                    alice_id,
                    alice.public_key(),
                    DirectionV1::Initiator,
                )?,
                SessionTransportParticipantV1::new(
                    bob_id,
                    bob.public_key(),
                    DirectionV1::Responder,
                )?,
            ],
        )?;
        let wrong_identity = SecretKey::from_bytes(&[0x23; 32])?;
        assert!(matches!(
            store.bind_transport_identity_references(
                initial.session_id(),
                [
                    SessionTransportIdentityReferenceV1::new(
                        alice_id,
                        [0x31; 32],
                        [0x41; 32],
                        wrong_identity.public_key(),
                    )?,
                    SessionTransportIdentityReferenceV1::new(
                        bob_id,
                        [0x32; 32],
                        [0x42; 32],
                        bob.public_key(),
                    )?,
                ]
            ),
            Err(SessionStoreError::Canonical)
        ));
        store.bind_transport_identity_references(
            initial.session_id(),
            [
                SessionTransportIdentityReferenceV1::new(
                    alice_id,
                    [0x31; 32],
                    [0x41; 32],
                    alice.public_key(),
                )?,
                SessionTransportIdentityReferenceV1::new(
                    bob_id,
                    [0x32; 32],
                    [0x42; 32],
                    bob.public_key(),
                )?,
            ],
        )?;
        let loaded = store.transport_identity_references(initial.session_id())?;
        assert_eq!(loaded[0].key_reference(), &[0x31; 32]);
        assert_eq!(loaded[1].noise_public_key(), &[0x42; 32]);
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        let loaded = reopened.transport_identity_references(initial.session_id())?;
        assert_eq!(loaded[0].participant_id(), &alice_id);
        assert_eq!(loaded[1].schnorr_public_key(), &bob.public_key());
        drop(reopened);

        let path = temporary
            .path()
            .join("sessions")
            .join(ROSTERS_NAME)
            .join(transport_identity_binding_name(initial.session_id()));
        let mut bytes = fs::read(&path)?;
        bytes[96] ^= 0x80;
        fs::write(path, bytes)?;
        assert!(matches!(
            ContractsSessionStoreV1::open_evidence_only(
                temporary.capability()?,
                "sessions",
                evidence_policy
            ),
            Err(SessionStoreError::Quarantined)
        ));
        Ok(())
    }

