    fn operational_abort_sender_index(
        fixture: &EarlyTransportTestFixture,
        authority: &PreparedOperationalAbortTransportAuthorityV1,
    ) -> Result<usize, SessionStoreError> {
        fixture
            .participant_ids
            .iter()
            .position(|participant_id| participant_id == &authority.canonical_sender_id)
            .ok_or(SessionStoreError::Canonical)
    }

    fn signed_operational_abort(
        fixture: &EarlyTransportTestFixture,
        authority: &PreparedOperationalAbortTransportAuthorityV1,
    ) -> Result<Vec<u8>, Box<dyn Error>> {
        let sender = operational_abort_sender_index(fixture, authority)?;
        transport_signed_bytes(
            fixture.identity_key(sender),
            *fixture.trusted_chain_id.as_bytes(),
            authority.session_id,
            authority.canonical_sender_id,
            authority.canonical_sender_sequence,
            authority.predecessor_transcript_hash,
            0x13,
            authority.abort_binding_digest(),
        )
    }

    fn require_new_abort_acceptance(
        outcome: DurableTransportOutcomeV1,
    ) -> Result<(), Box<dyn Error>> {
        match outcome {
            DurableTransportOutcomeV1::Accepted(DurableTransportReceiptV1 {
                message_type: 0x13,
                duplicate: false,
                ..
            }) => Ok(()),
            _ => Err(Box::new(SessionStoreError::Quarantined)),
        }
    }

