    #[test]
    fn store_issued_abort_outbound_is_durable_exact_and_restart_revalidates(
    ) -> Result<(), Box<dyn Error>> {
        let temporary = TestDirectory::create()?;
        let evidence_policy = policy(BudgetPolicyProfileV1::EvidenceOnly)?;
        let (store, initial, fixture) =
            operational_abort_store(&temporary, &evidence_policy, SessionPhaseV1::Created)?;
        let authority = store.prepare_operational_abort_transport_authority(
            fixture.trusted_chain_id,
            initial.session_id(),
            [0xd4; 32],
        )?;
        let sender = operational_abort_sender_index(&fixture, &authority)?;
        let key_reference = if sender == 0 { [0x31; 32] } else { [0x32; 32] };
        let other_reference = if sender == 0 { [0x32; 32] } else { [0x31; 32] };
        store.bind_local_transport_signer(initial.session_id(), key_reference)?;
        assert_eq!(
            store.bind_local_transport_signer(initial.session_id(), other_reference),
            Err(SessionStoreError::Conflict)
        );

        let mut tampered = store
            .prepare_abort_dsc1_signing_request(&authority)?
            .ok_or(SessionStoreError::Quarantined)?;
        assert_eq!(tampered.chain_id(), fixture.trusted_chain_id.as_bytes());
        assert_eq!(tampered.session_id(), &initial.session_id());
        assert_eq!(tampered.sender_id(), &fixture.participant_ids[sender]);
        assert_eq!(tampered.message_type(), 0x13);
        assert_eq!(tampered.payload(), authority.abort_binding_digest());
        assert_eq!(tampered.signer_key_reference(), &key_reference);
        let unsigned = encode_canonical_unsigned_dsc1(&OutboundDsc1UnsignedFieldsV1 {
            message_type: tampered.message_type(),
            chain_id: *tampered.chain_id(),
            session_id: *tampered.session_id(),
            sender_id: *tampered.sender_id(),
            sequence: tampered.sequence(),
            previous_transcript_hash: *tampered.previous_transcript_hash(),
            payload: tampered.payload(),
        })?;
        assert_eq!(
            tampered.unsigned_message_digest(),
            &tagged_hash(TRANSPORT_MESSAGE_DIGEST_TAG, &unsigned)
        );
        assert_ne!(tampered.request_id(), &[0; 32]);
        let retained_root = temporary.path().join("sessions").join(ROSTERS_NAME);
        assert_eq!(
            fs::metadata(
                retained_root.join(local_transport_signer_binding_name(initial.session_id()))
            )?
            .permissions()
            .mode()
                & 0o777,
            0o600
        );
        assert_eq!(
            fs::metadata(retained_root.join(outbound_dsc1_request_name(
                initial.session_id(),
                *tampered.sender_id(),
                tampered.sequence(),
            )))?
            .permissions()
            .mode()
                & 0o777,
            0o600
        );
        store.revalidate_prepared_outbound_dsc1(&tampered)?;
        tampered.payload[0] ^= 1;
        assert_eq!(
            store.revalidate_prepared_outbound_dsc1(&tampered),
            Err(SessionStoreError::InvalidTransition)
        );

        let request = store
            .prepare_abort_dsc1_signing_request(&authority)?
            .ok_or(SessionStoreError::Quarantined)?;
        let signed = transport_signed_bytes(
            fixture.identity_key(sender),
            *request.chain_id(),
            *request.session_id(),
            *request.sender_id(),
            request.sequence(),
            *request.previous_transcript_hash(),
            request.message_type(),
            request.payload(),
        )?;
        let committed = store.commit_prepared_outbound_dsc1(request, &signed)?;
        assert_ne!(committed.application_id(), &[0; 32]);
        assert_eq!(committed.session_id(), &initial.session_id());
        assert_eq!(committed.sender_id(), &fixture.participant_ids[sender]);
        assert_eq!(committed.signed_bytes(), signed);
        assert_eq!(
            fs::metadata(retained_root.join(outbound_dsc1_committed_name(
                initial.session_id(),
                *committed.sender_id(),
                committed.sequence(),
            )))?
            .permissions()
            .mode()
                & 0o777,
            0o600
        );
        store.revalidate_committed_outbound_dsc1(&committed)?;
        let stale = store
            .load_committed_outbound_dsc1(
                initial.session_id(),
                *committed.sender_id(),
                committed.sequence(),
            )?
            .issued_handle(store.open_instance_id);
        assert_eq!(
            store.load_session(initial.session_id())?.phase(),
            SessionPhaseV1::Aborted
        );
        let replay = match store.resume_outbound_dsc1(initial.session_id())? {
            OutboundDsc1RecoveryV1::Committed(resumed) => {
                assert_eq!(resumed.application_id(), committed.application_id());
                assert_eq!(resumed.signed_bytes(), signed);
                store.revalidate_committed_outbound_dsc1(&resumed)?;
                *resumed
            }
            OutboundDsc1RecoveryV1::SigningRequest(_) | OutboundDsc1RecoveryV1::None => {
                return Err(Box::new(SessionStoreError::Quarantined))
            }
        };
        store.complete_outbound_dsc1_relay_handoff(committed)?;
        assert_eq!(
            fs::metadata(retained_root.join(outbound_dsc1_reconciled_name(
                initial.session_id(),
                fixture.participant_ids[sender],
                replay.sequence(),
            )))?
            .permissions()
            .mode()
                & 0o777,
            0o600
        );
        store.complete_outbound_dsc1_relay_handoff(replay)?;
        assert!(matches!(
            store.resume_outbound_dsc1(initial.session_id())?,
            OutboundDsc1RecoveryV1::None
        ));
        drop(store);

        let reopened = ContractsSessionStoreV1::open_evidence_only(
            temporary.capability()?,
            "sessions",
            evidence_policy.clone(),
        )?;
        assert_eq!(
            reopened.revalidate_committed_outbound_dsc1(&stale),
            Err(SessionStoreError::InvalidTransition)
        );
        assert!(matches!(
            reopened.resume_outbound_dsc1(initial.session_id())?,
            OutboundDsc1RecoveryV1::None
        ));
        drop(reopened);
        let marker_path = retained_root.join(outbound_dsc1_reconciled_name(
            initial.session_id(),
            fixture.participant_ids[sender],
            stale.sequence(),
        ));
        let mut marker = fs::read(&marker_path)?;
        marker[216] ^= 1;
        fs::write(marker_path, marker)?;
        assert!(matches!(
            ContractsSessionStoreV1::open_evidence_only(
                temporary.capability()?,
                "sessions",
                evidence_policy,
            ),
            Err(SessionStoreError::Quarantined)
        ));
        Ok(())
    }

